window.__D("text/torat-shmuel/c031",{"p":[[2000460118,"והיינו שבמקום זה האיר בחי' זה הוי' קוינו לו רק שהוא דרך מעביר הבריאה כו' ועיקר הגילוי הי' מאצי' כו', ולכן אמר שמקום זה הוא מקום בהמ\"ק חלוק הוא מכל הארץ לפי שבבהמ\"ק האיר ג' ראשונות וכבוד הוי' מלא וכמ\"ש בסש\"ב בח\"א בסופו ע\"ש בענין בית ראשון ובסידור בשער הת\"ת בענין תלמוד בבריאה<sup data-n=\"134\">10</sup> שהוא ביאור על הסש\"ב הנ\"ל.\n<b>ולהבין</b> בתוס' ביאור ענין בחי' חולין שנעשו עטה\"ק יש להעיר לענין חול וחולין ממ\"ש גבי נדרים לא יחל דברו, ושרש ענין הנדרים בקצרה<sup data-n=\"135\">11</sup> שנדרים סייג לפרישות, והיינו מפני כי לא יכול להעלות הניצוץ שבדבר הנדור, ע\"כ ההכרח לדחותו, ואוסר ע\"ע הדבר הנדור בנדר, ונודע כי הנדרים הם מבינה ששם הו\"ע הנדרים, וזהו שארז\"ל כל הנודר כאלו נודר בחיי המלך, מלך הוא ז\"א וחיי המלך הוא מבינה, בחי' אלקי' חיים ומלך עולם כו' כמ\"ש במ\"א<sup data-n=\"136\">12</sup>, וכשמקבל עליו בנדר, ע\"ז בא האזהרה שלא יחל דברו הוא דבר הנדר, כי ע\"י דבורו ממשיך על דבר הנדור מקיף דקדושה, דוגמת מקיף דלבונה זכה שאין קדש מתערב בחול, אמנם החכם שמתיר הנדר מיחל דברו שאסר ע\"ע ומתיר לו נדרו, והיינו מפני כי בחכ' אתברירו, ויכול לברר ולהעלות הניצוץ, ולדחות הרע, ואז החולין הם חולין שנעשו על טהרת הקדש. נמצא להוסיף מחול על הקדש, היינו לברר ולהעלות הניצוץ שהי' בדבר הנדור, זהו ע\"י בחכמה אתברירו, וזהו שא\"ל שמואל לרב יהודה (בפ\"ה דערובין דנ\"ד ע\"א) שיננא חטוף ואכול חטוף ואישתי דעלמא כו' כהילולא דמי, פי' ר\"ל שלא יאכל לתיאבון וישאר הניצוץ מקושר בק\"נ כמקדם אלא יחטוף אותו מק\"נ, והיינו ע\"י היותו שיננא, ובחכמה אתברירו כנ\"ל, ובערוך ערך שן הב' פי' שיננא מחודד בתלמוד מלשון חץ שנון עכ\"ל, ואפ\"ל שלכן רב יהודה כולא תנויי בנזיקין הוה, בכדי לחטוף הניצוצות מד' אבות נזיקין, וכן דיני ממונות הם בסדר נזיקין שהרוצה שיחכם יעסוק בדיני ממונות, וע\"י היותו מחכים הנה בחכ' אתברירו להציל העשוק מיד עושקו שזהו עיקר ענין דיני ממונות, להיות עושה משפט לעשוקים כו', וכמ\"ש במ\"א בענין משפט וצדקה ביעקב אתה כו' ע' בת\"א פ' בשלח בד\"ה אשירה להוי'<sup data-n=\"137\">13</sup>, שזהו מה שנק' סדר נזיקין ישועות כמ\"ש במ\"א<sup data-n=\"138\">14</sup>, ולכן א\"ל חטוף כו', משא\"כ ע\"ה אסור לאכול בשר לפי שאינו יכול לחוטפו מק\"נ כו', ולכן על שבת ארז\"ל במכילתא ע\"פ זכור את יוה\"ש, הובא בילקוט ע\"פ הנ\"ל זכור מלפניו ושמור מלאחריו משל",[["134","10","<b>וכמ\"ש בסש\"ב בח\"א בסופו. . ובסידור בשער הת\"ת בענין תלמוד בבריאה</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא</a> פנ\"ב-נ\"ג. סידור עם דא\"ח צז, ג ואילך."],["135","11","<b>ושרש ענין הנדרים בקצרה</b>: בהבא לקמן ראה בארוכה לקמן ד\"ה וידבר גו' המטות. [ובהנסמן בהע' שלאח\"ז]."],["136","12","<b>כאלו נודר בחיי המלך. . כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610223\" data-slug=\"or-hatorah-hb\" data-id=\"8316610223\">אוה\"ת</a> מטות ע' א'שכו ואילך. וראה אוה\"ת ויצא (כרך ד) תתנב, א ואילך. סה\"מ תרל\"ג ח\"ב ס\"ע תלה ואילך."],["137","13","<b>במ\"א בענין משפט וצדקה. . ע' בת\"א פ' בשלח בד\"ה אשירה להוי'</b>: דף סג, ב."],["138","14","<b>שזהו מה שנק' סדר נזיקין ישועות כמ\"ש במ\"א</b>: ראה אוה\"ת דרושים לשבועות ע' עג ואילך. ע' פ ואילך. סה\"מ תרכ\"ז ע' תצו ואילך (הוצאת תש\"ס). תרל\"ב ח\"ב ע' תמג. ועוד."]]],[2000460119,"לזאב שטורף מלפניו ומלאחריו, וטריפתו זהו שחוטף שה מהעדר, והיינו כי שבת הוא בחי' מוחין דאבא, ולכן צריכין להוסיף בו מחול על הקדש מלפניו ומלאחריו, כזאב שחוטף בשר הבהמה כן צריכי' לחטוף מן החול ולהוסיף בבחי' קדש דשבת, כי בחכמה דוקא אתברירו לחטוף מן החול שיוכלל בבחי' הקדש דשבת כו', וכמו החכם שמייחל הדבור ומתיר הנדר שהניצוץ שהי' בו יתעלה כו' מחול לקדש להיות בחי' חולין שנעשו על טהרת הקדש כו'. וגם י\"ל חול, חולין הוא ע\"ד דכתי' במשה ויחל משה, וארז\"ל ברבות פ' תשא פמ\"ג שעשה מהמר מתוק, כי ויחל פירושו ג\"כ לשון מתיקות, והיינו שכאשר בחכמה אתברירו מתגלה המתיקות ותענוג עליון שנפל בשה\"כ ויוצא מק\"נ, וי\"ל שבשבת ע\"י זכור מלפניו ושמור מלאחריו עי\"ז נמשך תוס' בחי' תענוג עליון בסעודות דשבת, בחי' אז תתענג כו', וקראת לשבת ענג, ע\"י שחוטף מהחול כו'.\n<b>ובזה</b> יובן מה שר' יהודה הוי' קארי לי' (לרבו רשב\"י) שבת, וכי מה ענין זל\"ז. ועפמש\"נ כאן שהחכם מתיר הנדר שמעלה הניצוץ, וכן שבת חוטף מחול הניצוץ, נמצא ענין א' להם.\n<b>ואמנם</b> לתרץ שני מאה\"ז הנ\"ל מה שלפעמים משמע שששת ימי החול הם במט\"ט כמשנ\"ת לעיל ממאמר הזהר פ' אמור דצ\"ד ע\"ב, ולפעמי' משמע שששת ימי החול הם מק\"נ, כמשנ\"ת לעיל שההבדלה שבין קדש לחול זהו בין עשייה לק\"נ, והוא מהזהר פ' פקודי דרכ\"ז הנ\"ל, ולכאו' איך יתכן שניהם, ובאמת פי' שני מאמרי הזהר אלו הם בשם נ\"ב שהוא מהרח\"ו ז\"ל. אך הענין יובן ע\"פ מ\"ש בר\"ח שער הקדושה פ\"ב, אשר ביאר ע\"פ מאה\"ז פ' ויקהל דף ר\"ד ע\"א, ת\"ח אית ימים ואית ימים, ימי חול כמה דאתמר, ואלין קיימין לבר כו', ימי השבת דאינון ימי השבוע קיימין לישראל, וכוונתו שהם שלשה מיני ימים, האחד ימי חול דקיימין לבר, היינו שהם עומדים חוץ לקדושה (וזהו אלף ימי' דחול שנת' בזח\"ב פקודי דרכ\"ז ע\"ב, והיינו כמו שפי' המק\"מ שם בשם נ\"ב שזהו ע\"ס דנוגה), והשליט על ישראל הנהגת קדושה ע\"י מט\"ט כו' וששת ימי החול ההנהגה ע\"י מט\"ט כו' דאיהו עבד דשליט בשיתא סדרי משנה כו' (וזהו ששת ימי החול דאתנהיג עלמא ע\"י דשלוחייהו שא' ר' יוסי בזח\"ג אמור דצ\"ד ע\"ב, שנת' לעיל שזהו בחי' ו\"ק דיצי' וגם ו\"ק דעשיי', שהם מט\"ט וסנדל כנ\"ל), אמנם בשבת שולט אור האצי' כו' והעוסקים בתומ\"צ הם קושרים בימי החול ו\"ק של שש היכלות (היינו היכלות דיצי', ואפשר גם דעשיי') בששה ספירות הבנין שבאצי' שהם ששת ימים עשה ה' את השמים ואת הארץ (שהם מחסד דאצי' עד יסוד שהם פעלו כל מעשה בראשית כדפי' בזהר פ' בראשית, כי ששת ימים עשה, בששת לא נאמר כו') והיינו ע\"י כוונת התפלה, כמבואר בזהר פ' פקודי שע\"י כוונת ברכת ק\"ש ותפלת י\"ח מתקשרים ומאירים ההיכלות מאור האצילות, ובזה אנו מפרידים הטוב מהרע, והטוב מתקדש באור הטוב שבאצי' ובזה הם נשמרים מהרע, ע\"כ דברי הר\"ח."],[2000460120,"<b>וביאור</b> הענין ממ\"ש במ\"א שכל התומ\"צ מתעלי' ע\"י התפילה<sup data-n=\"139\">15</sup> שהיא כנגד עולת התמיד שע\"י מתעלי' התומ\"צ שהם המלאכי אלקי' שעולים בסולם דתפילה, ובאמת גם התפילה דחול מתעלית ע\"י התפילה דשבת, וכמ\"ש עולת שבת כו' שהיא על עולת התמיד כו' כמ\"ש במ\"א<sup data-n=\"140\">16</sup>, וז\"ע מה שמט\"ט קושר כתרי' לקונו מתפלותי' ש\"י, ופעם אמרו סנד\"ל קושר כתרים שזהו לפי הבדל הנ\"ל שנת' בחילוקי הארצות כו'. והענין הוא כמ\"ש במ\"א בענין לב מלכים אין חקר ובכדי שיפנה לבקשות ההדיוט זהו ע\"י שמביאי' דבר חדש כו' והדבר חדש הוא ביטול היש<sup data-n=\"141\">17</sup>, כי משמי' מיהב יהבא משקל כו' כנ\"ל, והוא ע\"י היותו ניזון מדברי' גשמיי' וחייו חיי בשרי ועכ\"ז יבא לבחי' הביטול ה\"ז יקר מאד בעיני ה' כו' ולכן המלאכי' הנ\"ל ע\"י דגפיף להון כו' שמזככים האותיות עושי' כתרי' כו' וכמו שהכתר הוא מאבני' טובות המאירים כו' כן זהו דוקא מאותיות התפילה שנק' אבנים, וכשהם טובות פי' שמאירי' מאור האהוי\"ר עושי' מזה כתרי' כו'. וגם ענין הכתרי' לפי שכל דברי' הגשמיי' מקבלי' חיותם מנוגה, וכשמתבררים מתברר הי\"ס דנוגה שנק' כתרין ושרשם מתהו כו' לכן עושי' מזה כתרים בבחי' התיקון כו'. ונמצא מובן דברי הר\"ח הנ\"ל שהעוסקים בתומ\"צ מ\"מ עיקר יחודם הוא ע\"י כוונת ק\"ש ותפילה כו', ומתורץ ג\"כ שני מאמה\"ז הנ\"ל, שהבירור שבנוגה זהו היומין דקיימין לבר, ומה שו\"ק דיצי' נק' ג\"כ חול זהו הכונה על שתא סדרי משנה, עבד דשלטא כו' שע\"פ מה שנת' לעיל בענין מארז\"ל כל שלמה<sup data-n=\"142\">18</sup> כו' חוץ מזה דהאלף לך שלמה הוא חול, שזהו ע\"ד שנת' באגה\"ק סי' ך\"ו בענין אילנא דטו\"ר. ומ\"מ מובן שא\"א לדמות בחי' חול זה לבחי' חול שבי\"ס דנוגה, ובשבת שולט מל' דאצי', ומקבלת מהבינה שהיא נק' שביעאה כו', והשראתה בהיכל קד\"ק דבריאה שלמעלה מבחי' מט\"ט ו\"ק דיצי' כו', וקרוב להיות ע\"ד השראת השכינה בב\"ר כמ\"ש בסש\"ב בענין תלמוד בבריאה, וצ\"ע.\n<b>ועפ\"ז</b> יובן דברי התרגומים הנ\"ל, שיונתן תרגם לית דין אתר חול, צ\"ל שכוונתו גם על בחי' חול דמט\"ט שהוא בחי' ו\"ק דיצי' הנ\"ל, וכוונתו שבבחי' מקום זה שפגע יעקב וילן שם, אינו נמשך ע\"י בחי' מט\"ט שרו ש\"ע כמו בבאר שבע עד\"מ, אלא שזהו מקום המקדש ששם היתה השראת שכינה וגילוי ש' הוי', ולכן במקדש היו קורי' השם ככתבו, גם בלתי כינוי ש' אד' ג\"כ, מפני עוצם הגילוי שהי' מאיר בבהמק\"ד, ויעקב הרגיש זה כו'. והת\"א מפרש עוד יותר, באמרו לית דין אתר הדיוט, שהכוונה שלא תטעה בפי' לשון חול, שיש חול שפי' י\"ס דנוגה כנ\"ל מהזח\"ב",[["139","15","<b>ממ\"ש במ\"א שכל התומ\"צ מתעלי' ע\"י התפילה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370338\" data-slug=\"torah-or\" data-id=\"3901370338\">תו\"א משפטים עו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380264\" data-slug=\"likkutei-torah\" data-id=\"4001380264\">לקו\"ת בהר מד, א</a>. סה\"מ תרל\"ג ח\"ב ע' שמא."],["140","16","<b>וכמ\"ש עולת שבת כו' שהיא על עולת התמיד כו' כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370357\" data-slug=\"torah-or\" data-id=\"3901370357\">תו\"א תרומה פ, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380264\" data-slug=\"likkutei-torah\" data-id=\"4001380264\">מד, א</a>. סה\"מ תרל\"ב ח\"א ע' נח. ובכ\"מ."],["141","17","<b>כמ\"ש במ\"א בענין לב מלכים. . והדבר חדש הוא ביטול היש</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370120\" data-slug=\"torah-or\" data-id=\"3901370120\">תו\"א וישלח כה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380388\" data-slug=\"likkutei-torah\" data-id=\"4001380388\">לקו\"ת במדבר כ, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380507\" data-slug=\"likkutei-torah\" data-id=\"4001380507\">שלח מח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381276\" data-slug=\"likkutei-torah\" data-id=\"4001381276\">שה\"ש לז, א</a>. דרמ\"צ קנט, ב. סה\"מ תרכ\"ח ע' נא. ע' רצג. ע' שצ. ע' תסה. וש\"נ."],["142","18","<b>שנת' לעיל בענין מארז\"ל כל שלמה</b>: בד\"ה ואמנם עדיין צ\"ל כו' האלף לך שלמה."]]],[2000460121,"פקודי דרכ\"ז, (והגם שא\"א לומר כן שהרי בכל א\"כ<sup data-n=\"143\">19</sup> מאיר ע\"י בחי' ו\"ק דיצי', וא\"כ א\"א לפרש על בחי' חול די\"ס דק\"נ, מ\"מ ביאר יותר) והוא במה שפי' לית דין אתר הדיוט, כנודע מאמרם ז\"ל על מט\"ט שש\"ע הדיוט איהו לגבי מארי', וא\"כ נתן סימן על איזהו חול כוונתו שלית דין אתר חול דבחי' מט\"ט שנק' הדיוט לגבי מארי', והיינו כמו שנמשך ההנהגה בכל א\"כ ע\"י עבדו זקן ביתו, אלא דרעוא בי' מן קדם הוי', שיש לפרש כונתו על ענין עמוק מאד, שפי' קדם הוי' הוא ע\"ד לפני הוי' שבסדר השתלשלות בחי' תורת הוי' מצות הוי', תטהרו היינו בחי' כתר כמ\"ש במ\"א שתטהרו בגימ' כתר<sup data-n=\"144\">20</sup>, והיינו ש' הוי' שלפני ההשתלשלות כו', ולכן ביוהכ\"פ כתי' וכפר על הקדש ג\"כ, וכמ\"ש במ\"א בענין מקדש הקדש וקדש<sup data-n=\"145\">21</sup> כו', והיינו שביוהכ\"פ הי' נכנס הכה\"ג לפני ולפנים הי' ממשיך לכפר גם על בחי' קדש, ועד\"ז י\"ל בפי' דרעוא פי' רצה\"ע בי' מן בחי' קדם הוי' שבסדר ההשתלשלות כו', וי\"ל שבבהמ\"ק הוא בחי' מל' דאצי' בחי' שכינה שזהו בחי' המקום שפגע יעקב, ושרש בחי' המל' הוא מרדל\"א כמ\"ש במק\"מ, וזהו דרעוי' בי' מן קדם הוי' כו', ולכן כשהרגיש יעקב זה אמר מה נורא המקום הזה, שבבחי' מקום זה מקום בהמק\"ד הוא בחי' נורא מקור היראה ע\"ד נורא תהילות, עד שעושה פלא פי' שגם בחי' פליאות חכ' לעשיי' נחשב לגבי בחי' זו שבכתר כו'.",[["143","19","<b>א\"כ</b>: ארץ כנען (ארץ ישראל). וראה לקמן ד\"ה וישב יעקב וד\"ה מי כהוי' אלקינו."],["144","20","<b>כמ\"ש במ\"א שתטהרו בגימ' כתר</b>: ראה לעיל ס\"ע לד. וש\"נ."],["145","21","<b>במ\"א בענין מקדש הקדש וקדש</b>: ראה לקו\"ת יוהכ\"פ סט, א. ע, ג. עא, ב."]]],[2000460122,"<h3>אתה אחד ושמך כו' (א)</h3>\n<b></b><b>בס\"ד. ש\"פ וישלח, ט\"ל.</b>\n<b></b>שהעלו אבק כו' אחד יחיד כו' מלחמת הקליפות\nוישלח\n<b>אתה</b> אחד<sup data-n=\"146\">1</sup> ושמך אחד, ומי כעמך כו' אחד בארץ. וצ\"ל שמשמע שבחי' זו שאתה אחד וגם מה ששמך אחד זהו ע\"י שגוי אחד בארץ, וכמארז\"ל אתם עשיתוני חטיבה אחת בעולם שנא' הוי' אחד, אף אני אעשה אתכם חטיבה אחת בעולם שנא' גוי אחד כו', ונמצא ממילא מובן שע\"י גוי אחד בארץ ממשיכי' בחי' אתה אחד ושמך",[["146","1","<b>אתה אחד</b>: מאמר זה (מלבד הסיום, פיסקא: ובזה יובן ענין אתה אחד, עד גמירא) הוא מיוסד והגהות על חלק מד\"ה ויקרא גו' פניאל להצ\"צ בכת\"י 1063 צט, א ואילך. וראה לקמן ד\"ה כמים הפנים שהוא בתור המשך למאמר זה [ומיוסד ג\"כ על ד\"ה ויקרא גו' פניאל]. מאמר הצ\"צ מיוסד על ד\"ה ויאבק איש עמו ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח כו, סע\"א</a> ואילך. [ובשינויים ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480088\" data-slug=\"or-hatorah-hb\" data-id=\"8316480088\">אוה\"ת וישלח (כרך ה) תתעה, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010146\" data-slug=\"or-hatorah-hb\" data-id=\"8159010146\">שם (כרך ז) תתתל, א</a> ואילך].\nהנחת כ\"ק אדמו\"ר מוהרש\"ב ממאמר זה נד' לקמן בהוספות. וראה עניני המאמר באריכות בד\"ה אתה אחד תרצ\"א בסה\"מ קונטרסים ח\"א קס, א ואילך. [וניכר שהוא מיוסד על הנחת כ\"ק אדמו\"ר מוהרש\"ב מהמאמר]. להתחלת וסיום המאמר ראה ד\"ה זה בסה\"מ תש\"ב ע' 71. וס\"ע 74. ד\"ה זה בסה\"מ מלוקט ח\"ד ע' סט-ע."]]],[2000460123,"אחד, והלא הוא ית' הוא אחד ומיוחד ואתה הוא קודם שנברה\"ע, ואתה הוא לאחר שנברה\"ע בלי שום שינוי כלל כו'. וגם צ\"ל הלא לע\"ל נא' ביום ההוא יהי' הוי' אחד ושמו אחד, והקשו ע\"ז בגמ' אטו האידנא כו', ותירצו כו'<sup data-n=\"147\">2</sup>, וא\"כ מהו שאתם עשיתוני חטיבה אחת בעולם, הלא עדיין לא נעשה בגילוי למטה שהרי ביום ההוא יהי' כו' וכפי מה שתירצו בגמ' כו' לא כעוה\"ז העוה\"ב כו'.\n<b>ולהבין</b> כ\"ז צ\"ל שרש ענין מלחמת יעקב<sup data-n=\"148\">3</sup> שאבק איש עמו עד עלות השחר, וארז\"ל (חולין פ' גיד הנשה) שהעלו אבק עד כסה\"כ, ודרשו זה מדכתי' ויאבק, שלכאו' א\"מ הלא ענין העלאת האבק זהו דבר הבא ממילא כששני בני אדם מתאבקים זא\"ז, ולא זהו לכאו' עיקר מלחמתם, ומדוע עשו מזה עיקר<sup data-n=\"149\">4</sup> לקרות כל המלחמה ע\"ש האבק שהעלו, וכי מפני שהעלו אבק יקרא לכל המלחמה בשם אבק כו'. ורש\"י פי' ויאבק לשון ויתקשר<sup data-n=\"150\">5</sup> ולשון ארמי הוא בתר דאביקו בי' וכמשארז\"ל במנחות גבי ציצית ואביק לי' מיבק כו' לשון עניבה, שכן דרך שני בנ\"א שמתאמצים להפיל איש את רעהו שמחבקו ואובקו בזרועותיו כו' עכ\"ל. והנה למעלה נק' מלחמה זו מלחמה לה' בעמלק מדור דור, ולכאורה אינו מובן איך יתכן להיות הס\"מ נלחם נגד הקדושה והלא כל עיקר חיות הקליפות הוא מהקדושה דהיינו מאחוריי' דקדושה וכמשי\"ת ואיך יהי' יכולת בידו להלחם נגד הוי' כו'.\n<b>והענין</b> הוא דהנה בגמ' בסנהדרין איתא ר' אליעזר רמי כתי' טוב ה' לכל וכתי' טוב ה' לקויו לנפש תדרשנו ואו' ע\"ז משל לאחד שהוא משקה שדהו הוא משקה לכל השדה אף במקום שאינו צריך (כי לא איכפת לי') וכשהוא עודר אינו עודר אלא כמה שצריך דהיינו סביבות האילנות כו'.",[["147","2","<b>והקשו ע\"ז בגמ' אטו האידנא כו' ותירצו כו'</b>: ז\"ל הגמ' (פסחים נ, א): והי' הוי' למלך על כל הארץ ביום ההוא יהי' ה' אחד ושמו אחד, אטו האידנא לאו אחד הוא, אמר ר\"א בר חנינא לא כעוה\"ז העוה\"ב, העוה\"ז על בשורות טובות אומר ברוך הטוב והמטיב ועל בשורות רעות אומר ברוך דיין האמת, לעוה\"ב כולו הטוב והמטיב. ושמי אחד מאי אחד אטו האידנא לאו שמו אחד הוא, אר\"נ בר יצחק לא כעוה\"ז העוה\"ב, העוה\"ז נכתב ביו\"ד ה\"א ונקרא באל\"ף דלי\"ת אבל לעוה\"ב כולו אחד נכתב ביו\"ד ה\"א ונקרא ביו\"ד ה\"א. [וראה לקמן בסיום המאמר]."],["148","3","<b>ולהבין כ\"ז צ\"ל שרש ענין מלחמת יעקב</b>: בהבא לקמן (בפיסקא זו) ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח שם כו, א</a>."],["149","4","<b>שלכאו' א\"מ הלא ענין העלאת האבק. . ומדוע עשו מזה עיקר</b>: תירוץ קושיא זו נתבאר לקמן בד\"ה כמים הפנים. וראה ד\"ה אתה אחד תרצ\"א שם שמבאר: אך הענין הוא דהנה איתא בחדושי הרשב\"א דאבק הרגלים הוא כינוי לתולדות, דשרו של עשו שהתאבק עם יעקב רמז לו שבכל הדורות יתאבקו תולדותיהם, והוא סוד הגלות, וישראל נתפזרו לארבע כנפות הארץ כו' ועוסקים בתורה וקיום המצות הנה בזה מטהרים את הארץ כו', וזהו שחזר אחר פכים קטנים דמלחמת יעקב היתה שבכל עת וכל מקום שיש בנ\"י גם אם יהיו ח\"ו בגלות וכלים קטנים ביותר יוכלו לטהר את האויר ע\"י קיום התומ\"צ, וזהו\"ע האבק שהו\"ע המלחמה בעבודת הבירורים כמ\"ש כי יד על כס י\"ה מלחמה לה' בעמלק מדר דר."],["150","5","<b>אבק עד כסה\"כ ודרשו זה מדכתי' ויאבק. . ורש\"י פי'. . לשון ויתקשר</b>: ראה בארוכה אוה\"ת בראשית (כרך ב) תנז, ב. ספר החקירה להצ\"צ צג, סע\"א-ב."]]],[2000460124,"<b>ולהבין</b> כ\"ז צ\"ל מארז\"ל הנ\"ל אתם עשיתוני חטיבה כו' שנא' שמע ישראל כו' ה' אחד, ולכאו' צ\"ל למה לא כתי' ה' יחיד<sup data-n=\"151\">6</sup> כי מלת יחיד מורה יותר על אחדות ממלת אחד, כי מלת אחד מלבד מה שיש אחד המנוי כמו שבטי ישראל הם שנים עשר שמ\"מ נק' אחד מהם בשם אחד כמ\"ש ויפתח האחד כו', או במע\"ב יום אחד כו' שזה אינו שייך לומר ח\"ו באלקות אלא כמ\"ש יש אחד ואין שני לו שמה שהוא ית' נק' אחד אין שני לו כו' כמ\"ש מזה במ\"א<sup data-n=\"152\">7</sup>, הנה תיבת אחד יתכן לומר על דבר שהוא כלל מהרבה מדרגו' רק שבכללות הוא דבר שלם, וכמו האדם שיתכן לומר אדם אחד אף שהוא כלול מהרבה בחי' ומדרגו' שונות כמו יד ורגל כו', והנה הוא ית' הוא פשוט בתכלית הפשיטות ויתכן בו יותר לומר ה' יחיד שמורה על אחדותו יותר. אך הענין הוא דהנה ארז\"ל כד אמליכתי' למעלה ולמטה תו לא צריך פי' אמליכתי' הוא, דהיינו להמשיך אלקות למטה בעולמות, ע\"ד הבקשה גלה כבוד מלכותך, וזהו פי' אחד שהאל\"ף מורה על אלופו ש\"ע וכנודע שברה\"ע לא הי' באל\"ף מטעם שית' לקמן, ואם כי תמונת אל\"ף הוא יו\"ד בראש ויו\"ד בסוף והקו הוא ו' באמצע כו' עכ\"ז הנה בכללותו הוא אל\"ף שרומז לבחי' אלופו של עולם, וח' הוא ז' רקיעים וארץ, ודלי\"ת הוא ד' רוחות העולם, ופי' שצריך להמשיך גילוי אלקות בעולמות הנבראי' ונפרדים שגם בהם יאיר אלקותו ית' בגילוי כו'.\n<b>והנה</b> ידוע שכדי שיוכל להיות להאיר גילוי אלקותו בעולמות הנבראי' ונפרדי' צ\"ל צמצום מתחלה, כי עצמותו ית' אינו בגדר עלמין כלל וכמאמר לאו מכל אינון מדות איהו כלל, ולית מח' תפיסא בי' כלל, וכדי שיהי' גילוי אלקו' בעולמות זהו ע\"י צמצום דוקא. ויובן זה ממשארז\"ל צמצם שכינתו בין ב' בדי הארון<sup data-n=\"153\">8</sup>, ולכאורה אינו מובן הלא בין הבדים הי' עיקר גילוי אלקותו ית', מה שאינו כן בכל העולם אף שכתי' את השמים ואת הארץ אני מלא אעפ\"כ אינו מאיר אלא בבחי' העלם, אבל בין הבדים הי' עיקר השראת גילוי אלקות שמשם קיבל משה נבואתו, וכמ\"ש ונועדתי לך שמה ודברתי איתך מעל הכפורת מבין שני הכרובים, וא\"כ למה א' צמצם שכינתו בין ב' בדי הארון. אך לפי הנ\"ל יובן זה היטב שהיא הנותנת לפי ששם הי' מאיר אלקות בבחי' גילוי ע\"כ צריך להיות צמצום דוקא כדי שיוכלו לקבל את הגילוי, שאל\"כ איך יכול להיות השראת שכינה בבית המקדש שהרי נא' איזה בית אשר תבנו לי כו', ע\"כ כדי שיהי' מאיר אלקות בבחי' גילוי בבהמ\"ק זהו ע\"י צמצום כו'. וזהו ענין ששם הוי'",[["151","6","<b>ה' אחד. . למה לא כתי' ה' יחיד</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380598\" data-slug=\"likkutei-torah\" data-id=\"4001380598\">בלק ע, א</a>. אמרי בינה שער הק\"ש פ\"ח. דרמ\"צ קכד, א ואילך. סה\"מ תרכ\"ו ע' קצג ואילך. תרכ\"ז ע' קע. רכג ואילך. תרכ\"ט ע' לא ואילך. קנו ואילך. תרל\"ב ח\"א ע' ערב. לקמן ד\"ה הללוי' גו' במרומים."],["152","7","<b>שמה שהוא ית' נק' אחד אין שני לו כו' כמ\"ש מזה במ\"א</b>: ראה סה\"מ תרכ\"ז שם ע' קע. תרכ\"ט ע' לב. וע' קסד. וראה גם סה\"מ תרל\"ה ח\"ב ע' תא."],["153","8","<b>ויובן זה ממשארז\"ל צמצם שכינתו בין ב' בדי הארון</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380225\" data-slug=\"likkutei-torah\" data-id=\"4001380225\">לקו\"ת אמור לד, ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480187\" data-slug=\"or-hatorah-hb\" data-id=\"8316480187\">אוה\"ת חנוכה (כרך ה) תתקכה, א</a>. סה\"מ תרל\"ב ח\"א ע' מח [ובמקומות שנסמנו שם בתחילת המאמר]. וע' רי. ועוד."]]],[2000460125,"מתחיל ביו\"ד כי ענין ש' הוי' הוא בחי' חכ' וכמ\"ש הוי' בחכ' כו' שהוא בחי' ראשית הגילוי מאא\"ס לבחי' השתל' העולמות, וכדי שיהי' גילוי אפי' בבחי' חכ' שהרי לית מח' תפיסא בי' כלל שאפי' בחי' חכ' ג\"כ אינו נתפס בך, וכמ\"ש והחכ' מאין תמצא שהיא רק הארה בעלמא, זהו ע\"י בחי' יו\"ד שהיא נקודה חדא בחי' צמצום כו'.\n<b>וזהו</b> ענין הוי' אחד שהוא בחי' המשכת אלקות בעולמות בבחי' גילוי, וזהו ע\"י צמצום דוקא. ולכך נא' הוי' אחד ולא כתי' ה' יחיד, לפי שה' יחיד הוא בחי' אא\"ס כמו שהוא למעלה מן הצמצום שאינו יכול להיות מאיר בבחי' גילוי למטה, אבל כדי שיהי' מאיר בבחי' גילוי למטה כו' זהו בחי' ה' אחד שהוא ע\"י צמצום. וזהו מ\"ש לע\"ל ביום ההוא יהי' ה' אחד ושמו אחד, ומקשינן בגמ' אטו האידנא לאו אחד הוא, אלא האידנא לא כמו שנכתב נקרא, והיינו שהקרי הוא בחי' גילוי והכתיב הוא בחי' העלם לפי שאינו מאיר עתה בבחי' גילוי ע\"כ לא כשאני נכתב כו', רק בבהמ\"ק שהי' בחי' גילוי הי' נקרא ככתבו כו', וזהו ע\"י צמצום יו\"ד דש' הוי' וכנ\"ל בענין צמצם שכינתו כו' כי ארון הוא אור נו\"ן כמ\"ש במ\"א<sup data-n=\"154\">9</sup>, אבל לע\"ל שיהי' מאיר אלקות בבחי' גילוי וכמ\"ש ואמר ביום ההוא הנה אלקינו זה כו' יהי' נקרא כמו שנכתב, וע\"כ נאמר ביום ההוא דוקא יהי' ה' כו' ושמו אחד לפי שאחד הוא בחי' גלוי אלקותו ית' שע\"י בחי' צמצום כו'.\n<b>והנה</b> ע\"י מה ממשיכי' שיהי' הגילוי אלקות בעולמו' הוא ע\"י הביטול כי השראת אא\"ס הוא בבחי' חכ' ובה ראשית הגילוי, לפי שחכ' היא כח מ\"ה בחי' ביטול וכמ\"ש בסש\"ב פל\"ה בהג\"ה ואין אא\"ס שורה אלא במי שבטל דוקא, וכמ\"כ מובן שע\"י הביטול ממשיכי' גילוי אלקות. והנה עיקר הביטול הוא בבחי' מוחין בחי' חב\"ד שהם הם בחי' ביטול ממש, משא\"כ במדת האהבה אף שיש לו אהבה לאלקות אעפ\"כ הוא בחי' יש מי שאוהב, אבל במוחין חב\"ד הביטול הוא אמיתי. ואעפ\"כ צריך שיומשך הביטול מהמוחי' גם במדות שהם נמשכי' מחב\"ד ע\"י התבוננות שנתהווה בחי' התפעלות הלב באהוי\"ר מפני שמתבונן בגדולת א\"ס ב\"ה, דהיינו שיהי' התכללו' המדות שיהיו כלולי' האהבה מיראה ויראה כלולה מאהבה וכמ\"ש בק\"ש ואהבת את<sup data-n=\"155\">10</sup>, שהאהבה כלולה מיראה שזהו ע\"י התבוננות בפסוק שמע כו' וכשהאוי\"ר כלולי' זמ\"ז הרי זה הזזה מבחי' יש, שההתכללות הוא היפוך הישות וזה בא ע\"י המשכת המוחין, ואעפ\"כ אינו עצמות הביטול כמו חב\"ד. ויש מי שהוא בבחי' נצח דהיינו אף שאין לו אוי\"ר בפו\"מ אעפ\"כ הוא בבחי' נצח דהיינו שנעשה אצלו הסכם",[["154","9","<b>ארון הוא אור נו\"ן כמ\"ש במ\"א</b>: ראה אוה\"ת חוקת (הוצאת תשנ\"ח) ע' תתפט (6). סה\"מ תרל\"ה ח\"ב ע' תנז. תרל\"ח ע' קמח. לקמן ד\"ה עבדו את ה' בשמחה. וראה גם לקו\"ת חוקת סו, ג."],["155","10","<b>שיהיו כלולי' האהבה מיראה. . וכמ\"ש בק\"ש ואהבת את</b>: ראה בכ\"ז בארוכה לקו\"ת ואתחנן ז, ד. מאמרי אדה\"ז תקס\"ו ע' שיא. מאמרי אדהאמ\"צ דברים ח\"א ע' קעו. אמ\"ב שער הק\"ש פמ\"ד. סה\"מ תרל\"א ע' צח. תער\"ב-ע\"ו ע' קלב. תרפ\"ז ע' קצא-ב."]]],[2000460126,"חזק<sup data-n=\"156\">11</sup> בבחי' נצח שלא יפרד מאלקות ויהי' בטל כו'. ויש מי שהוא רק בבחי' הודאה שאין לו אפי' בחי' נצחון רק שהוא בבחי' הודאה שמודה שצריך שיהי' אהוי\"ר לאלקות וצריך ליבטל אליו, ויש הודאה מהודאה שז\"ע בחי' הודאה דהודאה שנת' במ\"א<sup data-n=\"157\">12</sup>, וזהו מה שאנו אומרי' מודים אנחנו לך, הודו לה' קראו בשמו, והנה הודאה הוא בחי' מדרגה היותר אחרונה שהיא רק הודאה בעלמא לכן ארז\"ל מאן דלא כרע במודים<sup data-n=\"158\">13</sup> דהיינו שאין לו בחי' ביטול אף בהודאה בעלמא אינו קם בתחה\"מ. וזהו גוי אחד בארץ שיומשך בחי' גלוי אלקות בארץ דוקא ע\"י בחי' הביטול כ\"א לפי מדרגתו.\n<b>ובזה</b> יובן משארז\"ל ר\"א רמי כתי' טוב ה' לכל וכתי' טוב ה' לקויו ואמרו המשל כשמשקה משקה לכל השדה וכשהוא עודר כו', כי ענין טוב הוא השפעת חיות רוחני, ולכן נק' הצדיקי' טוב, וכמ\"ש אמרו לצדיק כי טוב כו', כי צדיק בחי' יסוד עולם ויסוד הוא בחי' משפיע, ופי' טוב ה' לכל הוא ענין השפעת החיות הכרחי לצורך קיום העולמות וז\"ש לכל אפילו כו', ומ\"ש טוב ה' לקויו זהו ענין השפעת אלקות בבחי' גילוי, וזהו דוקא לקויו דהיינו למי שהוא בבחי' ביטול לעושי רצונו דוקא. ואפ\"ל לקויו היינו המשכת אלקות בבחי' קוין שהיא ע\"י צמצום כו', והמשכת בחי' צמצום זה הוא ע\"י הצמצום שעושה בנפשו שזהו בחי' הביטול כו'.\n<b>והנה</b> מסוף מדרגת הקדושה נמשך חיות גם לקליפות וסט\"א אך ההשפעה שנשפע להם הוא בבחי' צמצום מאד וקבלתם הוא רק מאחורי העור דנוק' דהיינו בחי' צרופי אותיות<sup data-n=\"159\">14</sup> דרך נקבי העור דהיינו בחלל ומקום ריוח שבין צרוף לצרוף כדי שיהי' להם חיות מעט כו'. והנה עיקר המלחמה הוא שהקליפות רוצים לקבל למעלה מן הצמצום אשר שם כחשכה כאורה שוין, שממית בידים תתפש והיא בהיכלי מלך, אשר שם יכולי' גם הקליפו' לקבל כי אינו תופס מקום כלל אם צדקת כו', וע\"ז אמר הכתוב אם תגביהי כנשר<sup data-n=\"160\">15</sup> כו', דרך הנשר בשמים, שהם מגביהי' א\"ע בחוצפא וגסות הרוח כו', וענין חוצפא זו למעלה שרוצים לינק מאא\"ס ב\"ה שלא ע'י הקדושה שהיא המשכת הביטול הנמשך ע\"י ישראל, כי מזה אין להם יניקה רק מאחורי העור דנוק', אלא רוצים שיושפע להם אא\"ס ממש שלפניו כחשכה כאורה שאין בחי' הביטול תופס מקום כלל לפניו, ומשם יהי' להם יניקה שלא יצטרכו לקבל דרך הקדושה דרך נקבי העור בבחי' שערות וצפרני' כו'. רק עז\"נ משם אורידך נאום הוי' דהיינו גם",[["156","11","<b>בבחי' נצח. . שנעשה אצלו הסכם חזק</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380686\" data-slug=\"likkutei-torah\" data-id=\"4001380686\">לקו\"ת מסעי צ, ג</a>-ד. ועוד."],["157","12","<b>בחי' הודאה דהודאה שנת' במ\"א</b>: ראה סידור עם דא\"ח שג, ג ואילך. שו, ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650220\" data-slug=\"or-hatorah-hb\" data-id=\"8316650220\">אוה\"ת נ\"ך (כרך ב) ע' תתקמט</a> ואילך. וראה גם המשך תער\"ב ח\"א ע' תקטז. סה\"מ תש\"ט ע' 108. ובכ\"מ."],["158","13","<b>לכן ארז\"ל מאן דלא כרע במודים</b>: ראה גם לקמן ד\"ה ארע\"ק אשריכם ישראל."],["159","14","<b>והנה מסוף מדרגת הקדושה. . מאחורי העור. . צרופי אותיות</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח שם כו, ב</a>."],["160","15","<b>שהקליפות רוצים לקבל. . שממית בידים. . אם תגביהי כנשר</b>: ראה בכ\"ז בארוכה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370452\" data-slug=\"torah-or\" data-id=\"3901370452\">תו\"א ויחי קב, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370458\" data-slug=\"torah-or\" data-id=\"3901370458\">קג, ד</a> ואילך. סה\"מ תרל\"ב ח\"א ע' נג ואילך. [ובמקומות שנסמנו שם בע' נב]."]]],[2000460127,"ממקום אשר כחשיכה כאורה שוים יומשך ג\"כ בבחי' הוי' דוקא יו\"ד חכ' בחי' צמצום ה' התפשטות<sup data-n=\"161\">16</sup>, כי אני הוי' כתי' דהיינו דאפי' מבחי' אני שהוא אותיות אין בחי' עצמותו ומהותו נמשך דוקא לבחי' הוי' שהוא צמצום שכולא חד, לפי שכך עלה ברצונו דוקא שיהי' מאיר דוקא ע\"י צמצום כו' רצון אותיות צנור כו'. וזהו מלחמה לה' בעמלק מדור דור דהיינו שהמלחמה הוא בבחי' שם הוי' דוקא, אבל למעלה משם הוי' יכולי' גם הם לקבל משם שפע יניקה. אבל כשנעשה רצון אותיות צנור דהיינו שאפי' מבחי' שלמעלה ששם כחשכה כאורה שוין אם צדקת כו' יומשך ג\"כ בחכ' דוקא, וזה צנור בחי' צנור החכ' אבא יונק ממזלא, והוא בחי' הוי' יו\"ד חכ' אז לא יוכלו הקליפות לקבל רק כו'. וזהו תוכן מלחמת הס\"מ עם יעקב שרצה לקבל ממקום אשר כחשכה כאורה שוין.\n<b>ובזה</b> יובן מ\"ש במד\"ר בראשית והארץ היתה תהו ובהו אלו מעשה הרשעי', ויהי אור אלו מעשה הצדיקי', ועדיין איני יודע באיזה מהן חפץ אם במעשה הצדיקי' אם במעשה הרשעי', כיון דכתיב וירא אלקי' את האור כי טוב הוי חפץ במעשה הצדיקי'. ולכאו' אינו מובן מהו ענין ההתדמות מעשה הצדיקי' למעשה הרשעי' עד שנא' עדיין איני יודע באיזה מהן חפץ. אך הענין לפי שקמיה אשר לפני ההשתלשלות המדרגות חו\"ב שם כחשכה כאורה אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו, ולכן אין ידוע באיזה מהן חפץ, מאחר ששם אינו תופס מקום כלל, כשהוא אומר וירא אלקי' את האור כי טוב הוי חפץ במעשה הצדיקי', והיינו שכאשר נתצמצם ונמשך בסדר השתלשלות המדרגות אזי הוא הבירור שיחפוץ במעשה הצדיקי' דוקא כנ\"ל<sup data-n=\"162\">17</sup>.\n<b>ובזה</b> יובן ענין אתה אחד<sup data-n=\"163\">18</sup> ושמך אחד וענין אל\"ף דאחד שבק\"ש, דהנה ברה\"ע הי' בבי\"ת דוקא שקרא האל\"ף תגר ך\"ו דור, והוא מטעם שאל\"ף הוא ר\"ת ארור, משא\"כ ב' ר\"ת ברכה, בחכמה יבנה בית ב' כו' סימן ברכה, והקשו מדוע במ\"ת התחיל באל\"ף<sup data-n=\"164\">19</sup> אנכי, ותירצו שכאשר כבר הי' ברה\"ע בבי\"ת סי' ברכה אזי גם מהאל\"ף אינו נמשך ג\"כ כ\"א ע\"פ החכ' דוקא, וזהו ע\"ד ונפלינו אני ועמך כו'",[["161","16","<b>בבחי' הוי'. . יו\"ד. . צמצום ה' התפשטות</b>: ראה לקמן ד\"ה אנכי אנכי. וש\"נ."],["162","17","<b>שיחפוץ במעשה הצדיקי' דוקא כנ\"ל</b>: בכת\"י 1063 נוסף כאן הגה\"ה בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש: וי\"ל שגם בחפץ פנימיות הרצון הוא ג\"כ במעשיהם של צדיקים דוקא כמ\"ש ה' חפץ כו' יגדיל תורה."],["163","18","<b>ובזה יובן ענין אתה אחד</b>: הבא לקמן עד סוף המאמר נרשם במהדו\"ק בקיצור ובשינויים, ונדפס לקמן לאחרי המאמר."],["164","19","<b>בריה\"ע הי' בבי\"ת דוקא. . והקשו מדוע במ\"ת התחיל באל\"ף</b>: בהבא לקמן ראה בארוכה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסו ואילך. מאמרי אדהאמ\"צ קונטרסים ע' ריב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' תקעא. תקעט. ח\"ב ע' תשיח ואילך. תשכא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200143\" data-slug=\"or-hatorah-hb\" data-id=\"8159200143\">אוה\"ת</a> בשלח (כרך ז) ע' ב'תרנד. ויקרא (כרך ג) ע' תתנז ואילך. סה\"מ תרל\"א ע' נד ואילך. סא ואילך. תרל\"ב ח\"ב ע' תקנו ואילך. תרל\"ד ע' לו ואילך. ס' תורת שמואל דרושי חתונה ע' יח ואילך. ע' כ ואילך. סה ואילך. קלט ואילך. קמב ואילך. קמז. קסה ואילך."]]],[2000460128,"כמ\"ש בלק\"ת בד\"ה מצה זו<sup data-n=\"165\">20</sup>. ועד\"ז יובן ענין אל\"ף דאחד, הגם שאל\"ף רומז לבחי' פלא עליון עכ\"ז יומשך לבחי' ח' וד' שרומזי' לז' רקיעי' וארץ וד' רוחות העולם, והיינו ע\"י הצמצום, כנ\"ל שאחד רומז על הצמצום ע\"ד צמצם שכינתו כו', והוא שיצומצם להיות נמשך ע\"י החכמה שז\"ע יו\"ד בראש שבאל\"ף ויש בו קוץ ג\"כ. וכ\"ז הוא ע\"י התורה ומצות שישראל קיבלו שמתחלת באנכי כנ\"ל. וק\"ש היא מצוה כלליות שמרומז בה כל התומ\"צ כנודע שרמ\"ח תיבין דק\"ש רומזי' לרמ\"ח מ\"ע וכמ\"ש בכוונות ק\"ש שז\"ע שיעור קומה וכמ\"ש בלק\"ת שה\"ש בד\"ה צאינה וראינה<sup data-n=\"166\">21</sup> הראשון ס\"ג, ובירושלמי אמרו שבק\"ש יש כל עשרת הדברות בפרט, שה' אלקינו היא קבלה על אנכי, ה' אחד על לא יהי' לך כמ\"ש מזה במ\"א<sup data-n=\"167\">22</sup>, וק\"ש היא מצות היחוד שיומשך יחוד אלקותו ית' בעולמות, כי באמת בתיבות ה' אחד מרומז ב' הבחי' דה' אחד וגם שמו אחד שנא' בזכרי', שפי' הוי' אחד הוא שב' הויות יהיו אחד, והיינו מה שעכשיו נא' ויקרא ה' ה' ופסיק טעמא בינייהו שנת' מזה בכמה דוכתי<sup data-n=\"168\">23</sup> שש' הוי' דלתתא הוא ש' הוי' שבסדר השתלשלות שיש בו חו\"ג כו', משא\"כ ש' הוי' דלעילא הוא ש' הוי' שלמעלה מהשתלשלות שלית שמאלא, כ\"א שניהם ימין כמ\"ש ימינך ה' ב\"פ כו', ועכשיו פסיק טעמא בינייהו, ולע\"ל יהי' הוי' אחד שלא יפסיק הפסיק טעמא, ולכן תירצו בגמ' על אטו האידנא לאו אחד הוא, אלא שבעוה\"ב יהי' כולא הטוב והמטיב מפני שיאיר בחי' שם הוי' דלעילא דלית שמאלא כו', ועל ושמו אחד תירצו שיהי' נקרא כמו שנכתב, וכנ\"ל שכתי' וקרי הוא העלם וגילוי, והיינו כי זה שמי (ש' הוי') לעלם כתי' שצריכי' להעלימו בש' אד', ולכן סובר אבא שאול אף ההוגה את ה' באותיותיו אין לו חלק לעולם הבא (בסוף משנה א' דפרק חלק בסנהדרין), אלא שצריכי' להעלימו בש' אד', אבל לע\"ל יהי' שמו אחד שיקרא היינו שיהי' הגילוי כמו שנכתב שהוא ההעלם דעכשיו, וא\"כ זה ששמו אחד זהו ג\"כ נכלל במה שאומרי' בק\"ש ה' אחד שהכוונה ששמו העצמי הוא ש' הוי' יהי' אחד היינו שב' הוויות יהי' אחד, וגם שמו ש' הוי' ואד' יהיו אחד, והוא שגם ביחו\"ת יאיר כמו ביחו\"ע, וא\"כ יהי' הגילוי מש' הוי' וה\"ז ה' אחד. וי\"ל שזהו גילוי יותר מכמו שהי' בבהמק\"ד שהרי בבהמק\"ד שהיו קורי' את השם ככתבו היינו שהי' הגילוי בבהמק\"ד מש' הוי', אבל מ\"מ יש פסיק טעמא בין ב' ההוויות, אבל ע\"י היחוד דק\"ש יומשך שיהי' הגילוי מש' הוי' דלעילא ע\"י בחי' ש' הוי' דלתתא, וזהו יאיר גם בכללות העולם (ולא בבהמ\"ק לבד שגדול יהי' כבוד הבית כו'), וכ\"ז הוא ע\"י היחוד דק\"ש שהכח ע\"ז הוא מפני שהוי' אלקינו וכמו שפי' רש\"י שמה שעכשיו ה' אלקינו יהי' לע\"ל ה' אחד כו' ע\"ש, וזהו ע\"י ק\"ש שהיא מצוה כלליות,",[["165","20","<b>כמ\"ש בלק\"ת בד\"ה מצה זו</b>: צו דף יב, ג."],["166","21","<b>בלק\"ת שה\"ש בד\"ה צאינה וראינה</b>: דף כא, ג ואילך."],["167","22","<b>שה' אלקינו. . על אנכי ה' אחד על לא יהי'. . כמ\"ש מזה במ\"א</b>: ראה סה\"מ תרל\"ב ח\"ב ע' תעז [ובהמ\"מ שם]. תרל\"ג ח\"א ע' כו [ובהמ\"מ שם]. רפג. שיז-ח. ח\"ב ע' תעב. תקצב. לקמן רד\"ה את ה' האמרת."],["168","23","<b>ויקרא ה' ה'. . שנת' מזה בכמה דוכתי</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370277\" data-slug=\"torah-or\" data-id=\"3901370277\">תו\"א בשלח סא, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370372\" data-slug=\"torah-or\" data-id=\"3901370372\">תצוה פג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">פד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380167\" data-slug=\"likkutei-torah\" data-id=\"4001380167\">לקו\"ת תזריע כא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">חוקת נז, ג</a>. דרושים לר\"ה נט, א. לקמן ד\"ה ששים המה מלכות. וש\"נ."]]],[2000460129,"וכ\"ה ע\"י כל המצות בפרט שהם לאתקנא רזא דשמי' כמ\"ש בזהר, וע' בת\"א בד\"ה משה ידבר<sup data-n=\"169\">24</sup>, ובד\"ה ואלה שמות<sup data-n=\"170\">25</sup> בנ\"י בענין שמו הגדול, רק שכ\"ז הוא עכשיו להוסיף אורות באצי', ולע\"ל יומשך בחי' זו בגילוי.\n<b>וזהו</b> אתה אחד ושמך אחד גם עכשיו רק שזהו באצי' ע\"י עבודתינו שממשיכי' להוסיף אורות באצי' (משא\"כ אתה קודם שנברא ואתה הוא לאחר כו' הרי יש פסיק טעמא, וע\"י העבודה י\"ל שממשיכי' תוס' אורות שלא יפסיק הפסיק טעמא וע' בסידור בד\"ה ברוך שאמר<sup data-n=\"171\">26</sup> בענין ג' בחי' אתה כו' ובענין רדל\"א כו', ולכן י\"ל אתה אחד זהו כענין ה' אחד שבזכרי' ושמך אחד זהו כענין ושמו אחד דלע\"ל, וזהו ע\"י העבודה להוסיף אור' באצי' ולכן גם עתה אתה אחד ושמך אחד שהרי זהו כמונח בקופסא כמ\"ש במ\"א<sup data-n=\"172\">27</sup>) ולע\"ל יתגלה זה כו'.\n<b>וכ\"ז</b> הוא ע\"י ומי כו' גוי אחד בארץ שממשיכי' בחי' אחד גם בארץ בחי' טורי דפרודא שגם בה יומשך בחי' יחוד אלקותו, וזהו מה שאומרים ואספת דגנך כו' בפ' שני' דק\"ש (שהיא ג\"כ דבוקה לאחד שבפ' ראשונה שלכן נק' שני' כו'), שהגם שיש דרשי רז\"ל על דגנך תירושך ויצהריך כו', שבאמת כן הוא, אמנם אין מקרא יוצא מידי פשוטו שהוא דגנך כו' כפשוטו, והיינו שקאי על בעלי עסקים שגם הם יכולים להמשיך בחי' אחד בארץ כמו בעלי תורה יושבי אוהלים ואפשר ביתר שאת כו', והיינו ע\"י שיאספו כל דברי' הגשמיים לאלקות<sup data-n=\"173\">28</sup>, וכמ\"ש מזה במ\"א שיכוון שמפני מה הוא עוסק במו\"מ<sup data-n=\"174\">29</sup> הוא בשביל שירויח, ועי\"ז יוכל לפרנס בניו וב\"ב שגם על זה אמרו בגמ' שזהו עושה צדקות בכל עת, וכ\"ש בכדי שיוכל ליתן צדקה מיגיעו ויהדר במצות כו', שנמצא ע\"י זה מקשר כל דבריו הגשמי' שעושה לאלקות, ועי\"ז לא די שאינו נעשה נפרד אלא שהוא מקושר.",[["169","24","<b>בת\"א בד\"ה משה ידבר</b>: פ' יתרו סז, ד."],["170","25","<b>ובד\"ה ואלה שמות</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370221\" data-slug=\"torah-or\" data-id=\"3901370221\">תו\"א שמות מט, א</a> ואילך."],["171","26","<b>וע' בסידור בד\"ה ברוך שאמר</b>: דף לט, ג ואילך. ובארוכה פיה\"מ לאדהאמ\"צ ס, א ואילך."],["172","27","<b>העבודה להוסיף אור' באצי'. . כמונח בקופסא כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">לקו\"ת דברים א, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפג. מאמרי אדהאמ\"צ ויקרא ח\"א ע' נה. סה\"מ תרכ\"ז ע' תסז. תרכ\"ט ס\"ע רכח-ט. תרל\"ב ח\"ב ע' שנד. תרל\"ג ח\"א ע' רמד. תכא. ד\"ה פזר נתן תרמ\"ב. סה\"מ מלוקט ח\"א ע' ז."],["173","28","<b>ואספת דגנך. . שיאספו כל דברי' הגשמיים לאלקות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380414\" data-slug=\"likkutei-torah\" data-id=\"4001380414\">לקו\"ת נשא כו, ג</a>. סה\"מ תרכ\"ו ע' קסט. קעא. תו\"א תרומה שבהע' שלאח\"ז. ועוד."],["174","29","<b>וכמ\"ש מזה במ\"א שיכוון שמפני מה הוא עוסק במו\"מ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370357\" data-slug=\"torah-or\" data-id=\"3901370357\">תו\"א תרומה פ, ב</a>. סה\"מ תרל\"ב ח\"א ע' ו. קפ. תרל\"ג ח\"א ע' קלז. ובכ\"מ."]]],[2000460130,"<b>[לד\"ה אתה אחד] </b>\n<b>וזהו</b> אתה אחד<sup data-n=\"175\">30</sup> ושמך אחד, אתה אחד זהו ע\"ד הוי' אחד, כי ש' הוי' הוא שם העצם וכתי' הוי' בחכמה שנק' אתה כמ\"ש כי אתה אבינו, וע' בסידור בד\"ה ברוך שאמר, ושמך אחד היינו מה שיהי' נק' כמו שנכתב, וכל גילוי זה הוא ע\"י שישראל קבלו התורה וע\"י תומ\"צ ויחוד דק\"ש שהיא מצוה כלליות ממשיכי' שיהי' לע\"ל גילוי בחי' אתה ושמך אחד, לא יהי' הגילוי ע\"י בחי' הסתר דש' אד' כ\"א גם שמך יהי' אחד היינו בחי' גילוי ש' הוי ע\"ד כמו שהי' בבהמ\"ק, וביתר שאת שהרי גם ההויות יהי' ג\"כ אחד.\n<b>וכ\"ז</b> הוא ע\"י התומ\"צ דעכשיו, שעכשיו העבודה היא להוסיף אורות באצי', ולע\"ל יתגלה למטה, וי\"ל שבק\"ש מרומז כל התרי\"ג מצות רמ\"ח תיבין רמ\"ח מ\"ע, תר\"ך אותיות, ובירושלמי שכל עשה\"ד יש בק\"ש, ועיקר ענין יחוד דק\"ש זהו הוי' אחד דוקא, והכח ע\"ז הוא מפני שהוי' אלקינו אלקי' שלנו לכן נתן לנו הכח והעוז שגם בעולמות יהי' ביכלתינו להמשיך גילוי ש' הוי', והגם שזה שמי לעלם זהו עכשיו צריכי' להעלימו בש' אד', אבל לע\"ל כשיהי' כולו הטוב והמטיב וגם שמו יהי' אחד יתגלה כ\"ז, שע\"י שעושי' עכשיו אחד בארץ, היינו ליחד כל הדברי' באלקות ע\"ד ואספת דגנך שאומרי' בפ' שני' דק\"ש, עי\"ז נמשך גם עכשיו באצי' בחי' אתה אחד ושמך אחד, רק שלע\"ל יתגלה גם למטה להיות ונגלה כבוד הוי' וראו כו'<sup data-n=\"e10\">*</sup>.",[["175","30","<b>וזהו אתה אחד</b>: הבא לקמן הוא מהדו\"ק בקיצור ובשינויים מסוף ד\"ה אתה אחד הנדפס לעיל."],["e10","*","<b>ע\"ד הוי' אחד</b>: בשולי העמוד נרשם בגוכי\"ק:\nלהעיר שברה\"ע הי' ע\"י ב' סימן ברכה, ומ\"ת באל\"ף שגם בחי' חפץ הוי' פנימיות הרצון יומשך ג\"כ ע\"י שיגדיל תורה, ע\"ד ונפלינו אני ועמך."]]],[2000460131,"<h3>כמים הפנים (ב)</h3>\n<b></b><b>בס\"ד. (י\"ט כסלו, ט\"ל).</b>\nי\"ט כסלו\n<b>כמים</b> הפנים<sup data-n=\"176\">1</sup> לפנים כו' (משלי ך\"ז י\"ט) פי' רש\"י כו'<sup data-n=\"177\">2</sup> וצ\"ל מהו המשל ממים אל לב האדם.\n<b>הנה</b> כתי' זה דור דורשיו<sup data-n=\"178\">3</sup> מבקשי פניך יעקב סלה. ולכאו' אינו מובן כי הנה מבקשי פניך קאי על אא\"ס כמ\"ש את פניך הוי' אבקש, וא\"כ מהו שכ' יעקב סלה<sup data-n=\"179\">4</sup>. ורש\"י פי' מי שהוא מבקש פניך הוא מזרע יעקב<sup data-n=\"180\">5</sup>, אבל מי שאינו מבקש פניך כו'. אך הענין הוא דהנה יעקב נק' פניך ע\"ש שהמשיך אא\"ס בבחי' פנימי'. וזהו מ\"ש במד\"ר ע\"פ ויוציאך בפניו בכוחו הגדול, בפניו זה יעקב, בכוחו זה יצחק, הגדול זה אברהם, והיינו לפי שיעקב המשיך אלקו' בבחי' פנימי', לפי שיעקב הוא בריח התיכון כו' ששם מאיר אא\"ס בתוס' וגילוי יותר לפי שהוא מחבר בחי' מדות חו\"ג. וע\"כ נק' פנים. והיינו שכמו שבפנים מאיר כל גילוי כוחות הנפש כמו ראי' ושמיעה כו' ריח ודבור, כך יעקב המשיך אא\"ס בבחי' הארת פנים וכמ\"ש יאר ה' פניך אליך שיומשך בחי' הארת פנים למטה כו'.\n<b>וזהו</b> דכתי' וירא כי לא יכול לו<sup data-n=\"181\">6</sup> כו' ותקע כף ירך יעקב. כי הנה יעקב בחיר שבאבות. והאבות הן הן המרכבה ויעקב הוא בחי' ת\"ת קו האמצעי בריח",[["176","1","<b>כמים הפנים</b>: מאמר זה הוא בהמשך להמאמר שלפנ\"ז ד\"ה אתה אחד. והוא מיוסד והגהות על חלק מד\"ה ויקרא גו' פניאל להצ\"צ בכת\"י 1063 קא, א ואילך. חלק מהמאמר מיוסד על ד\"ה ויאבק איש עמו ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a> ואילך.\nוראה תוכן המאמר בשינויים בד\"ה ויקרא גו' פניאל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480095\" data-slug=\"or-hatorah-hb\" data-id=\"8316480095\">אוה\"ת וישלח (כרך ה) תתעח, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480100\" data-slug=\"or-hatorah-hb\" data-id=\"8316480100\">וראה גם שם תתפא, א</a> ואילך. אוה\"ת נ\"ך (כרך ג) ע' א'רצד-ה (ע\"פ זה דור דורשיו). הנחת כ\"ק אדמו\"ר מוהרש\"ב ממאמר זה נדפסה לקמן בהוספות.\nוראה שיחת ליל כ' כסלו תרצ\"ג (לקו\"ד ח\"א מב, ב — הובא לקמן ח\"ב בהוספות בליקוט שיחות ורשימות אודות שנת תרל\"ט), שיסוד מאמר זה הוא מד\"ה כמים הפנים שאמר אדמו\"ר הזקן במוצאי כ\"ף כסלו תקנ\"ט לאחר צאתו מהמאסר, ויסוד המאמר הוא מתורת הבעש\"ט ע\"פ זה. עיי\"ש."],["177","2","<b>כמים הפנים. . פי' רש\"י כו'</b>: ז\"ל רש\"י עה\"פ: כמים הללו הפנים שאתה מראה לתוכן הן מראות לך, כן לב האדם לאדם חבירו, לפי מה שאדם יודע שחבירו אוהבו כן הוא מראה לו פנים."],["178","3","<b>הנה כתי' זה דור דורשיו</b>: בהבא לקמן בפיסקא זו ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670294\" data-slug=\"or-hatorah-hb\" data-id=\"8158670294\">אוה\"ת</a> וישלח (כרך ה) שם תתעט, א. נ\"ך (כרך ג) שם ע' רצד-ה."],["179","4","<b>מבקשי פניך קאי על אא\"ס. . וא\"כ מהו שכ' יעקב סלה</b>: ראה אוה\"ת וישלח שם: הבחיי פ' לך כ' כי הדבר הדבק נק' ע\"ש הנדבק בו, וכן הנדבק נק' ע\"ש הדבק כו' וז\"ש מבקשי פניך יעקב סלה עכ\"ל, ור\"ל מבקשי פניך קאי ע\"ש הקב\"ה ע\"ד בקשו פני את פניך ה' אבקש, וא\"כ מהו שכ' מבקשי פניך יעקב סלה, אלא לפי שיעקב נדבק בהקב\"ה נאמר כן כו' למדנו מזה דגילוי בחי' פניך זהו ע\"י יעקב. עכ\"ל האוה\"ת שם. וראה גם אוה\"ת נ\"ך שם."],["180","5","<b>ורש\"י פי' מי שהוא מבקש פניך הוא מזרע יעקב</b>: כ\"ה בכת\"י מעתיק מס' 1063 שם, ולא נמצא ברש\"י שלפנינו. ואולי הוא טעות המעתיק כאן, וצ\"ל: ובמפרשים פי'. וכן מפורש לקמן בהנחת כ\"ק אדמו\"ר מוהרש\"ב מהמאמר בשם מפרשים. וראה ראב\"ע עה\"פ (תהלים כד, ז): זה הדור הם מבקשי פניך כו' הם זרע יעקב. ובמצו\"ד שם: זהו הדור שהמה דורשי ה' והמה קרואים זרע יעקב הראויים לבקש פניך לעולם ולבוא לביהמ\"ק."],["181","6","<b>וזהו דכתי' וירא כי לא יכול לו</b>: בהבא לקמן (עד פיסקא: והנה בחי' אבק) ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח שם כו, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770350\" data-slug=\"or-hatorah-hb\" data-id=\"8316770350\">אוה\"ת שה\"ש (כרך ב) ע' תשיח</a> ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480091\" data-slug=\"or-hatorah-hb\" data-id=\"8316480091\">אוה\"ת וישלח רמה, סע\"א</a> ואילך. שם (כרך ה) תתעו, ב."]]],[2000460132,"התיכון המבריח מן הקצה כו', וגם יעקב הוא בחי' יו\"ד עקב, הארת יסוד אבא שרש כל האצי'. ובזה טעה הס\"מ שהי' סבור שיעקב אבינו אינו אלא מרכבה למדות חג\"ת, אבל באמת שרש יעקב ויסודתו בהררי קדש ח\"ע יסוד אבא מוח הזכרון כו' וכמשארז\"ל על יעקב יעקב לא מת ואיתא בזוהר מאן דנפיל ממדריגתו איקרי מית פי' מה שנפלו בשבירה נק' בחי' מיתה וכמ\"ש וימלוך וימת, אבל הנה ידוע שהשבירה לא הי כ\"א בז\"ת דס\"ג אבל בחכ' לא הי' בחי' שבירה כלל כמ\"ש ימותו ולא בחכ'. ולכן יעקב שהוא מבחי' יסוד אבא כו' לא הי' ממדריגות הנופלי' כלל, ולכן יעקב אבינו לא מת<sup data-n=\"182\">7</sup>. וזהו כי לא יכול לו, רק ותקע כף ירך יעקב, שנגע בירכין שהוא בחי' נצח והוד שפגם בנצח דקדושה עד שבא שמואל ותיקן<sup data-n=\"183\">8</sup> וכמ\"ש וגם נצח ישראל לא ישקר.\n<b>והנה</b> מלחמה זה הוא בדכר דקליפה שכנגד ז\"א, וכמו\"כ יש לעו\"ז בנוקבא דקליפה נגד מל' דקדושה, וזהו ההפרש שבין עפר לאבק הנז' בזוהר<sup data-n=\"184\">9</sup>, ושרש ההפרש",[["182","7","<b>יעקב. . יסוד אבא. . ולכן יעקב אבינו לא מת</b>: ראה בכ\"ז ביאוה\"ז לאדהאמ\"צ קלז, סע\"ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480091\" data-slug=\"or-hatorah-hb\" data-id=\"8316480091\">אוה\"ת וישלח שם תתעו, ב</a>."],["183","8","<b>שנגע בירכין. . נצח והוד. . עד שבא שמואל ותיקן</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיט ואילך. דרמ\"צ יב, סע\"א ואילך. ובכ\"מ."],["184","9","<b>וזהו ההפרש שבין עפר לאבק הנז' בזוהר</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560120\" data-slug=\"or-hatorah-hb\" data-id=\"8316560120\">אוה\"ת</a> שה\"ש שם ע' תשכ. וראה גם אוה\"ת בראשית (כרך ג) תקכו, ב. בשלח ע' תנג. וראה ספר הערכים חב\"ד ח\"א ערך אבק ע' סג ואילך.\nבכת\"י מעתיק נמצא כאן עוד קטע שלא ניתן להעתיק (לחלקו הראשון ראה בשינויים תו\"א וישלח שם): כי הנה ד' יסודות ארמ\"ע, העפר היא מדריגה התחתונה שבכולם ואש רוח מים הם הגבוהים יותר, ואעפי\"כ כולם אינם מצמיחין פירות רק הכל הי' מן העפר. והטעם כי הנה העפר הוא מבחי' מל' וכמ\"ש ומן העפר אשר יהי' בקרקע המשכן, והנה בקדושה היא בחי' ההתכללות נעוץ תחילתן בסופן דוקא וכנודע מ\"ש אני ראשון ואני אחרון שהמל' הוא בחי' כתר שהוא הממוצע בין המאציל לנאצלים, אני אותיות אין, כי אין הוא בחי' כתר, וכמ\"ש והחכ' מאין תמצא, ולכן<sup data-n=\"e27\">*</sup> יש כח זה גם להמל' להצמיח כל צמח האדמה בגשמיות, וגם ברוחניות יש כח להמל' סוף המדריגות מקור אתדל\"ת להיות אתדל\"ע להמשיך אור הי\"ס כו'. והנה בעבודה נק' עפר בחי' ענוה כמו העפר שהכל דורסין עלי' כמו\"כ מי שהוא עניו באמת לא איכפת לי' כלל וכמו שא' והוי שפל רוח בפני כל אדם, וגם עפר היא בחי' קבלת עומ\"ש שהיא סוף בחי' ענוה וכמ\"ש עקב ענוה יראת ה' יר\"ת, וזהו מ\"ש ונפשי כעפר לכל תהי' פתח לבי בתורתך דהיינו שכדי שיהי' הצמיחה בחי' תומ\"צ וכשארז\"ל מאי פירי מצוה, צריך להיות תחילה בבחי' עפר, משא\"כ אבק הוא מה שאשתאר מן נורא כמשל העצים שדולקי' באש והאש שואב יסוד ארמ\"ע [כ\"ה בגוכי\"ק] שבתוכו ולא נשאר אלא יסוד העפר שהוא האפר, ואפר זה אינו מצמיח כמו העפר שמצמיח מעצמו, אלא זורעים בו ומצמיח שלכן הוא כשר לכיסוי הדם, כך עד\"מ מל' דקליפה אחר גמר כל הבירורים שעיקר החיות שלהם הוא ע\"י שבה\"כ כו' ומה שנברר תחילה הוא היותר מובחר נעשה אצי' ואח\"כ בריאה עד שהמדרג' התחתונה סוף כל הבירורים מה שא\"א עוד לברר שם הם הקליפות ולא נשאר בהם רק חיות מועט כמו האבק שעכ\"פ כשזורעין בו מצמיח, ומ\"מ אינו כמו עפר שמצמיח מעצמו ואם זורעין בו מצמיח בתוס' וריבוי."],["e27","*","<b>ולכן יש כח זה גם להמל' להצמיח</b>: בשולי הגליון נרשם בגוכי\"ק: להעיר מענין שההולדה הוא דוקא ע\"י אשה, והגם כי ג\"ז מאיש לוקחה זאת, עכ\"ז כו'. רק כשהם מפורדין יכול ח\"ו להיות ע\"ד כאדם הראשון וחוה במשך ק\"ל שנים. ולכן בירר יעקב גם האבק נוק' בכדי לתקן שיומשך ע\"י תומ\"צ אח\"כ יחוד זו\"נ, ויהי' שומר לפרי כמו קודם החטא כו'."]]],[2000460133,"עפר הוא בחי' ומן העפר אשר יהי' בקרקע המשכן מל' דקדושה, ואבק מל' דלעו\"ז<sup data-n=\"185\">10</sup> כו'.\n<b>ויובן</b> יותר ההפרש שבין אבק לעפר<sup data-n=\"186\">11</sup>, הנה אבק הוא אינו עצם הדבר רק שהוא מעין אותו הדבר, וכשארז\"ל כמה קשה אבקה של שביעית, וכן מצינו אבק גבי ריבית, וכן אבק לשון הרע, והיינו כי אבק אינו עצם הדבר, שאינו ריבית ממש או לה\"ר ממש, רק שהוא מעין ריבית ויש לו קצת התדמות לריבית. וכמ\"כ הקליפה נגד הקדושה היא רק דמיון קצת לבד אבל אינם ח\"ו כו' והם רק כקוף בפני אדם, שאף שהקוף עושה ג\"כ מה שיעשה האדם אעפי\"כ אינם אלא שמדמין מעשיהם למעשה האדם כו', כמו\"כ הוא ענין הקליפות נקראים אבק כו' וד\"ל. והנה ארז\"ל העלו אבק עד כסה\"כ, פי' העלו אבק שיעקב העלה גם בחי' האבק שיוכלל בקדושה עד כסה\"כ בחי' מל' דקדושה, שכאשר ויאבק איש עמו גם יעקב נתחזק ובירר ממנו, והעלו לשון רבים לפי שהבירור הי' ע\"י שניהם, יעקב הוא המברר והס\"מ הוא המתברר כו' וכמו שחבק הס\"מ חו\"ג על גופו של יעקב, כך חבקו ידי יעקב חו\"ג שלו על גופו של ס\"מ כי כן דרך המתאבקי' במלחמה שחובקי' ואובקים זא\"ז בזרועותיהם. ולכך נק' המלחמה בשם אבק ויאבק עמו כו'. וכך היא מלחמת היצה\"ר וכמשארז\"ל לעולם ירגיז אדם כו'. ולכן גדול כח התשובה, כי הבירור הוא ענין תשובה כי גדולה תשובה שמגעת עד כסה\"כ. וזהו שהעלו אבק עד כסה\"כ שהוא בחי' תשובה.\n<b>והנה</b> בפי' אבק י\"ל לשון אבוקה<sup data-n=\"187\">12</sup>, ופי' אבוקה הנה ארז\"ל למה צדיקי' דומין בפני השכינה כנר בפני אבוקה כמ\"כ ההפרש שבין צדיקי' לבע\"ת, כי הנה הצדיקי' נק' נר וכמ\"ש נר הוי' נשמת אדם, אבל בע\"ת דמשכין בחילא יתיר הם ממשיכי' בחי'",[["185","10","<b>ואבק מל' דלעו\"ז</b>: ראה עד\"ז בתו\"א וישלח שם כו, ד: והאבק הוא מל' דקליפה. ובאוה\"ת חוקת ע' תשעא: אבק מל' דנוגה. ועד\"ז כ' באוה\"ת שה\"ש שם. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380876\" data-slug=\"likkutei-torah\" data-id=\"4001380876\">לקו\"ת תצא לט, סע\"ד</a>: בחי' אבק דאשתאר מן נורא שהיא המדרי' התחתונה שבקליפות. [וראה ספר הערכים שם ע' סג הע' 5]."],["186","11","<b>ויובן יותר ההפרש שבין אבק לעפר</b>: בהבא לקמן (עד פיסקא: וזהו צמאה נפשי) ראה אוה\"ת שה\"ש שם ע' תשכ."],["187","12","<b>והנה בפי' אבק י\"ל לשון אבוקה</b>: ראה בארוכה אוה\"ת שה\"ש שם (ע' תשכ). וראה גם אוה\"ת ויצא קפח, א. ספר הערכים חב\"ד ח\"א ע' טו ואילך (ערך אבוקה)."]]],[2000460134,"אבוקה שאבוקה למשל מריבוי נרות וכמ\"ש וישע ה' אל הבל כו' שהוא בחי' ש\"ע נהורין<sup data-n=\"188\">13</sup> ריבוי אורות כו' שהוא בחי' אבוקה. וזהו ע\"י שהעלו אבק עד כסה\"כ שהעלו בחי' אבק בבחי' תשובה עי\"ז המשיכו בחי' אבק בחי' אבוקה.\n<b>ובזה</b> יובן ענין אבוקה להבדלה מצוה כמשנ\"ת בענין המבדיל בין קדש לחול<sup data-n=\"189\">14</sup> שזהו הפרסה שבין עשי' לע\"ס דנוגה, והיא עתיק דנוגה, ונודע כי שבת אותיות תשב נותנת כח בג' ימים דבתר שבתא שיתברר מהחול ע\"ד חולין שנעשו על טהרת הקדש, ועי\"ז נמשך תוס' אורות וזהו אבוקה להבדלה, או שהאבוקה הוא בכדי שיכללו כנר בפני האבוקה כו', וכ\"ז הוא ע\"י המשכה פנימיות דיעקב.\n<b>וזהו</b> צמאה נפשי כו' מתי אבא<sup data-n=\"190\">15</sup> ואראה פני אלקי', ולכאו' אינו מובן מ\"ש ואֵרָאֶה דהל\"ל ואֶרְאֶה. אך הענין הוא דהנה כתי' עין בעין יראו, והנה פי' עין בעין, דהנה יש שני בחי' עין, עין דיחו\"ע ועין דיחו\"ת, אספקלריא המאירה ואספקלריא דלא נהרא, וזהו מ\"ש כל הנביאי' נתנבאו בכה ומשה נתנבא בזה, כה הוא אספקלרי' דלא נהרא וזה אספקלריא המאירה<sup data-n=\"191\">16</sup>, וידוע ההפרש שבין אספקלריא המאירה לאספקליא דלא נהרא, כי אספקלריא דלא נהרא הוא כמו ענין המראה שקורין שפיגל אף שרואין בה דמות האדם, אעפ\"כ אינו נראה עצמות האדם דרך המראה רק דמות בחי' האדם, אבל אספקלריא המאירה היא כמו זכוכית לבנה ובהירה שנראה בה עצמות האדם ממש. כמו\"כ יובן ההפרש שבין משה לשאר נביאים, כי כל הנביאים ראו דרך אספקלריא שאינה מאירה לא ראו רק דמות כו', וכמ\"ש ביד הנביאים אדמה, וכתי' הוא מראה דמות כבוד הוי' שהוא רק דמות לבד. אבל משה ראה דרך אספקלריא המאירה כמ\"ש פנים אל פנים כו', וזהו ב' בחי' עין. וזהו ענין עין בעין יראו שיומשך בחי' עין שהוא אספקלריא המאירה בחי' יחו\"ע בעין בחי' יחו\"ת ממש, ויהי' בחי' יחו\"ת כמו יחו\"ע ממש. וזהו ואֵרָאֶה בכל אחד בנפשו יהי' מאיר בו בחי' יחו\"ע ממש אספקלריא המאירה. וזהו בחי' יעקב שממשיך גילוי אלקי' בבחי' פנימי', כי הנה המשכה פנימי' בבחי' הארת פנים יאר ה' פניו הוא בחי' התורה, והנה כתי' ויקם עדות ביעקב ותורה שם בישראל שהתורה המשכ' פנימי' שייך ליעקב כו'.",[["188","13","<b>וישע ה' אל הבל. . ש\"ע נהורין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370099\" data-slug=\"torah-or\" data-id=\"3901370099\">תו\"א ויצא כא, א</a>. כב, א. ובכ\"מ."],["189","14","<b>כמשנ\"ת בענין המבדיל בין קדש לחול</b>: ד\"ה כרמי כו' האלף לעיל ע' י ואילך. וד\"ה ואמנם כו' האלף לעיל ע' כא ואילך. וד\"ה ויירא ויאמר לעיל ע' לד ואילך."],["190","15","<b>וזהו צמאה נפשי כו' מתי אבא</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480095\" data-slug=\"or-hatorah-hb\" data-id=\"8316480095\">אוה\"ת וישלח (כרך ה) שם תתעח, ב</a>. תתעט, רע\"א."],["191","16","<b>הנביאי' נתנבאו בכה ומשה. . בזה. . אספקלרי' דלא נהרא. . המאירה</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370153\" data-slug=\"torah-or\" data-id=\"3901370153\">תו\"א מקץ לג, א</a> ואילך. סה\"מ תרל\"ב ח\"א ס\"ע פ' ואילך. וס\"ע צח ואילך. וש\"נ."]]],[2000460135,"<b>וזהו</b> מ\"ש דור דורשיו מבקשי פניך יעקב סלה, לפי שיעקב הוא ממשיך בבחי' פנימי'<sup data-n=\"192\">17</sup>. וזמ\"ש הקול קול יעקב קלא קדמאה חסר וא\"ו שהוא בחי' קלא פנימאה דלא אשתמע בחי' קול התפילה, וקול הב' הוא בחי' קול התורה<sup data-n=\"193\">18</sup> שהתורה היא המשכ' פנימי', והיינו שע\"י קול התפילה וקול דתורה אזי הוא בחי' יעקב שהוא המשכ' פנימי'. וזהו דור דורשיו כו' פניך יעקב, פי' מי שהוא מבקש פניך ע\"י תורה ותפילה. והנה בחי' פניך אין ביכלתינו להמשיך בבחי' גילוי וכמ\"ש ופני לא יראו, שבחי' פני כמו שהוא א\"א להמשיך, ע\"ז אמר יעקב סלה שעכ\"פ בחי' ומדריגות יעקב שהוא ג\"כ המשכה פנימית זה יש ביכלתינו להמשיך, כי משה מלגאו יעקב מלבר וע\"כ בחי' יעקב יש בידינו להמשיך.\n<b>וזהו</b> ענין מ\"ש כמים הפנים לפנים כן לב כו' פי' שכשמביטין במים נראה דמותו במים דהיינו הבבואה, והנה התורה היא בחי' מים וכמ\"ש כל צמא לכו למים. והנה כשהאדם קורא בתורה הקב\"ה קורא ושונה כנגדו כו', כן לב האדם כו' שהוא בחי' לב האדם העליון אל האדם התחתון כו'. וסדר ההמשכה הוא בהשתלשלות המדריגות, תחילה כמים הפנים לפנים בבחי' מוחין, ואח\"כ כן לב האדם כו' בבחי' מדות, שיהי' לב האדם העליון לבחי' אדם התחתון שיהי' בחי' אהבה מלמעלה אהבתי אתכם אמר ה' כנ\"ל.",[["192","17","<b>שיעקב הוא ממשיך בבחי' פנימי'</b>: בכת\"י מעתיק הנ\"ל נמצא כאן עוד קטע (שלא ניתן להעתיק): (וזהו מ\"ש ויקרא שם המקום פניאל כי ראיתי אלקי' פא\"פ בחי' יחו\"ע בבחי' יחו\"ת. והנה מ\"ש פניאל זהו ענין מ\"ש חלו נא פני אל, ולשון חלו נא זהו כמ\"ש ויחל משה וארז\"ל מלמד שהחלה א\"ע, והיינו בבחי' חולת אהבה, והיינו לפי שכדי שיומשך בחי' פנימי' זהו ע\"י התפילה בחי' אהבה חולת אהבה שיהי' לו רצון ותשוקה בזה כו' עי\"ז ממשיך גילוי אלקות בבחי' פנימיות, וזהו ויקרא כו' פניאל שע\"י מה ממשיכי' בחי' פנימי' זהו ע\"י חלו נא פני אל שצריך שיהי' לו תשוקה בזה)."],["193","18","<b>הקול קול יעקב. . קול התפילה. . קול התורה</b>: ראה סידור עם דא\"ח יט, א-ב. סה\"מ תרל\"א ע' עט. לקמן סד\"ה וישב יעקב. וסד\"ה שמע ישראל."]]],[2000460136,"<h3>וישב יעקב</h3>\n<b>בס\"ד.</b>\n<b>וישב</b> יעקב<sup data-n=\"194\">1</sup> בארץ מגורי אביו בארץ כנען. אלה תולדות יעקב יוסף כו'. להבין ענין זה גם כפל לשון בארץ מגורי אביו בארץ כנען. גם י\"ל מ\"ש אלה תולדות יעקב יוסף כיון שכתי' אלה לשון רבים וא\"כ למה נזכר יוסף לבד.\n<b>ולהבין</b> זה ילה\"ק מתחלה ענין מה שנא' בשל\"ה שהפרשה שקורין לפני השבוע שייך לשבוע זה. והנה פרשה וישב קורין קודם חנוכה, וא\"כ צ\"ל שייכות פ' זו לחנוכה. והענין הוא דהנה ימי חנוכה תמניא אינון כו', והקשו כל המפרשים למה תקנו ימי חנוכה תמניא שהרי הנס הי' רק שבעה ימים, שעל יום א' הי' מחזיק הפך שמן, ותירצו שם מה שתירצו.\n<b>והנה</b> להבין זה ילה\"ק קצת מה שנמצא בתשו' הרשב\"א שיש מועדים שהם רק שבעה ימים כמו פסח הוא שבעה, שענין שבעה הוא כנגד שבעה ימי בראשית, ששת ימים עשה הוי' את השמים ואת הארץ וביום השביעי שבת כו' שהוא בחי' שבעת ימי הבנין, ומה שיש ג\"כ בחי' שמונה ימים<sup data-n=\"195\">2</sup>, שמונה הוא למעלה מהשבעה שהשבעה הוא בחי' שבעת ימי הבנין שהם נקראי' שבעת ימי ההיקף לפי שהשבעה הנ\"ל הם בבחי' היקף. לפי שבאמת אינו מובן איך אנו קורין יום ראשון יום שני, והלא מבריא' העולם יש כמה אלפי' רבבות ימים<sup data-n=\"196\">3</sup>, אלא לפי ששבעת ימי בראשית הם שבעת ימי ההיקף שבכל שבעה חוזרין חלילה, לפי שביום ראשון מאיר בחי' חסד וביום שני מאיר מדת הגבורה כו'. וכן חוזרין חלילה ונקראי' שבעת ימי ההיקף. והנה שמיני הוא בחי' שומר את ההיקף שלמעלה משבעת ימי הבנין, וכמו ששביעי הוא למעלה מהששי, וכמשארז\"ל ברבות כל השביעין חביבין, בשנים שנה השביעי שמיטה, בחדשים בחדש השביעי באחד לחדש הוא ר\"ה, וכמ\"כ שמיני הוא למעלה משבעה, וכמארז\"ל על המילה שניתנה בשמיני כדי שיעבור עליו שבת א' שהוא למעלה משבת, ולכך מילה דוחה שבת, וכן עד\"ז הוא שנת היובל, שמתחלה סופרי' שבעה שבועו' ואח\"כ בשנת החמשים הוא יובל, שהיובל עצמו היא מדרגת שמיני וכולל בו ז' שמיטות שכל שמיטה בשנים הוא כדוגמת מועד של שבעה",[["194","1","<b>וישב יעקב</b>: מאמר זה מיוסד על ד\"ה וישב יעקב ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670116\" data-slug=\"or-hatorah-hb\" data-id=\"8158670116\">אוה\"ת חנוכה רסח, א</a>-ב. ונמצא ג\"כ בכת\"י 1063 קיג, א [הוא ס' הנחות של מאמרי כ\"ק הצ\"צ], ובס' תרל\"ט כאן (כת\"י 1069) ניתוספו הגהות בגוכי\"ק אדמו\"ר מהר\"ש.\nהמשך המאמרים לקמן — ד\"ה: מי כה' אלקינו, אמר ריב\"ל עתיד הקב\"ה להנחיל, ואהבת את ה' אלקיך, שמע ישראל, צאינה וראינה — כולם הם מיוסדים ותוס' הגהות (מהדו\"ב) על מאמר ד\"ה וישב יעקב כאן."],["195","2","<b>בתשו' הרשב\"א. . שבעה. . בחי' שמונה ימים</b>: בהבא לקמן ראה גם סה\"מ תרע\"ח ע' רסט ואילך. תש\"ד ע' 188 ואילך. תש\"ה ע' 167 ואילך. תשי\"ג ע' 395 ואילך. ועוד."],["196","3","<b>איך אנו קורין יום ראשון. . והלא. . יש כמה אלפי' רבבות ימים</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו\"ת שה\"ש כה, סע\"א</a>. ובכ\"מ."]]],[2000460137,"שבימים כו', וכן שבועו' הוא ג\"כ עד\"ז שמתחלה סופרי' שבעה שבועו' ואח\"כ ביום החמשים הוא חג שבועות שהוא בחי' שער הנון דבינה שזהו ענין יו\"ט דשבועות עצמו מלבד מה שהתורה ניתנה בו, והו\"ע הטבילה כמ\"ש בזהר שבצאת ישראל ממצרי' היו צריכים הפסק טהרה ובדיקה, וז\"ע שארז\"ל במשנה אור לארבעה עשר בודקין את החמץ לאור הנר שהו\"ע הבדיקה של החמץ הוא היצה\"ר שנק' חמץ כמ\"ש מכף מעוול וחומץ, ושרשו מבחי' הגבורות, כענין בחי' החמשה דמים שטמאים באשה, ואח\"כ צ\"ל ספירת ז' נקיים שז\"ע ז' שבועות תספור לך, שלהיות זהו בכלליות נש\"י לכן אינו מספיק ספירת ז' נקיים כמו באשה יחידית, שנא' בה וספרה לה שבעת ימים, כ\"א ז' שבועות ימים, ואח\"כ יום החמשים הוא הטבילה שבו הוא היחוד שהו\"ע מ\"ת דכתי' ביום חתונתו וארז\"ל זו מ\"ת והגם שקאי על לוחות האחרונות שניתנו ביוהכ\"פ, אמנם באמת כ\"ה גם בלוחות הראשונות שהי' עיקר היחוד (רק שלא נתקיימו לכן גם לוחות אחרונות הם חתונתו כו'), והוא כמשל המשכת טיפת האב כו' שבנמשל ז\"ע מה שאורייתא מחכ' נפקת, בחי' טיפת אבא דאצי' כמ\"ש מזה במ\"א באריכות, עמ\"ש בד\"ה וספרתם לכם שלא נדפס<sup data-n=\"197\">4</sup>, והיינו להוליד בדומה לו בחי' ואנשי קדש תהיון לי ע\"י אקב\"ו, ולכן יאמרו לפניהם קדוש כדרך שאומרים כו' שז\"ע בדומה לו כו'. ונמצא ששמיני הוא למעלה משבעה, וזהו שארז\"ל כינור של בהמ\"ק הי' של ז' נימין ולעתיד יהי' של ח' נימין. וזהו ההפרש שבין משה למב\"ד<sup data-n=\"198\">5</sup>, שמשה הוא מדרגת שביעי כי משה הי' דור שביעי לאברהם, ולכך הי' משה חביב וניתנה התורה על ידו, אך מב\"ד יהי' מדרגת שמיני, ולכן יהי' על ידו התגלות פנימי' התורה כו'. והנה עד\"ז תיקנו ימי חנוכה תמניא דוקא שהמשיכו ממדריגת שמיני שהוא שומר את ההיקף, לפי שערבים עלי דברי סופרי' יותר מיינה של תורה, כי תורה ניתנה ע\"י משה שהוא דור שביעי, משא\"כ ד\"ס המשיכו ממדריגת שמיני.\n<b>ובזה</b> יובן מה ששייך פ' וישב לחנוכה, כי הנה איתא שג' רגלים הוא כנגד ג' אבות, פסח כנגד אברהם שנא' בו לושי ועשי עוגות, ושבועות הוא כנגד יצחק אילו של יצחק שבמ\"ת הי' קול שופר, וסכות הוא כנגד יעקב ויעקב נסע סכותה, והנה שמע\"צ הוא כנגד יוסף וכמ\"ש בזהר ע\"פ ולא עמד איש איתו בהתוודע יוסף אל אחיו שזה\"ע ביום השמיני עצרת תהי' לכם, ולכך נחשב שמע\"צ רגל בפ\"ע, נמצא שיוסף הוא מדרגת שמיני, ולזה קורין פ' זו קודם חנוכה, שחנוכה הוא ג\"כ מדרגת שמיני כו'.\n<b>והנה</b> להבין מ\"ש בארץ מגורי אביו<sup data-n=\"199\">6</sup> בארץ כנען, הנה כתי' אתהלך לפני ה' בארצות החיים, שיש שני ארצות שהם בחי' ג\"ע העליון וגעה\"ת, וכמ\"ש כל ישראל יש",[["197","4","<b>בד\"ה וספרתם לכם שלא נדפס</b>: ראה אוה\"ת דרושים לחה\"ש ע' ריד (הוצאת תשנ\"ה)."],["198","5","<b>למב\"ד</b>: בכת\"י המעתיק הי' רשום: למשיח. ובמקום זה תוקן בגוכי\"ק אדמו\"ר מהר\"ש: למב\"ד למשיח בן דוד]. ונראה שתיקון זה הוא מפאת הצענזור."],["199","6","<b>והנה להבין מ\"ש בארץ מגורי אביו</b>: מכאן (עד פיסקא: והענין הוא דהנה כתיב) הוא ע\"פ לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370125\" data-slug=\"torah-or\" data-id=\"3901370125\">תו\"א וישב כו, ג</a>-ד בשינויים ובתוס' הגהות. וראה גם תו\"ח וישב נז, א ואילך [ובהמ\"מ שם]. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480114\" data-slug=\"or-hatorah-hb\" data-id=\"8316480114\">אוה\"ת וישב (כרך ב) רנא, ב</a> ואילך. שם (כרך ה) תתפח, א ואילך."]]],[2000460138,"להם חלק לעוה\"ב שנא' ועמך כולם צדיקי' לעולם ירשו ארץ, נמצא שארץ הוא בחי' ג\"ע, ויש ב' בחי' ג\"ע, וזהו שנא' בארצות החיים. וביאור הענין צריך להבין למה נק' א\"י בכל התורה ארץ כנען ומה הוא היחוס והלא נא' ארור כנען עבד עבדים יהי' לאחיו, וגם שחם הוא אבי כנען ומה היחוס שבח א\"י בזה, (גם להבין מ\"ש כנען בידו מאזני מרמה), גם מה שכתוב ולא יהי' עוד כנעני בבית ה' צבאות ביום ההוא, שמשמע שביום ההוא דוקא לא יהי' כנעני אבל עכשיו שמשמע שיש כנעני בבית ה' צבאות ואם הפי' כפשוטו איך נמצא כנעני בבית ה'. אך הענין הוא דהנה נודע שכל התורה כולה נדרשת בזה לעומת זה, כי כמו שיש לבן כו' ושרי פרעה בקליפה וכמ\"ש ארמי אובד אבי כך יש כל בחי' אלו בקדושה, שיש ג\"כ לבן דקדושה (וכמ\"ש לבושי' כתלג חיור ושער רישי' כעמר נקא, וכן כתי' וישכם לבן בבקר שקאי על לבן דקדושה, ולכן הי' כה\"ג מתלבש ביוה\"כ בד' בגדי לבן דוקא, שלבן דקדושה הוא מדרגה גבוה מאד). והנה שלשה בני נח הם למעלה בקדושה ג' בחי' גווני קשת חיור סומק וירוק, שלנח נתן הקשת ושלשת בניו הם ג' בחי' גווני קשת, אלא שבהשתלשלות העולמות בבחי' נפילה מדרגה אחר מדריגה נעשה חם גשמי אבי כנען שהוא בחי' חמימות רשפי אש התאוה (וכן עד\"ז יש בקדושה ג\"כ חמימות רשפי אש הקדושה, שזהו מ\"ש בלחם הפנים שהי' חם כיום הלקחו שהוא בחי' חם דקדושה כו').\n<b>ולהבין</b> ענין כנען בקדושה הנה כנען פי' סוחר כמ\"ש כנעני' נכבדי ארץ, וכתי' כנען בידו מאזני מרמה, והיינו עד\"מ כמו הסוחר שמפזר ממון כסף וזהב ומוציאם מרשותו כדי להרויח ולהשתכר ואף שספק אצלו אם ירויח או לאו אעפ\"כ הוא מפזר אולי ירויח ומכניע א\"ע לספק זה להיות מפזר אולי נוסף עוד, כך הנה מקור נש\"י שהיא בחי' כנס\"י נמשלה לסוחר זה, (וזהו מ\"ש באברהם וישקול אברהם לעפרון ארבע מאות שקל כסף עובר לסוחר, שארבע מאות שקל כסף הוא ת' עלמין דכסופין, שנמשכי' מעולם התענוג, ואברהם נתן אותם לעפרון, וזהו עובר לסוחר שזהו עד\"מ כסוחר שמפזר ועי\"ז נוסף עוד), וכך הנה כנס\"י בגלות מצרים נמשלו לסוחר וכמ\"ש וזרעתי' לי בארץ כלום אדם זורע קב אלא להוציא ממנה כמה כורין, והיינו שעי\"ז מתבררי' ניצוצי הנשמות שנפלו בשבה\"כ וכמשארז\"ל לא גלו ישראל אלא בשביל להוסיף עליהם דהיינו ניצוצי הנשמות שנפלו כו', וכמ\"ש עת אשר שלט האדם באדם לרע לו, דהיינו מה ששולט אדם דלעו\"ז באדם דקדושה הוא לרע לו כדי שעי\"ז יתבררו ניצוצי הנשמות כו', ולכן נמשלו נש\"י לסוחר שעי\"ז שמפזר נוסף עוד, כך נש\"י נמשלו לסוחר, (וזהו שנק' הקב\"ה בשם קונה וכמ\"ש קונה שמים וארץ, קונה הכל, לפי שזהו ע\"ד כמו סוחר שמפזר כו' ועש\"ז נק' גם הקב\"ה בשם קונה), וכמו שהוא בכללות העולם כך הוא בפרטיות בכל נפש מישראל בעבודת ה' כי הנה הנשמה טרם ירידתה לעולם הזה להתלבש בגוף ונה\"ב היתה קשורה ומיוחדת"],[2000460139,"במקורה ושרשה במאצילה ברשפי אש האהבה בטבע כשלהבת העולה מאלי' והיתה נהנית מזיו השכינה והי' לה בחי' אהבה ויראה טבעית בגילוי רב שהוא בחי' כסף וזהב מלשון נכסוף נכספתי, דהיינו בחי' אהבה, וזהב מצפון יאתה שהוא בחי' שמאל שהוא בחי' יראה, ואח\"כ כשירדה הנשמה לעוה\"ז להתלבש בגוף הגשמי הנה גם בחי' אהוי\"ר שהי' לה שם הם מוסתרות ומכוסות בלב הגשמי ואינה יכולה לראות<sup data-n=\"200\">7</sup> באהוי\"ר בהתגלות כ\"כ כבתחלה, נמצא שנגרעו האהוי\"ר מערכם וא\"כ למה זה ירדה הנשמה לעוה\"ז מאחר שהיא ירידה גדולה וגרעון גדול מבתחלה שהוא בחי' פיזור כסף וזהב, אך הנה פיזור הוא בשביל ריוח.\n<b>ולהבין</b> מהו ענין הריוח דהנה כתי' טוב לי תורת פיך מאלפי זהב וכסף, אלפי לשון לימוד, שיש לי יתרון מעלה בתורת פיך בעוה\"ז יותר מבחי' זהב וכסף שהיתה הנשמה למודה בהם בתחלה.\n<b>והענין</b> הוא דהנה כתי'<sup data-n=\"201\">8</sup> ביום חתונתו זו מ\"ת, שתו' נק' בשם חתונה בחי' יסוד, והיינו שע\"י תומ\"צ שלמטה עי\"ז מתאחדת הנשמה באא\"ס ממש שהוא בחי' לאשתאבא בגופא דמלכא ממש וכמשל יחוד חתן וכלה שנעשים אדם אחד ממש, וכמ\"ש זכר ונקבה בראם ויקרא שמם אדם ונק' תרי פלגא גופא כמ\"ש בזהר, משא\"כ הנשמה קודם ירידתה לעוה\"ז אף שהי' לה אוי\"ר בהתגלות אעפ\"כ היתה בבחי' נפרד, וכמו המלאכי' שהם נפרדי' אף שאומרי' קדוש וברוך תמיד באהבה ברשפי אש, אבל ע\"י התורה עי\"ז מתאחדי' ממש לפי שהתורה היא בחי' תורת הוי', וכן במצות נא' מצות הוי', הקב\"ה מניח תפילין ומתעטף בציצית כו', והמצות עליונות ממש כמו שהן למעלה נמשכו ונתלבשו למטה במצות גשמי', ואף שנתלבשו בגשמי', אך באמת היא הנותנת כו' וכמ\"ש במ\"א<sup data-n=\"202\">9</sup>, וזהו המשל מבחי' חתונה שאף שהטפה שנמשך ממוח האב היא נתגשמה ממש בבחי' טפה גשמי' מ\"מ מלובש בה מעצמיות המוחי' ממש, שהרי מטפה זו נתהווה להוליד בדומה לו ממש, וכך עד\"מ זה יובן שמה שהקב\"ה מניח תפילין כו' כי ע\"י שאנו מניחי' תפילין שלנו, עי\"ז ממשיכי' שיהי' הקב\"ה מניח תפילין וכידוע, וע' מ\"ש במ\"א בענין פי' המד\"ר ע\"פ מגיד דבריו<sup data-n=\"203\">10</sup> ליעקב כו' מה שהוא עושה אומר לישראל לעשות שמה שהוא עושה כבי' זהו ע\"י שאומר כו', ונמצא שזהו הריוח של הפיזור כסף וזהב, שעי\"ז נכללי' הנשמו' באא\"ס ממש לאשתאבא בגופא דמלכא.",[["200","7","<b>לראות</b>: כ\"ה גם בתו\"א שם. ובהגהות כ\"ק אדמו\"ר מוהרש\"ב לתו\"א נתקן שצ\"ל: להיות. וכן נתקן לקמן בד\"ה מי כה' אלקינו."],["201","8","<b>והענין הוא דהנה כתי'</b>: פיסקא זו נמצאת ג\"כ בשינויים ובאריכות להלן בד\"ה אמר ריב\"ל (פיסקא: והענין הוא). ובד\"ה צאינה וראינה."],["202","9","<b>והמצות עליונות. . במצות גשמי'. . ואף שנתלבשו בגשמי'. . וכמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380496\" data-slug=\"likkutei-torah\" data-id=\"4001380496\">לקו\"ת שלח מו, א</a>. ועוד."],["203","10","<b>וע' מ\"ש במ\"א בענין פי' המד\"ר ע\"פ מגיד דבריו</b>: ראה סה\"מ תרכ\"ח ע' פז ואילך. תרכ\"ט ע' רכג. תרל\"ב ח\"ב ע' פד. תרל\"ד ע' נג."]]],[2000460140,"<b>וביאור</b> הענין איך ע\"י תומ\"צ<sup data-n=\"204\">11</sup> תהי' הנשמה מתאחדת באא\"ס ממש הענין הוא דהנה תורה נק' ביום חתונתו, והנה חתונה צריך מתחלה בחי' חופה, וע\"י החופה עי\"ז יכול להיות אח\"כ היחוד, וזהו מ\"ש מקדש עמו ישראל ע\"י חופה וקידושין, והנה חופה הוא ענין תשובה, והנה אע\"פ שנת\"ל שירידת הנשמה הוא בשביל תורה, הנה באמת ענין ירידת הנשמה הוא בשביל תשובה ג\"כ, דהנה הנשמה קודם שירדה לעוה\"ז היתה במדרגת צדיקי' אבל אח\"כ נעשה בחי' בע\"ת, והנה ארז\"ל יפה שעה אחת בתשומע\"ט בעוה\"ז מכל חיי העוה\"ב, ואין הפי' תשובה על עוונות דוקא אלא הפי' תשובה הוא כמ\"ש והרוח תשוב אל האלקי' אשר נתנה, דהיינו החזרת פב\"פ, דהנה אם אדם נמשך אחר גשמי' הוא בחי' רחוק מאלקות וכמו למשל ב' בני אדם שהם עומדים אחור באחור אף שעומדים מקרוב מ\"מ כיון שהם אחור באחור נקראים רחוקים, אבל כשהם עומדים פב\"פ נקראים קרובים וכמ\"כ למעלה בעבודה, הנה כשאדם נמשך אחר גשמי' אף שהוא סור מרע ועשה טוב מ\"מ כיון שהוא בבחי' חיצוני' נק' רחוק וכמ\"ש כי פנו אלי עורף ולא פנים, אף שפנו אלי הוא רק בבחי' עורף, אבל תשובה היא החזרת פב\"פ שהוא בחי' אהבה בבחי' רעו\"ד דהיינו אהבה דבכל מאדך שהוא בלי גבול ממש.\n<b>והנה</b> כדי לבוא לבחי' אה' זו בבחי' רעו\"ד זהו דוקא למטה, כי הנשמות למעלה אף שהי' להם אהוי\"ר בהתגלות מ\"מ הוא רק בחי' בכל לבבך ובכל נפשך שאהבה זו מתלבשת בכלי הנפש משא\"כ אהבה דכל מאדך זהו דוקא למטה מבחי' העלם והסתר הגוף דוקא, כי יתרון האור הוא מתוך החשך דוקא, ונמצא שאע\"פ שיש לה גרעון<sup data-n=\"205\">12</sup> באהוי\"ר טבעיות שבחיצוני' הלב הגלוי' מ\"מ יהי' לה יתרון בבחי' רעו\"ד בנקודת פנימי' הלב כיתרון האור הבא מן החשך.\n<b>והנה</b> כדי לבוא לבחי' רעו\"ד<sup data-n=\"206\">13</sup> זהו ע\"י התבוננות, דהנה כתי' אני ראשון ואני אחרון ומבלעדי אין אלקי', פי' אני ראשון היינו כמו קודם בריאת העולמות, שהי' לבדו וכמ\"ש עד שלא נבה\"ע הי' הוא ושמו בלבד, ואני אחרון קאי על מה שיהי' לאחר נו\"ן אלפי' יובלות כו', ומבלעדי אין אלקי' פי' מה שהוא זולת בחי' זו דהיינו באמצעות הזמן שנראה העולם ליש ודבר בפ\"ע בחי' זמן ומקום אין אלקי' זולתי כו' כי אין ההסתר דש' אלקי' מסתיר לפניו כו', כי רק לעינינו נראה בחי' הסתר והעלם שנראה העולם ליש ודבר נפרד אבל באמת קמי' ית' אין הסתר, וכמו שהוא לבדו קודם שנבה\"ע כמ\"כ הוא גם עתה הוא לבדו הוא כי אין העולם תופס מקום כלל, וכמ\"ש אני הוי' לא שניתי, וכלא קמי' כלא חשיב ממש. והנה כשיתבונן אדם בבחי'",[["204","11","<b>וביאור הענין איך ע\"י תומ\"צ</b>: פיסקא זו ושלאחרי' נמצאת ג\"כ בשינויים ובאריכות להלן בד\"ה ואהבת את ה' אלקיך ובד\"ה צאינה וראינה."],["205","12","<b>ונמצא שאע\"פ שיש לה גרעון</b>: הבא לקמן הוא ע\"פ ל' התו\"א וישב שם כו, סע\"ב ואילך. בשינויים ובתוס' הגהות."],["206","13","<b>והנה כדי לבוא לבחי' רעו\"ד</b>: מכאן עד הסיום נמצא ג\"כ בשינויים ובאריכות להלן בד\"ה שמע ישראל."]]],[2000460141,"רוממות אלקות כו' ובפחיתות ערכו איך שהוא רחוק מאלקות אי לזאת תכלה ותכסוף נפשו ליבטל במציאות אליו ית' לצאת ממאסר הגוף ונרתקה להשתפך נפשה אל חיק אבי' בבחי' רעו\"ד ממש, משא\"כ הנשמה טרם ירידתה להתלבש בגוף היתה אהבתה ודביקותה בשרשה לפ\"ע השגתה וכן לענין היראה.\n<b>והנה</b> בזמן שבהמ\"ק הי' קיים הי' נמשך בחי' זו רעו\"ד מגילוי אא\"ס ב\"ה בהיכל ק\"ק, דהנה איתא עשה רצונו כרצונך<sup data-n=\"207\">14</sup> כדי שיעשה רצונך כרצונו, פי' שיעשה רצונך כרצונו דהיינו כמו שרצה\"ע ב\"ה הוא בלי גבול ממש כמ\"כ יהי' רצון האדם ג\"כ בלי גבול בחי' רעו\"ד. והנה באמת האדם מצ\"ע אי אפשר לו להגיע לבחי' רצון זה, רק שרצון זה נמשך מלמעלה, וזהו מ\"ש רז\"ל כדי שיעשה רצונך כרצונו שהקב\"ה עושה רצון זה באדם, וכמ\"ש פותח את ידיך ומשביע לכל חי רצון, שהקב\"ה משביע רצון זה, רק שמתחלה צריך שיהי' פותח את ידיך, ידיך הוא בחי' יודי\"ך, דהיינו פתיחו דיודין יו\"ד בחי' חכ' דהיינו שיעשה האדם רצון העליון ב\"ה כרצונו, שמתחלה צריך לייגע אדם א\"ע שיגיע לבחי' רצון שע\"פ חכ' שהוא בחי' רצון התחתון ועי\"ז אח\"כ ומשביע לכל חי רצון, רצון שלמעלה מן השכל. וזהו עשה רצונו כרצונך, שמתחלה צריך שיעשה האדם רצון העליון ב\"ה כרצונו ממש, שהוא בחי' רצון שע\"פ השכל, ועי\"ז יעשה הקב\"ה רצונך כרצונו.\n<b>והנה</b> בזמן בהמ\"ק הי' עושים רצונו ש\"מ ע\"י עבודת הקרבנות וכמ\"ש ריח נחוחי ופי' רז\"ל נחת רוח לפני שאמרתי ונעשה רצוני, ועי\"ז שהיו עושים רצונו ש\"מ עי\"ז הי' נמשך מלמעלה שיגיעו לבחי' רצה\"ע ממש, אך בזמן הגלות מצרים הנה כתי' ובקשתם משם את ה' אלקיך ומצאת, משם דוקא דהיינו מסט\"א, וכמ\"ש קראו שם פרעה<sup data-n=\"208\">15</sup> מלך מצרי', כי אלקי' יכולי' למצא בכל מקום. וביאור ענין משם זהו ע\"ד שארז\"ל על ר\"ע כשראה כרך גדול של רומי שחק ואמר אם לעוברי רצונו כך לעושי רצונו עאכו\"כ, והיינו שאנו רואי' שעוברי רצונו מקבלי' השפעתם יתירה שלא לפ\"ע מעשיהם כלל, ומאין נשפע להם שפע וחיות להיות בהם חיות וקיום מרצונו ית', שהרי רצונו ית' הוא המחי' אותם וכמ\"ש ואתה מחי' את כולם, אך ע\"ז אמרו כמה ארך אפים לפניו<sup data-n=\"209\">16</sup> שמבחי' ארך אפים נמשך ונשתלשל ממדרגו' העליונו' דרך נפילה להחיות העובדי כוכבי' אף שהם עוברי רצונו, וזהו אם לעוברי רצונו כך שהם מקבלי' מבחי' רצה\"ע שלמעלה מן השכל לעושי רצונו עאכו\"כ שיקבלו מבחי' רצה\"ע שהוא למעלה מעלה מגדר עלמין שלא בבחי' ירידות והשתלשלות המדרגו' בבחי' חכ' ומדות אלא בבחי' פנימי'",[["207","14","<b>דהנה איתא עשה רצונו כרצונך</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381232\" data-slug=\"likkutei-torah\" data-id=\"4001381232\">לקו\"ת שה\"ש כה, ד</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380316\" data-slug=\"likkutei-torah\" data-id=\"4001380316\">לקו\"ת במדבר ב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380796\" data-slug=\"likkutei-torah\" data-id=\"4001380796\">ראה כ, א</a>. ובכ\"מ."],["208","15","<b>ובקשתם משם. . דהיינו מסט\"א. . קראו שם פרעה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380845\" data-slug=\"likkutei-torah\" data-id=\"4001380845\">לקו\"ת ראה לב, ג</a>."],["209","16","<b>ע\"ז אמרו כמה ארך אפים לפניו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>."]]],[2000460142,"נקודת הלב שהוא בחי' תשו\"ע שקדמה לעולם, וזהו כי תדרשנו בכל לבבך ובכל נפשך, שתחילה צ\"ל בכל לבבך ובכל נפשך אהבה שע\"פ טעם ודעת וכמ\"ש לאהבה את ה' כי הוא חייך כו', וכן בענין המצות הנה נודע כי אהוי\"ר הם שרש רמ\"ח מ\"ע ושס\"ה ל\"ת, וזהו עשה רצונו כרצונך שהרי התומ\"צ נתלבשו בדברי' גשמיים והם יכולי' להיות נעשים כרצונך שע\"פ טו\"ד כו' ועי\"ז הקב\"ה נותן לנו כח ועוז שיעשה רצונינו כרצונו בלי גבול שזהו בחי' בכל מאדך רעו\"ד, והיינו שיהפוך לבו מן הקצה אל הקצה ואהתפכא חשוכא לנהורא על ידי בחי' רעו\"ד זו למאוס בחיי עוה\"ז ותענוגי' ולימשך לבו ונפשו לדבקה בו ית'.\n<b>והנה</b> כ\"ז ע\"ד משל הסוחר שמוציא כסף וזהב מרשותו להיות מפזר ונוסף עוד, כך הנשמה אע\"פ שמוציאה כסף וזהב שהוא בחי' אוי\"ר הגלוים להתלבש ולהסתיר בגוף ונה\"ב, הנה עי\"ז יש לה יתרון בבחי' רעו\"ד כרשפי אש מן ההיפוך. וזהו וחם הוא אבי כנען בזקף גדול שחמימות רשפי אש ושלהבת העולה מאלי' מן ההיפוך הוא העושה בחי' כנען לסוחר כנ\"ל, כמ\"ש טעמה כי טוב סחרה (והנה בחי' רעו\"ד זו הוא בחי' החופה לפי שאהבה מאיר בבחי' מקיף על הנפש שאין כלי הנפש יכולה להכיל את אהבה זו, ואח\"כ ביום חתונתו זו מ\"ת שע\"י התורה נעשה בחי' היחוד שהוא בחי' לאשתאבא בגופא דמלכא כו'). וזהו מ\"ש הקל קול יעקב<sup data-n=\"210\">17</sup> קלא קדמאה חסר וי\"ו שהוא בחי' קלא דלא אשתמע וקול בתראה מלא וי\"ו שהוא בחי' המשכה כמשל הקול המחבר וממשיך מצפוני כוונת הלב לבוא לידי גילוי בדבור, וכך התורה הוא בחי' ח\"ע בחי' חכים ולא בחכ' ידיעא, שהרי טעמי המצות לא נתגלו להיות בהתגלות רב להבין כל עמקי סודותי' בפרטי פרטיות, ונמשכת לבחי' גילוי ע\"י התלבשותה בדברי' גשמי' סדר זרעי' מועד כו', והוא בחי' קול והמשכה של יעקב יו\"ד עקב דהיינו מבחי' יו\"ד שהוא ח\"ע להיות נמשך עד עקב והוא העשי', אך כדי שיהי' האדם כלי ומכון שיהי' ח\"ע שורה ומתגלה בו בעסק התורה צ\"ל תחלה בבחי' ביטול בבחי' רעו\"ד שהוא בחי' חופה והוא בחי' קלא דלא אשתמע דרוח אמשיך רוח להיות אור ה' שורה ומתגלה בו להיות חכ' ה' בקרבו בהתגלות וחב\"ד שבנפשו בטלי' וטפלי' אליו וה\"ע אתדבקות רוחא ברוחא.\n[סיום המאמר נמצא לקמן ע' פא פיסקא: וזהו וישב יעקב, ואילך]",[["210","17","<b>וזהו מ\"ש הקל קול יעקב</b>: ראה בכ\"ז סידור עם דא\"ח יט, א-ב. לעיל סד\"ה כמים הפנים."]]],[2000460143,"<h3>מי כה' כו' המגביהי כו' (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ וישב שבת חנוכה, ט\"ל).</b>\n<b>תלים קי\"ג ה' וא\"ו. </b>\n<b></b>אלה תולדות יעקב כו' ז' ח' כו' ד\"ס כו' טוב לי תורת פיך כו' סוחר כנען\nוישב\n<b>מי</b><sup data-n=\"e11\">*</sup> כה' אלקינו<sup data-n=\"211\">1</sup> המגביהי כו' המשפילי כו' ובארץ, ופי' רש\"י ז\"ל מי כו' בשמים ובארץ שיהא מגביה לשבת ומשפיל לראות, מגביהי משפילי מקימי להושיבי מושיבי, כולם יו\"ד יתירה בהם עכ\"ל. וצ\"ל לאיזהו צורך השמיענו רש\"י שהיודי\"ן הם יתירים בתיבות אלו, וגם הכוונה בפירושו שיהא מגביה לשבת ומשפיל לראות<sup data-n=\"e12\">*</sup>. ולהבין זה צריכי' להקדים תחלה מ\"ש אלה תולדות יעקב יוסף הלא הל\"ל אלה תולדות יעקב ראובן ומהו יוסף דוקא, וכ\"ש לפי מה שאמר אלה שהוא לשון רבים הי' לו לחשוב כסדר, ולמה הזכיר את יוסף לבד.\n<b>ובכדי</b> להבין ילה\"ק מ\"ש בשל\"ה שהפרשה שקורין לפני השבוע שייך לשבוע זה, והנה פרשה וישב קורין קודם חנוכה, או שבת חנוכה כו', וא\"כ צ\"ל שייכות פ' זו לחנוכה. והענין הוא דהנה ימי חנוכה תמניא אינון כו', והקשו כל המפרשים למה תקנו ימי חנוכה תמניא שהרי הנס הי' רק שבעה ימים, שעל יום א' הי' מחזיק הפך שמן, ותירצו שם מה שתירצו.\n<b>והנה</b> להבין זה ילה\"ק קצת מה שנמצא בתשו' הרשב\"א שיש מועדים שהם רק שבעה ימים כמו פסח הוא שבעה, שענין שבעה הוא כנגד שבעה ימי בראשית, ששת ימים עשה הוי' את השמים ואת הארץ וביום השביעי שבת כו' שהוא בחי' שבעת ימי הבנין, ומה שיש ג\"כ בחי' שמונה ימים<sup data-n=\"212\">2</sup>, שמונה הוא למעלה מהשבעה, שהשבעה הוא בחי' שבעת ימי הבנין שהם נקראי' שבעת ימי ההיקף לפי",[["211","1","<b>מי כה' אלקינו</b>: המשך זה כולל כמה מאמרים: א) ד\"ה מי כה' אלקינו. ב) ד\"ה אריב\"ל. ג) ד\"ה ואהבת. ד) ד\"ה שמע ישראל. ה) סיום הדרוש ד\"ה וזהו וישב יעקב. חלק מההמשך נמצא בשינויי הסדר לקמן ד\"ה צאינה וראינה (הא').\nמאמר זה הוא מהדו\"ב ותוס' הגהות לד\"ה וישב יעקב הנדפס לעיל (מתחילתו עד פיסקא: והענין הוא דהנה כתיב), וע\"ש בהמ\"מ. והוא מיוסד על ד\"ה וישב יעקב באוה\"ת וישב רסח, א-ב. ועל ד\"ה וישב יעקב בתו\"א כו, ג-ד [עי' במ\"מ לקמן פיסקא: ובכדי להבין זה].\nלקמן בחלק ההנחות, נדפסו הגהות על מאמר זה מגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["212","2","<b>בתשו' הרשב\"א. . שבעה. . בחי' שמונה ימים</b>: בהבא לקמן ראה גם סה\"מ תרע\"ח ע' רסט ואילך. תש\"ד ע' 188 ואילך. תש\"ה ע' 167 ואילך. תשי\"ג ע' 395 ואילך. ועוד."],["e11","*","<b>ומי כה' אלקינו</b>: בשולי הגליון נרשם בגוכי\"ק ציונים אלו:\nמי כו' זח\"א ק\"ח ד', זח\"ב י\"ז א', מד\"ר קנט ד', קסה ד', ש\"ך קנה א' (א\"ו קכה). המשפילי ר\"ח רל\"ב ב', מד\"ר קנט א', קסה ד', ילקוט ח\"ב קמג ג', ש\"ך קנה א'."],["e12","*","<b>מגביה לשבת ומשפיל לראות</b>: בצידי העמוד רשום בגוכי\"ק:\nאם זהו בדרך שבח שמשבחו שמגביהי לשבת עכ\"ז הנה הוא משפילי כו'. או שי\"ל כוונה אחרת כו'."]]],[2000460144,"שהשבעה הנ\"ל הם בבחי' היקף, לפי שבאמת אינו מובן איך אנו קורין יום ראשון יום שני, והלא מבריאת העולם יש כמה אלפי' רבבות ימים<sup data-n=\"213\">3</sup>, אלא לפי ששבעת ימי בראשית הם שבעת ימי ההיקף שבכל שבעה חוזרין חלילה, לפי שביום ראשון מאיר בחי' חסד וביום שני מאיר מדת הגבורה כו', וכן חוזרין חלילה ונקראי' שבעת ימי ההיקף, והנה שמיני הוא בחי' שומר את ההיקף שלמעלה משבעת ימי הבנין, וכמו ששביעי הוא למעלה מהששי, וכמשארז\"ל ברבות כל השביעין חביבין, בשנים שנה השביעי שמיטה, בחדשים בחדש השביעי באחד לחדש הוא ר\"ה, וכמו\"כ שמיני הוא למעלה משבעה, וכמארז\"ל על המילה שניתנה בשמיני כדי שיעבור עליו שבת א' שהוא למעלה משבת, ולכך מילה דוחה שבת, וכן עד\"ז הוא שנת היובל, שמתחלה סופרים שבעה שבועות ואח\"כ בשנת החמשים הוא יובל, שהיובל עצמו היא מדריגת שמיני, וכולל בו ז' שמיטות שכל שמיטה בשנים היא כדוגמת מועד של שבעה שבימים כו', וכן שבועות הוא ג\"כ עד\"ז שמתחלה סופרים שבעה שבועות ואח\"כ ביום החמשים הוא חג שבועות שהוא בחי' שער הנו\"ן דבינה, שזהו ענין יו\"ט דשבועות עצמו, מלבד מה שהתורה ניתנה בו, והו\"ע הטבילה כמ\"ש בזהר, שבצאת ישראל ממצרים הי' צריך הפסק טהרה ובדיקה, וז\"ע שארז\"ל במשנה אור לארבעה עשר בודקין את החמץ לאור הנר שהו\"ע הבדיקה של החמץ הוא היצה\"ר שנק' חמץ כמ\"ש מכף מעוול וחומץ, ושרשו מבחי' הגבורות, כענין בחי' החמשה דמים שטמאים באשה, ואח\"כ צ\"ל ספירת ז' נקיים שז\"ע ז' שבועות תספר לך<sup data-n=\"214\">4</sup>, שלהיות זהו בכלליות נש\"י לכן אינו מספיק ספירת ז' נקיים כמו באשה יחידית שנא' בה וספרה לה שבעת ימים, כ\"א ז' שבועות ימים, ואח\"כ יום החמשים הוא הטבילה שבו הוא היחוד שהו\"ע מ\"ת דכתי' ביום חתונתו וארז\"ל זו מ\"ת, והגם שקאי על לוחות האחרונות שניתנו ביוהכ\"פ, אמנם באמת כ\"ה גם בלוחות הראשונו' שהי' עיקר היחוד (רק שלא נתקיימו לכן גם לוחות אחרונות הם יום חתונתו כו') והוא כמשל המשכת טפת האב כו' שבנמשל ז\"ע מה שאורייתא מחכ' נפקת, בחי' טיפת אבא דאצי' כמ\"ש מזה במ\"א באריכות, עמ\"ש בד\"ה וספרתם לכם, שלא נדפס<sup data-n=\"215\">5</sup>, ונמצא ששמיני הוא למעלה משבעה, וזהו שארז\"ל כנור של בהמ\"ק הי' של ז' נימין ולעתיד יהי' של ח' נימין, וזהו ההפרש שבין משה למב\"ד, שמשה הוא מדרגת שביעי כי משה הי' דור שביעי לאברהם, ולכך הי' משה חביב וניתנה התורה על ידו, אך מב\"ד יהי' מדריגת שמיני, ולכך יהי' על ידו התגלות פנימי' התורה כו'.\n<b>והנה</b> עד\"ז תיקנו ימי חנוכה תמניא דוקא שהמשיכו ממדריגת שמיני שהוא שומר את ההיקף, לפי שערבים עלי דברי סופרים יותר מיינה של תורה, כי תורה",[["213","3","<b>איך אנו קורין יום ראשון. . והלא. . יש כמה אלפי' רבבות ימים</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו\"ת שה\"ש כה, סע\"א</a>. ובכ\"מ."],["214","4","<b>ספירת ז' נקיים שז\"ע ז' שבועות תספר לך</b>: ראה בכ\"ז בארוכה ביאוה\"ז לאדהאמ\"צ קמ, ג ואילך. ולהצ\"צ ח\"ב ע' תתקכז ואילך. תתקמז ואילך. סה\"מ תרכ\"ו ע' פז ואילך."],["215","5","<b>עמ\"ש בד\"ה וספרתם לכם, שלא נדפס</b>: ראה אוה\"ת דרושים לשבועות ע' ריד (הוצאת תשנ\"ה)."]]],[2000460145,"ניתנה ע\"י משה שהוא דור שביעי, משא\"כ ד\"ס המשיכו ממדרגת שמיני. והענין הוא כנודע<sup data-n=\"216\">6</sup> שד\"ס הם בשרשן גבוהים יותר הרבה גם מבחי' יינה של תורה שהוא בחי' פנימיות התורה, כמ\"ש בד\"ה זה שמי לעלם בפ' שמות ע\"ש<sup data-n=\"217\">7</sup>, אשר לכן לא ניתן לכתוב כלל לא הציווי למשה ולא האמירה דמשה לישראל, כ\"א בע\"פ דוקא, וכענין מ\"ש במ\"א בענין מפיו דעת<sup data-n=\"218\">8</sup>, שבחי' זו א\"א להיות מאיר ומתגלה אלא מפיו דוקא, ע' בד\"ה והי' אמונת עתך כו' ודעת, ולכן מצות דרבנן הם כמו עשה, ועכ\"ז מעלתם ע\"ד מצות ל\"ת ועוד יותר שזהו מטעם הנ\"ל ששרשם גבוה יותר כו', ולכן ערבים עלי בבחי' מקיף כו' שבהם יש מעלה יתירה על בחי' יינה ש\"ת ג\"כ, ולכן בכוחם גזרו גדרי' וסייגי', שזהו מפני שרשם מאד נעלה, וכענין אב המייסר את בנו שזהו מפני אהבתו הרבה והעצומה כו', וכמו כל מה שהחפץ יקר אצלו הוא מדקדק לשומרו יותר כו', וכעין מ\"ש בזהר בפי' הפסוק הן שמים לא זכו שזהו מפני גודל מעלתם לכן הדקדוק בהם יותר שעדיין לא זכו, כן יצא מפיו ית' בבחי' תושבע\"פ דוקא כל הדקדוקי' דד\"ס כו' מפני עוצם אהבתו לבחי' בני בכורי כו' שזהו מחמת גודל אהבתו שאהבתי אתכם אמר ה' לכן מדקדק לזכותינו כו', וזהו דוקא בזמן שאין בהמ\"ק קיים כו' כמובן, שבזמן שבהמ\"ק קיים לא הי' צרי' לזה כו', ויובן יותר ממארז\"ל והאיך לא אשא פנים כו' שמדקדקי' ע\"ע עד כזית כו' מובן שע\"י הדקדוק נמשך מבחי' נשיאות פניו אליך, בחי' אה\"ר שלמעלה מהשתלשלו' ושיומשך אליך דוקא, היינו להעלות גם הנה\"ב כמ\"ש בלק\"ת בד\"ה שחורה אני<sup data-n=\"219\">9</sup>, וזהו ישא ה' פניו אליך שיהי' גילוי אה\"ר זו גם באדם כו', וע' בד\"ה כי אתה נרי בפ' מקץ<sup data-n=\"220\">10</sup> בענין וה' יגיה חשכי, שלהגיה החשך שגם במקום החשך יאיר כו' זהו ע\"י בחי' וה' דוקא ש' הוי' דלעילא שלמעלה מהשתלשלות כו'. ומכ\"ז יובן מעלת מצות דרבנן ונ\"ח שהמשיכו בחי' ומדריגת שמיני דוקא כו'.\n<b>ובזה</b> יובן מה ששייך פ' וישב לחנוכה, כי הנה איתא שג' רגלים הוא כנגד ג' אבות, פסח כנגד אברהם שנא' בו לושי ועשי עוגות, ושבועות הוא כנגד יצחק אילו של יצחק שבמ\"ת הי' קול שופר, וסכות הוא כנגד יעקב ויעקב נסע סכותה, והנה שמע\"צ הוא כנגד יוסף וכמ\"ש בזהר ע\"פ ולא עמד איש אתו בהתוודע יוסף אל אחיו שזה\"ע ביום השמיני עצרת תהי' לכם, ולכך נחשב שמע\"צ רגל בפ\"ע, נמצא שיוסף הוא מדרגת שמיני, ולזה קורין פ' זו קודם חנוכה או בשבת חנוכה, לפי שחנוכה הוא ג\"כ מדריגת שמיני כו'.",[["216","6","<b>והענין הוא כנודע</b>: הבא לקמן עד סוף הפיסקא נרשם בגוכי\"ק כהגה\"ה. ובהעתקת המאמר בכת\"י 2207 (כת\"י הר\"ש סופר) נרשמה הגה\"ה זו בסיום המאמר, ונרשם ע\"ז: ”נכתב באופן אחר בסיום הדרוש\". [ויל\"ע הכוונה]."],["217","7","<b>כמ\"ש בד\"ה זה שמי לעלם בפ' שמות ע\"ש</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370236\" data-slug=\"torah-or\" data-id=\"3901370236\">תו\"א נב, ד</a>."],["218","8","<b>במ\"א בענין מפיו דעת. . בד\"ה והי' אמונת עתיך כו' ודעת</b>: אוה\"ת דרושים לחגה\"ש ע' פב."],["219","9","<b>בלק\"ת בד\"ה שחורה אני</b>: שה\"ש דף ו, סע\"א."],["220","10","<b>בד\"ה כי אתה נרי בפ' מקץ</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">תו\"א מא, א</a>."]]],[2000460146,"<b>ובכדי</b> להבין כ\"ז צ\"ל ג\"כ כפל הלשון שא' בארץ מגורי<sup data-n=\"e13\">*</sup> אביו<sup data-n=\"221\">11</sup> בארץ כנען, הנה כתי' אתהלך לפני ה' בארצות החיים שיש שני ארצות שהם בחי' ג\"ע העליון וגעה\"ת, וכמ\"ש כל ישראל יש להם חלק לעוה\"ב שנא' ועמך כולם צדיקי' לעולם ירשו ארץ, נמצא שארץ הוא בחי' ג\"ע, ויש ב' בחי' ג\"ע וזהו שנא' בארצות החיים. וביאור הענין צריך להבין למה נק' א\"י בכל התורה ארץ כנען ומה הוא היחוס, והלא נא' ארור כנען עבד עבדים יהי' לאחיו, וגם שחם הוא אבי כנען ומה היחוס שבח א\"י בזה, [גם להבין מ\"ש כנען בידו מאזני מרמה], גם מ\"ש ולא יהי' עוד כנעני בבית ה' צבאות ביום ההוא, שמשמע שביום ההוא דוקא לא יהי' כנעני אבל עכשיו שמשמע שיש כנעני בבית ה' צבאות, ואם הפי' כפשוטו איך נמצא כנעני בבית ה'. אך הענין הוא דהנה נודע שכל התורה נדרשת בזה לעומת זה, כי כמו שיש לבן כו' ושרי פרעה בקליפה וכמ\"ש ארמי אובד אבי כך יש כל בחי' אלו בקדושה שיש ג\"כ לבן דקדושה [וכמ\"ש לבושי' כתלג חיור ושער רישי' כעמר נקא, וכן כתי' וישכם לבן בבקר<sup data-n=\"222\">12</sup> שקאי על לבן דקדושה, ולכן הי' כה\"ג מתלבש ביוה\"כ בד' בגדי לבן דוקא, שלבן דקדושה הוא מדרגה גבוה מאד], והנה שלשה בני נח הם למעלה בקדושה ג' בחי' גווני קשת חיור סומק וירוק, שלנח נתן הקשת ושלשת בניו הם ג' בחי' גווני קשת, אלא שבהשתלשלו' העולמות בבחי' נפילה מדרגה אחר מדרגה נעשה חם גשמי אבי כנען שהוא בחי' חמימות רשפי אש התאוה, [וכן עד\"ז יש בקדושה ג\"כ חמימות רשפי אש הקדושה, שזהו מ\"ש בלחם הפנים שהי' חם כיום הלקחו שהוא בחי' חם דקדושה כו'].\n<b>ולהבין</b> ענין כנען בקדושה, הנה כנען פי' סוחר כמ\"ש כנעני' נכבדי ארץ, וכתי' כנען בידו מאזני מרמה, והיינו עד\"מ כמו הסוחר שמפזר ממון כסף וזהב ומוציאם מרשותו כדי להרויח ולהשתכר ואף שספק אצלו אם ירויח או לאו אעפ\"כ הוא מפזר אולי ירויח ומכניע א\"ע לספק זה להיות מפזר אולי נוסף עוד, כך הנה מקור נש\"י שהוא בחי' כנס\"י נמשלה לסוחר זה, [וזהו מ\"ש באברהם וישקול אברהם לעפרון ארבע מאות שקל כסף עובר לסוחר, שארבע מאות שקל כסף הוא ת' עלמין דכסופין<sup data-n=\"223\">13</sup>, שנמשכי' מעולם התענוג, ואברהם נתן אותם לעפרון, וזהו עובר לסוחר שזהו עד\"מ כסוחר שמפזר ועי\"ז נוסף עוד], וכך הנה כנס\"י בגלות מצרים נמשלו לסוחר וכמ\"ש וזרעתי' לי בארץ כלום אדם זורע קב אלא להוציא ממנה כמה כורין,",[["221","11","<b>ובכדי להבין כ\"ז. . בארץ מגורי אביו</b>: מכאן (עד פיסקא: ולהבין מה ענין הריוח) הוא ע\"פ לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370125\" data-slug=\"torah-or\" data-id=\"3901370125\">תו\"א וישב כו, ג</a>-ד. וראה גם תו\"ח וישב נז, א ואילך [ובהמ\"מ שם]. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480114\" data-slug=\"or-hatorah-hb\" data-id=\"8316480114\">אוה\"ת וישב (כרך ב) רנא, ב</a> ואילך. שם (כרך ה) תתפח, א ואילך."],["222","12","<b>לבן. . בקליפה. . שיש ג\"כ לבן דקדושה. . וישכם לבן בבקר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370107\" data-slug=\"torah-or\" data-id=\"3901370107\">תו\"א ויצא כג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370110\" data-slug=\"torah-or\" data-id=\"3901370110\">כג, סע\"ד</a> ואילך."],["223","13","<b>מ\"ש באברהם. . ארבע מאות שקל כסף. . ת' עלמין דכסופין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370115\" data-slug=\"torah-or\" data-id=\"3901370115\">תו\"א וישלח כד, ג</a>. ועוד."],["e13","*","<b>מגורי אביו</b>: בשולי הגליון נרשם בגוכי\"ק:\nמגורי אביו, בינה מקור של אביו דאתה אבינו, א\"כ הוא תמינאה."]]],[2000460147,"והיינו שעי\"ז מתבררין ניצוצי הנשמות שנפלו בשבה\"כ וכמשארז\"ל לא גלו ישראל אלא בשביל להוסיף עליהם דהיינו ניצוצי הנשמות שנפלו כו', וכמ\"ש עת אשר שלט האדם באדם לרע, דהיינו מה ששולט אדם דלעו\"ז באדם דקדושה הוא לרע לו כדי שעי\"ז יתבררו ניצוצי הנשמות כו', ולכן נמשלו נש\"י לסוחר שעי\"ז שמפזר נוסף עוד, כך נש\"י נמשלו לסוחר [וזהו שנק' הקב\"ה בשם קונה וכמ\"ש קונה שמים וארץ, קונה הכל, לפי שזהו ע\"ד כמו סוחר שמפזר כו']. וכמו שהוא בכללות העולם כך הוא בפרטיות בכל נפש מישראל בעבודת ה', כי הנה הנשמה טרם ירידתה לעוה\"ז להתלבש בגוף ונה\"ב היתה קשורה ומיוחדת במקורה ושרשה במאצילה ברשפי אש האהבה בטבע כשלהבת העולה מאלי' והיתה נהנית מזיו השכינה והי' לה בחי' אהוי\"ר טבעי' בגילוי רב שהוא בחי' כסף וזהב מלשון נכסוף נכספת, דהיינו בחי' אהבה, וזהב מצפון יאתה שהוא בחי' שמאל שהוא בחי' יראה, ואח\"כ כשירדה הנשמה לעוה\"ז להתלבש בגוף הגשמי הנה גם בחי' אהוי\"ר שהי' לה שם הם מוסתרות ומכוסות בלב הגשמי ואינה יכולה להיות באהוי\"ר בהתגלות כ\"כ כבתחלה, נמצא שנגרעו האהוי\"ר מערכם וא\"כ למה זה ירדה הנשמה לעוה\"ז מאחר שהיא ירידה גדולה וגרעון גדול מבתחלה שהוא בחי' פיזור כסף וזהב, אך הנה פיזור הוא בשביל ריוח.\n<b>ולהבין</b> מה ענין הריוח, דהנה כתי' טוב לי תורת פיך מאלפי זהב וכסף, אלפי לשון לימוד שיש לי יתרון מעלה בתורת פיך בעוה\"ז יותר מבחי' זהב וכסף שהיתה הנשמה למודה בהם בתחלה, וכמ\"ש במ\"א בענין חי ה' אשר עמדתי לפניו<sup data-n=\"224\">14</sup> שעמידתה היתה באהוי\"ר במכ\"ש ממ\"ש ויעמידם לעד לעולם כו' שהרי נשמות הם מפנימיות הכלים כו', ועכ\"ז ירדה להתלבש בגוף ונה\"ב כו', אלא שהירידה צורך עלי' היא שעי\"ז הנה היא באה לאשתאבא בגופא דמלכא כו', וזהו דכתי' ואנשי קדש תהיון לי, שע\"י ירידת הנשמה בגוף מתעלה בבחי' קדש העליון קדש מלה בגרמי', שלמעלה משרש הנשמה שהי' בבחי' טהורה היא כמ\"ש במ\"א<sup data-n=\"225\">15</sup> כו', והוא ע\"י אשר קדשנו במצותיו, וצונו ל' צותא וחיבור כו', ולכן עתידי' צדיקים, פי' צדיק המקיים תומ\"צ כמ\"ש במ\"א<sup data-n=\"226\">16</sup>, שיאמרו לפניהם קדוש כו', ופרש\"י ע\"ד שאומרי' לפני הקב\"ה<sup data-n=\"227\">17</sup>, וזהו העלי' שע\"י הירידה כו' וכמשי\"ת<sup data-n=\"228\">18</sup>.",[["224","14","<b>וכמ\"ש במ\"א בענין חי ה' אשר עמדתי לפניו</b>: מכאן עד הסיום הוא הוספה בהמאמר שלפנינו, וליתא בד\"ה וישב הנדפס לעיל. וראה להלן ד\"ה אמר ריב\"ל בענין ה' אשר עמדתי לפניו."],["225","15","<b>ואנשי קדש. . שלמעלה משרש הנשמה. . טהורה היא כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380433\" data-slug=\"likkutei-torah\" data-id=\"4001380433\">לקו\"ת בהעלותך ל, ד</a>. ועוד."],["226","16","<b>עתידים צדיקים פי' צדיק המקיים תומ\"צ כמ\"ש במ\"א</b>: ראה בכ\"ז סה\"מ תרל\"ג ח\"א ע' קמא. וש\"נ."],["227","17","<b>ופרש\"י ע\"ד שאומרי' לפני הקב\"ה</b>: בגמ' ב\"ב עה, ב: עתידים צדיקים שאומרים לפניהם קדוש כדרך שאו' לפני הקב\"ה. וברש\"י שלפנינו: שאו' לפניהם, מלאכים יאמרו."],["228","18","<b>וכמשי\"ת</b>: ראה לקמן בד\"ה אמר ריב\"ל [ובהמ\"מ שם]."]]],[2000460148,"<h3>אריב\"ל כו' ש\"א עולמות (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ ויגש, ט\"ל).</b>\n<b></b>טוב לי תורת כו' יפה כח הבן מכח האב כו' נתיב ל\"ב כו' בדומה לו\nויגש\n<b>אריב\"ל</b> עתיד הקב\"ה<sup data-n=\"229\">1</sup> להנחיל לכל צדיק וצדיק שלש מאות ועשרה עולמות שנא' (משלי ח') להנחיל אוהבי יש ואוצרותיהם אמלא (משנה סוף עוקצין), ופי' המפרשי' יש בגימ' ש\"י, ועל מה שהכינו בעוה\"ז יהי' התשלום ש\"י פעמים נגד כל העוה\"ז והעוה\"ז עצמו הוא חלק אחד נגד ש\"י פעמים דעוה\"ב כו', וצ\"ל מהו מספר ש\"י דוקא, ומה\"ע שהעוה\"ז הוא חלק א' נגד ש\"י דעוה\"ב כו'.\n<b>הנה</b> כתיב טוב לי תורת פיך<sup data-n=\"230\">2</sup> מאלפי זהב וכסף, פי' זהב וכסף הם בחי' יראה ואהבה כי מצפון שהוא קו השמאל יראה זהב יאתה, וכסף הוא בחי' אהבה מל' נכסוף נכספת לבית אביך, ופי' אלפי הוא לימוד מלשון אאלפך חכ' שענינו הוא לימוד האהוי\"ר שהיתה הנשמה רגילה בו הנה טוב לי יותר תורת פיך שאתה לומד תורה בהתלבשות הנשמה בגוף מבחי' האהוי\"ר שהיתה הנשמה רגילה קודם התלבשותה בגוף כו', אשר ג\"ז אינו מובן כ\"כ שהרי גם אחרי התלבשותה בגוף ולומדת תורת פיך (היינו גם תושבע\"פ) הנה היא צריכה לאהוי\"ר שהרי אוריי' בלא דו\"ר לא פרחת לעילא, וארז\"ל מה להלן באימה וביראה אף כאן באימה וביראה, א\"כ גם אח\"כ צריכה לאהוי\"ר אשר בל\"ז לא פרחית כו'.\n<b>ויובן</b> בהקדם שרש ענין בחי' ירידת הנשמה<sup data-n=\"231\">3</sup> בגוף שלכאו' היא ירידה גדולה ועצומה מאד, שהרי מלבד שהיא בחי' חלק ה' הנה נא' בה חי ה' אשר עמדתי לפניו, שענין העמידה הכוונה על בחי' הביטול באהוי\"ר ע\"ד שרפי' עומדים שעמידתם היא בבחי' ביטול, וזהו עיקר קריאת שם עמידה שרומז על בחי' ביטולם שאם הכוונה על עמידה סתם הלא ארז\"ל וכי יש ישיבה למעלה, אלא כנ\"ל, וזהו ויעמידם לעד לעולם הכוונה שעומדי' בבחי' הביטול תמיד כ\"ז קיום ועמידת העולם, וי\"ל שקאי על המלאכי' שעומדים כעת בבחי' הביטול באמירת פעם הג' קדוש משי\"ב כו', וכמ\"ש מזה במ\"א<sup data-n=\"232\">4</sup>, וא\"כ עמידת הנשמה בודאי היא באופן היותר נעלה שהרי הנשמות הם מבחי' פנימיות הכלים הקרובי' לבחי' האור, משא\"כ המלאכי' הם",[["229","1","<b>אריב\"ל עתיד הקב\"ה</b>: מאמר זה הוא המשך להמאמר שלפניו ד\"ה מי כהוי' אלקינו. והוא מהדו\"ב ותוס' הגהות לד\"ה וישב יעקב הנדפס לעיל (מפיסקא: והנה להבין מ\"ש בארץ מגורי אביו, עד פיסקא: וביאור הענין איך ע\"י תומ\"צ), וע\"ש בהמ\"מ. מאמר זה נמצא ג\"כ לקמן בהוספות, בהנחת כ\"ק אדמו\"ר מוהרש\"ב (ומתחיל: ואהבת את ה' אלקיך, וראה שם שבפעם א' התחיל המאמר: אריב\"ל). וראה שם ד\"ה לה\"ע מה שחותמין בברכת אירוסין."],["230","2","<b>הנה כתיב טוב לי תורת פיך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370126\" data-slug=\"torah-or\" data-id=\"3901370126\">תו\"א וישב כו, סע\"ד</a>. תו\"ח וישב נה, א ואילך. אוה\"ת וישב (כרך ב) רנג, ב ואילך. שם (כרך ה) תתפט, ב ואילך."],["231","3","<b>ויובן בהקדם שרש ענין בחי' ירידת הנשמה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370042\" data-slug=\"torah-or\" data-id=\"3901370042\">תו\"א י, ב</a>. בשלח סב, סע\"ד. ובארוכה תו\"ח שמות רל ואילך. והחרים תרל\"א ע' כח ואילך. וככה תרל\"ז ע' קפה ואילך. יונתי תר\"מ ע' י. סה\"מ עטר\"ת ע' שע-עא. ועוד."],["232","4","<b>המלאכי'. . פעם הג' קדוש. . וכמ\"ש מזה במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך."]]],[2000460149,"מחיצוני' הכלים, ובירידתה להתלבש בגוף מלבד מה שצריכי' ריבוי התבוננו' ביגיעת הנפש ויגיעת בשר עד שיבא לבחי' אהבה אמיתית, שהוא מבחי' ממכ\"ע, וכ\"ש לבחי' יראה שבא מהתבוננות בחי' סוכ\"ע, כמ\"ש בלק\"ת בד\"ה וידעת היום דרוש השני<sup data-n=\"233\">5</sup>, הנה בעבור בחי' ההתבוננות חולפת ועוברת גם אהבתה גם יראתה, א\"כ זהו הוכחה שגם בעת שהיו האהוי\"ר לא היו בתוקף כ\"כ, שהרי הקיום זהו הוכחה על בחי' התוקף והחוזק, וכענין ויעמידם נת\"ל שזהו שיהיו עומדי' בבחי' הביטול כל שית אלפי שני כו', ועמ\"ש במ\"א מענין מ\"ש בירושלמי בהבראם חזקים כיום הבראם כו'<sup data-n=\"234\">6</sup>, ולמה היתה כזאת מלפניו ית' שתרד פלאים כו' בשביל התלבשותה בגוף ונה\"ב, אם לא שכל ירידתה כדאי בשביל עלייתה כ\"כ במעלה עליונה גבוה מאד נעלה, וצ\"ל מהו.\n<b>אך</b> הענין שזהו שא' טוב לי תורת פיך כו' וע\"ד שאה\"כ יש מפזר ונוסף עוד, שכמו הסוחר בנסעו לקנות מפזר כסף וזהב על קניית הסחו', והוא בכדי שירויח כו', כ\"ה בנשמה שמפזרין כסף וזהב שלה שהו\"ע האהוי\"ר שלה בכדי להוסיף עוד שז\"ע דכתי' טוב לי תורת פיך מאלפי זהב וכסף אלפי לשון לימוד שיש לו יתרון מעלה בתורת פיך בעוה\"ז יותר מבחי' זהב וכסף שהיתה הנשמה למודה בהם בתחלה.\n<b>והענין</b> הוא, דהנה כתי'<sup data-n=\"235\">7</sup> ביום חתונתו זו מ\"ת, שתו' נק' בשם חתונה בחי' יסוד, והיינו שע\"י תומ\"צ שלמטה עי\"ז מתאחדת הנשמה באוא\"ס ממש שהוא בחי' לאשתאבא בגופא דמלכא ממש וכמשל יחוד חתן וכלה שנעשים אדם אחד ממש, וכמ\"ש זכר ונקבה בראם ויקרא שמם אדם, ונק' תרי פלגא גופא כמ\"ש בזהר, משא\"כ הנשמה קודם ירידתה לעוה\"ז אף שהי' לה אוי\"ר בהתגלות אעפ\"כ היתה בבחי' נפרד, וכמו המלאכי' שהם נפרדי', אף שאומרי' קדוש וברוך תמיד באהבה ברשפי אש, אבל ע\"י התורה עי\"ז מתאחדי' ממש לפי שהתורה היא בחי' תורת הוי' וכן במצות נא' מצות הוי', הקב\"ה מניח תפילין ומתעטף בציצית כו', והמצות עליונות ממש כמו שהן למעלה נמשכו ונתלבשו למטה במצות גשמי', ואף שנתלבשו בגשמי', אך באמת היא הנותנת כו' וכמ\"ש במ\"א<sup data-n=\"236\">8</sup>. וזהו המשל מבחי' חתונה שאף שהטפה שנמשך ממוח האב היא נתגשמה ממש בבחי' טפה גשמי' מ\"מ מלובש בה מעצמיות המוחין ממש, שהרי מטפה זו נתהוה להוליד בדומה לו ממש,",[["233","5","<b>כמ\"ש בלקו\"ת בד\"ה וידעת היום דרוש השני</b>: לקו\"ת ואתחנן ד, ד ואילך."],["234","6","<b>ועמ\"ש במ\"א מענין מ\"ש בירושלמי בהבראם חזקים כיום הבראם כו'</b>: ראה ספר החקירה להצ\"צ ד, א. שם קא, א ואילך. סה\"מ תרכ\"ז ע' תעט-פ. וש\"נ. תרל\"ג ח\"ב ע' תקמט. המשך מים רבים תרל\"ו פל\"ג."],["235","7","<b>והענין הוא דהנה כתי'</b>: התוכן מכאן (עד קרוב לסיום המאמר) נמצא ג\"כ להלן בד\"ה צאינה וראינה. וראה גם לעיל ד\"ה וישב יעקב, פיסקא: והענין הוא דהנה כתי'."],["236","8","<b>המצות עליונות. . ואף שנתלבשו בגשמי' וכמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380496\" data-slug=\"likkutei-torah\" data-id=\"4001380496\">לקו\"ת שלח מו, א</a>. ועוד."]]],[2000460150,"ונת' במ\"א מענין יפה כח הבן מכח האב<sup data-n=\"237\">9</sup> שלכאו' יפלא מאין יומשך יתרון בהבן נגד האב א\"ל שנאמר שזהו ממה שהקב\"ה נותן בו נשמה, כי שלש שותפין באדם<sup data-n=\"238\">10</sup>, ומצד יתרון שיש בנשמת הבן עי\"ז יפה כחו. אמנם באמת גילוי בחי' נשמה א\"א להיות בעוה\"ז בלתי שימצא כלי בגוף שיתלבש בו כח הנפש, וא\"כ מאחר שיפה כח הבן בהכרח שגם בגופו יש כלי לגילוי אור זה, וכלי הגוף הגם שג\"ז הוא מהקב\"ה כמארז\"ל ע\"פ אין צור כו' אין צייר כאלקינו שצר צורה בתוך צורה, עכ\"ז חשבו בגמ' כלי הגוף לחלק אב ואם כמארז\"ל אב מזריע לובן שממנו כו' אם אודם שממנו כו', א\"כ צ\"ל איך יפה כח הבן כו', אלא שצ\"ל שבאדם יש כחות נגלי' וכחות נעלמי', ויפה כח הבן בכחות הנגלים מכח האב ג\"כ הנגלים, אבל בכחות הנעלמי' בהכרח לומר שיש באב ג\"כ דאל\"כ מאין ימצא בכלי הגוף שבבן כו', והרי עכ\"פ מזה מובן דעם היות שהטפה גשמיות היא עכ\"ז יש בה מעצם כח האב גם מכחות הנעלמי' ג\"כ כו', ולכן מוליד בדומה לו ממש וגם כחות הנעלמי' יכולים להיות ברצון השי\"ת נגלים בבן עד שבהאיר חלק הנשמה בכחות ההם יפה כח הבן כו'. ועד\"מ זה יובן בענין ביום חתונתו, והתו' היא בחי' השפעת חתן לכלה שהיא בחי' טפת אבא, שיש בה מעצם אור אבא שלמעלה מהשתלשלו' כמ\"ש במ\"א בד\"ה וככה תאכלו<sup data-n=\"239\">11</sup>, וזהו אורייתא מחכ' נפקת, אבל שרשה היא בלמעלה מן החכ' ועמ\"ש במ\"א שהיחוד עליון נמשך מהכתר דוקא<sup data-n=\"240\">12</sup>, וע' בד\"ה הגידה לי שאהבה נפשי<sup data-n=\"241\">13</sup>, ובהגהות לד\"ה וספרתם דסה\"ע<sup data-n=\"242\">14</sup>. וכ\"ז הוא דוקא בבחי' המצות שנתלבשו בדברי' גשמיים דוקא וכמשל הטפה הנ\"ל, ועל מצות אלו אנו מברכין אשר קדשנו בבחי' מצותיו דוקא היינו מה שהקב\"ה מניח תפילין כו' כי ע\"י שאנו מניחי' תפילין שלנו עי\"ז ממשיכי' שיהי' הקב\"ה מניח תפילין וכידוע, ועמ\"ש במ\"א בענין פי' המד\"ר ע\"פ מגיד דבריו ליעקב כו'<sup data-n=\"243\">15</sup> מה שהוא עושה אומר לישראל לעשות, שמה שהוא עושה כבי' זהו ע\"י שאומר כו', ונמצא שזהו הריוח של הפיזור כסף וזהב, שעי\"ז נכללי' הנשמות באא\"ס ממש לאשתאבא בגופא דמלכא, פי' גופא הלא אין לו דמות הגוף ולא גוף, אלא שזהו משל להבין ענין בחי' שיעור קומה דבחי' ע\"ס שלמעלה.\n<b>ויובן</b> ענין בדומה לו, ועם היות שג\"ז נכלל בתי' גופא דמלכא, מאחר שקאי על כלליות שיעור קומה, עכ\"ז יובן בעומק יותר, ע\"פ מארז\"ל במד\"ר וישלח",[["237","9","<b>ונת' במ\"א מענין יפה כח הבן מכח האב</b>: ראה סה\"מ תרל\"ב ח\"ב ע' תצה. ובכ\"מ."],["238","10","<b>שלש שותפין באדם</b>: נדה לא, א. וראה בכ\"ז גם סה\"מ תרל\"ב ח\"ב ע' תעח ואילך."],["239","11","<b>כמ\"ש במ\"א בד\"ה וככה תאכלו</b>: ראה המשך וככה תרל\"ז פס\"ז (ע' קד) ואילך. ועוד."],["240","12","<b>ועמ\"ש במ\"א שהיחוד עליון נמשך מהכתר דוקא</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490144\" data-slug=\"or-hatorah-hb\" data-id=\"8316490144\">אוה\"ת וירא (כרך ד) תשמא, ב</a>. ביאוה\"ז להצ\"צ (כרך ב) ע' תתרמה. סה\"מ תרל\"ד ע' תי."],["241","13","<b>וע' בד\"ה הגידה לי שאהבה נפשי</b>: אוה\"ת שה\"ש ע' קיז ואילך. ועוד."],["242","14","<b>ובהגהות לד\"ה וספרתם דסה\"ע</b>: דספירת העומר. ראה אוה\"ת דרושים לשבועות ע' ריד (הוצאת תשנ\"ה)."],["243","15","<b>ועמ\"ש במ\"א בענין פי' המד\"ר ע\"פ מגיד דבריו ליעקב כו'</b>: ראה סה\"מ תרכ\"ח ע' פז. תרכ\"ט ע' רכג. תרל\"ב ע' פד. תרל\"ד ע' נג."]]],[2000460151,"ס\"פ ע\"ט ע\"פ ויקרא לו אל אלקי ישראל<sup data-n=\"244\">16</sup> א\"ל אתה אלקה בעליוני' ואני אלקה בתחתוני', ונענש ע\"ז ע\"ש במפרשי', ובמגילה די\"ח ארז\"ל שהקב\"ה קרא ליעקב אל, וע' בהרמב\"ן בפי' החומש במקומו. והענין הוא כי דברי המד\"ר הנ\"ל נת' במ\"א בענין ספי' הת\"ת<sup data-n=\"245\">17</sup> שאבינו יעקב הי' מרכבה לה שע\"ז אמר ואני אלק' בתחתוני', ואינו שייך כ\"כ לכוונת דרוש זה, אמנם דברי רז\"ל במגילה שאמרו שהקב\"ה קרא ליעקב אל, י\"ל הכוונה ע\"פ מ\"ש בס\"י בל\"ב נתיבות פליאות חכ' חקק כו' שיש בחכ' בחי' ל\"ב נתיבות, וכן בבינה יש נש\"ב, כמארז\"ל חמשים שערי בינה נבראו בעולם, והנה במשה נא' ותחסרהו מעט מאלקי' ופירשו בזה שהשיג רק מ\"ט שערי בינה, ועד יום מותו לא השיג שער החמשים וזהו ותחסרהו מעט היינו בחי' שער הנו\"ן דבינה מבחי' אלקי' דבינה, רק שבעת הסתלקותו השיג גם שער הנו\"ן ג\"כ, ולכן ארז\"ל לעליוני' נדמה להם למטה לתחתוני' נדמה להם למעלה שקאי על שער הנו\"ן כמ\"ש מזה במ\"א ע' בד\"ה את שבתותי תשמרו שלא נדפס, ובהגהות לשם<sup data-n=\"246\">18</sup>, וכמו שהוא בנש\"ב כן גם בל\"ב נ\"ח יש ג\"כ נתיב אחד אשר עליו נא' (איוב ך\"ח וא\"ו) נתיב לא ידעו עיט ולא שזפתו עין איה, שבחי' נתיב זה לא ידעו כלל, וי\"ל פי' איה קאי על האומרים איה מקום כבודו (כ\"פ במאו\"א<sup data-n=\"247\">19</sup>) שגם הם אינם יודעי' מנתיב זה, ויש לבאר ע\"פ משנ\"ת במ\"א שאי' מקום כבודו אומרי' האופני' וחיות הקדש<sup data-n=\"248\">20</sup>, שהרי השרפי' אומרים מכה\"כ, וארז\"ל בחולין פרק גיד הנשה שאני אופנים שמכסא עצמו, לכן מזכירי' את השם אחר ב' תיבות, ועכ\"ז גם הם אינם יודעי', והיינו לא מיבעי שהשרפי' אינם משיגי' זה שהרי זהו בעצם למעלה מהשגה, ולכן א\"א להם להשיג בחי' זה כלל, כי השרפים הם משיגי' רק בד\"כ שאוא\"ס ב\"ה הוא קדוש ומובדל מגדר עולמות, ולכן רצונם וחפצם ליכלל וליבטל באוא\"ס שלמעלה מבחי' מקור לעולמות, ומאן דכסיף אע\"ג דלא יכיל שבחא אית לי', לכן נא' עליהם שרפי' עומדים ממעל לו היינו לש' אד' הנז' תחלה, או ממעל לבחי' וא\"ו מקור דמקור לעולמות כי ששת ימים כו' וכתי' כי אמרתי עולם חסד יבנה, וכפי ב' הפי' שבתי' יבנה כמ\"ש במ\"א<sup data-n=\"249\">21</sup>, וכמו שפי' הבעש\"ט ז\"ל שבמקום שרצונו של אדם<sup data-n=\"250\">22</sup> עד\"מ שם הוא בחוזק ה\"ז כאלו עומד שם כו', ולכן גבי השרפי' מאחר שרצונם ליכלל באוא\"ס",[["244","16","<b>ע\"פ ויקרא לו אל אלקי ישראל</b>: בכל הבא לקמן ראה גם בסה\"מ תורת שמואל — דרושי חתונה ע' כג ואילך. כה ואילך. [ובהנסמן בהע' שלאח\"ז]."],["245","17","<b>נת' במ\"א בענין ספי' הת\"ת</b>: ראה סה\"מ תרל\"ב ח\"א ע' לז ואילך [ובהנסמן שם]. ושם ע' קנט וע' קצט ואילך. תרל\"ג ח\"א ע' מח ואילך. וש\"נ."],["246","18","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940212\" data-slug=\"or-hatorah-hb\" data-id=\"8159940212\">ע' בד\"ה</a> את שבתותי תשמרו שלא נדפס, ובהגהות לשם</b>: ראה מאמרי אדה\"ז תק\"ע ס\"ע פח ואילך. אוה\"ת בהר כרך ב ע' תריח. סה\"מ תרל\"ב ח\"ב ע' תקנב."],["247","19","<b>כ\"פ במאו\"א</b>: תיבה זה אינה ברורה בגוכתי\"ק. [וראה מאו\"א א, כב]. ובכת\"י המעתיק הר\"ש סופר רשום כאן: במאמ\"א."],["248","20","<b>ע\"פ משנ\"ת במ\"א שאי' מקום כבודו אומרי' האופני' וחיות הקדש</b>: ראה סה\"מ תרל\"ג ח\"א ע' יג ואילך. ח\"ב ע' תקפד ואילך. תרל\"ד ע' רמה ואילך."],["249","21","<b>וכפי ב' הפי' שבתי' יבנה כמ\"ש במ\"א</b>: ראה סה\"מ תרל\"ד ע' נד ואילך."],["250","22","<b>וכמו שפי' הבעש\"ט ז\"ל שבמקום שרצונו של אדם</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830086\" data-slug=\"or-hatorah-hb\" data-id=\"8158830086\">אוה\"ת</a> בראשית כרך ו תתרכז, ב. פ' במדבר (הוספות) ע' 86. ובכ\"מ."]]],[2000460152,"הסוכ\"ע שלמעלה מהארה המתצמצמת בעולמות ה\"ז כאלו עומדי' שם כו', ועכ\"ז מזכירי' את השם אחר ג' תיבות דוקא, משא\"כ אופנים מזכירים את השם אחר ב' תיבות לפי שהם מכסא עצמו, ומ\"מ הם ברעש גדול כמשנ\"ת במ\"א<sup data-n=\"251\">23</sup> שזהו מפני העדר ההשגה שעי\"ז נעשה הרעש גדול, ולכן הם הם הממשיכי' בחי' כבוד ה' ממקומו פי' ממקורו ושרשו ע\"ד ממקומו הוא מוכרע כמ\"ש מזה בד\"ה ואולם חי אני ובהביאורי' שלא נדפסו ובהג\"ה לשם<sup data-n=\"252\">24</sup>, וע' בד\"ה כי במקלי עברתי<sup data-n=\"253\">25</sup> בענין כ\"י ב\"מ ר\"ת ברוך כבוד הוי' ממקומו, שזהו ע\"י היותם מי בכים כו', וע' בד\"ה אני דפ' ציצית<sup data-n=\"254\">26</sup> שמרעש נעשה שער בימין ושער בשמאל ע\"ש, ואחר כל השבח הזה דאופנים עכ\"ז בחי' נתיב זה הל\"ב לא שזפתו עין איה שגם האומרים אי' מקום כבודו ג\"כ אינם יודעים ממנו שיהי' מזה אצלם בחי' רעש מפני העדר השגתם, כי הרעש על העדר ההשגה צריך לידע עכ\"פ שיש מה להשיג והם אינם משיגי', ומזה נעשה הרעש, אבל בנתיב זה אינו שייך גם שזיפת עין מין הנק' איה היא הראה והדיה שבס' דברים כמארז\"ל בחולין<sup data-n=\"255\">27</sup> היא ראה דיה היא אי', ונק' ראה ע\"ש שרואה למרחוק, ע\"ד אמרתי אחכמה והיא רחוקה, וה\"ז משל שגם ראיית השכל ע\"ד ידיעת המציאות אינו ידוע לאותם האומרים אי' מקום כבודו (רק לנשמות שגבהה מעלתם ממלאכי' כנודע, וירדו להתלבש בגוף דוקא לברר נה\"ב, נתגלה לנו ע\"פ ס\"י שיש ל\"ב נ\"ח).\n<b>והנה</b> ארז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות שנא' להנחיל אוהבי יש, יש הוא ש\"י עולמות, וצ\"ל מ\"ע מספר ש\"י דוקא. אך הענין הוא שזהו נגד בחי' הל\"א נתיבות דחכ' שכ\"א כלול מעשר עולה מספר ש\"י כו', ונודע כי ארז\"ל שלשה הטעימן הקב\"ה מעין עוה\"ב ולכן נא' ביעקב ויקרא לו אל, היינו בחי' ל\"א נ\"ח הנ\"ל שזהו מעין עוה\"ב שיהיו ש\"י עולמות כו', ולכן פי' בזהר שאל הוא נהירא דחכמתא לפי שקאי על ל\"א נ\"ח כו' וה\"ז הוא בדומה לו כבי' שקראו אל, ויעקב זכה לזה גם קודם מ\"ת, והיינו ע\"י קיום המצות שקיימו שעם היות ריחות היו כמ\"ש במ\"א<sup data-n=\"256\">28</sup> כו' עכ\"ז מחסד ה' עליהם הטעימן מעין עכ\"פ של העה\"ב, ועד\"ז יובן ענין ההולדה בדומה לו שע\"י מ\"ת בגשמיות דוקא, ע\"ד שארז\"ל עתידי' צדיקי' שיקראו ע\"ש של הקב\"ה, ופרש\"י שיהי' שמם הוי', היינו בחי' הוי' בחכ' כו'.",[["251","23","<b>ומ\"מ הם ברעש גדול כמשנ\"ת במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380383\" data-slug=\"likkutei-torah\" data-id=\"4001380383\">לקו\"ת במדבר יח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380423\" data-slug=\"likkutei-torah\" data-id=\"4001380423\">נשא כח, ד</a> ואילך. ובכ\"מ."],["252","24","<b>כמ\"ש מזה בד\"ה ואולם חי אני ובהביאורי' שלא נדפסו ובהג\"ה לשם</b>: ראה ס' מאמרי אדה\"ז תקס\"ט ע' קפג ואילך. מאמרי אדה\"ז עה\"ת ח\"ב ע' תרכז וע' תרלב ואילך. מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'עח ואילך. א'קנב ואילך. א'קמז ואילך. אוה\"ת שלח ע' תקי ואילך. סה\"מ תרל\"ד ע' רמה ואילך."],["253","25","<b>וע' בד\"ה כי במקלי עברתי</b>: סה\"מ תרל\"ג ח\"א ע' רלה."],["254","26","<b>וע' בד\"ה אני דפ' ציצית</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a> ואילך."],["255","27","<b>הראה והדיה שבס' דברים כמארז\"ל בחולין</b>: פ' ראה יד, יג. חולין סג, ב."],["256","28","<b>שעם היות ריחות היו כמ\"ש במ\"א</b>: ראה בארוכה סה\"מ תרכ\"ט (הוצאת תשנ\"ב) ע' רכא ואילך. וש\"נ."]]],[2000460153,"<b>וי\"ל</b> שמה שאריב\"ל עתיד כו' ש\"י עולמות שזה ל\"א פעמי' יו\"ד ש\"י פעמי' נגד העוה\"ז, כי גם בעוה\"ז נא' ה' בחכ' יסד ארץ, ואין לך במספר פחות מאחד, הנה זה יהי' בבחי' נחלה, ומ\"מ גם נתיב הל\"ב שלא ידעו עיט, שי\"ל שזהו מ\"ש בתורה לא ידע אנוש ערכה כמ\"ש באגה\"ק ד\"ה דוד זמירות קרית להו<sup data-n=\"257\">29</sup>, הנה לע\"ל שיתגלה פנימיות התורה יתגלה גם בחי' זו כו', וא\"כ מובן בטוב טעם ענין בחי' בדומה לו גם בבחי' מוחין דאבא כו'.",[["257","29","<b>כמ\"ש באגה\"ק ד\"ה דוד זמירות קרית להו</b>: תניא קו\"א קס, א."]]],[2000460154,"<h3>ואהבת כו' (ג)</h3>\n<b></b><b>בס\"ד. (ש\"פ ויחי, ט\"ל).</b>\n<b></b>חופה (ואח\"כ) קדושין כו' צדיקים ובעלי תשובה\n[ויחי]\n<b>ואהבת</b> כו'<sup data-n=\"258\">1</sup> בכל לבבך ובכל נפשך ובכל מאדך, הנה בפי' ואהבת יש ב' פי', הא' ל' ציווי, והב' לשון הבטחה, שסופך לבוא לידי אהבה כו', ועל פי' הא' ל' ציווי הקשו האיך שייך ציווי על אהבה<sup data-n=\"259\">2</sup> הלא היא מדה שבלב, והתירוץ ע\"ז הוא שהציווי הוא על ההתבוננות שכאשר מתבונן בפסוק שמע כו' איך שה' אלקינו הוא ה' אחד בז' רקיעים וארץ וד' רוחות העולם וכאמרז\"ל כד אמליכתי' כו' עי\"ז ממילא יבוא לידי אהבה. ולכאו' אינו מובן למה בא הציווי כ\"כ או ההבטחה שסופך לבוא כו' הלא הנשמה קודם התלבשותה בגוף היתה עומדת לפניו כמ\"ש חי ה' אשר עמדתי לפניו שנת' בד\"ה אריב\"ל<sup data-n=\"260\">3</sup> שפי' וענין העמידה ז\"ע תוקף ביטולה באהוי\"ר ע\"ש, וה\"ה רגילה בזה, ולמה צריכי' ציווי כ\"כ ע\"ז, וכ\"ש ענין ההבטחה שסופך לבוא לידי אהבה.\n<b>אך</b> הענין הוא שנת' שם בענין טוב לי תורת פיך מאלפי זהב וכסף, זהב וכסף זהו יראה ואהבה שהיתה הנשמה רגילה שזהו פי' אלפי ל' לימוד כו' עם היות שמתמעטים ע\"י התלבשותה בגוף עכ\"ז טוב לי תורת פיך, שעי\"ז באה לאשתאבא בגופא דמלכא, ע\"ש בענין בדומה לו, עתידי' שיקראו ע\"ש של הקב\"ה שיהי' שמם הוי', שי\"ל שזהו עוד יותר ממה שהקב\"ה קרא ליעקב אל, שהוא נהירא דחכמתא, ל\"א נתיבות חכמה שזה הי' קודם מ\"ת, והמצות שקיימו האבות ריחות היו כאמרם",[["258","1","<b>ואהבת כו'</b>: מאמר זה הוא המשך להמאמרים שלפני\"ז ד\"ה מי כה' אלקינו וד\"ה אריב\"ל. והוא מהדו\"ב ותוס' הגהות לד\"ה וישב יעקב הנדפס לעיל (פיסקא: וביאור הענין איך ע\"י תומ\"צ), וע\"ש בהמ\"מ. וראה לקמן בהוספות הנחת כ\"ק אדמו\"ר מוהרש\"ב ד\"ה ואהבת, וד\"ה לה\"ע מה שחותמים בברכת אירוסין."],["259","2","<b>הקשו האיך שייך ציווי על אהבה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370388\" data-slug=\"torah-or\" data-id=\"3901370388\">תו\"א תשא פו, ג</a>-ד. הוספה לדרמ\"צ קצט, א. סה\"מ תרכ\"ז ע' עד וש\"נ. תרל\"ב ח\"א ע' צה. תש\"א ע' 116 ואילך."],["260","3","<b>שנת' בד\"ה אריב\"ל</b>: נדפס לעיל לפני מאמר זה."]]],[2000460155,"ז\"ל במד\"ר שה\"ש, אבל ע\"י מ\"ת, שנת' במ\"א שגם על פנימיות התורה שיתגלה לע\"ל הכל נכלל במ\"ת<sup data-n=\"261\">4</sup> כו', ומה שעתידי' שיקראו הוי' היינו כמ\"ש ה' בחכ' שזהו כל הל\"ב נתיבות, וי\"ל שזהו כמ\"ש במ\"א שמוחין דאבא הם למעלה מהשתלשלות<sup data-n=\"262\">5</sup> כו'.\n<b>וביאור</b> הענין איך ע\"י תומ\"צ<sup data-n=\"263\">6</sup> תהי' הנשמה מתאחדת באוא\"ס ממש, הענין הוא דהנה תורה נק' ביום חתונתו, והנה חתונה צריך מתחלה בחי' חופה, וע\"י החופה עי\"ז יכול להיות אח\"כ היחוד, וזהו מ\"ש מקדש עמו ישראל ע\"י חופה וקדושין, והקשה בהרא\"ש למה מזכירין חופה בברכת אירוסין, הלא כשהיו מברכין ברכת אירוסין בזמן שנהגו לארס תחילה לא הי' חופה כלל, ול\"ל להזכיר דבר שא\"צ, ותירצו שזהו בכדי להזכירו שלא ברכת האירוסין מתיר כ\"א החופה שבשעת הנשואין דוקא כו'. אמנם עדיין אינו מובן מדוע אינם מזכירי' בברכת נשואין ענין החופה שאז הוא דבר בעתו גם למנהגיהם שהיו מארסין תחלה ואח\"כ חופה ונשואין, ולמה הקדימו להזכיר בברכת אירוסין שא\"צ לחופה כלל שההיתר הוא ע\"י חופה דוקא, ובנשואין עצמם לא תיקנו להזכיר, עד שגם אצלינו שאירוסין ונשואין הם ביחד לא זזה ממקומה כו', אם לא שנא' שיש שייכות להזכיר ענין החופה בשעת אירוסין דוקא. וע\"פ פשוט נשאר הנוסח גם אצלינו כן הגם שאירוסין ונשואין הם ביחד, מפני אולי יקרה שיהיו אירוסין תחילה צריכי' להזכירו שההיתר הוא ע\"י החופה דוקא כתירוץ הרא\"ש. אמנם יש עוד טעם מה שתיקנו להזכיר חופה בברכת אירוסין הגם כי עיקר החופה היא שייכה לנשואין דוקא כו'.\n<b>והענין</b> הוא כנודע שענין האירוסין הוא בחי' מקיף שמקדשה בטבעת ואומר לה הרי את מקודשת כו', שהטבעת הנה רק בחי' מקיף שממשיך לה חיות מועט להיות מקודשת לשון הפרשה לו כו', וכמ\"ש מזה בלק\"ת בד\"ה תורה צוה בפ' הברכה<sup data-n=\"264\">7</sup>, אמנם נשואין הוא בחי' השפעה פנימי' להוליד בדומה לו, וכמ\"ש מזה בביאור מאה\"ז ע\"פ לא טוב היות האדם לבדו (הלשון שלא נדפס)<sup data-n=\"265\">8</sup>, בביאור ענין ההבדל שבין זווג נשיקין כו' לענין זיווג גופני דזו\"נ להוליד נשמות ע\"ש, רק",[["261","4","<b>פנימיות התורה שיתגלה לע\"ל הכל נכלל במ\"ת</b>: ראה גם סה\"מ תרנ\"ו ע' שנו. המשך תרס\"ו ע' כג. שם ע' תקמו. תער\"ב ח\"א ע' שסו. סה\"מ עטר\"ת ע' רצא. תרפ\"ה ע' קצט. ה'תש\"ט ע' 57. סה\"מ מלוקט ח\"א ע' תסא. ועוד."],["262","5","<b>כמ\"ש במ\"א שמוחין דאבא הם למעלה מהשתלשלות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת צו יא, ד</a> ואילך. סה\"מ תרל\"ב ח\"א ע' תכז. וש\"נ."],["263","6","<b>וביאור הענין איך ע\"י תומ\"צ</b>: התוכן מכאן עד סיום המאמר נמצא ג\"כ להלן בתוך ד\"ה צאינה וראינה. וראה גם לעיל ד\"ה וישב יעקב, פיסקא: וביאור הענין איך ע\"י תומ\"צ."],["264","7","<b>וכמ\"ש מזה בלק\"ת בד\"ה תורה צוה בפ' הברכה</b>: דף צד, ד."],["265","8","<b>בביאור מאה\"ז ע\"פ לא טוב היות האדם לבדו (הלשון שלא נדפס)</b>: ראה ביאוה\"ז לאדהאמ\"צ א, ד ואילך. ולהצ\"צ ח\"ב ע' תריב. ועוד נוסחאות של הביאוה\"ז (מליל ש\"ק פ' תולדות תקס\"ו) נמצא בכתבי-יד ועדיין לא נדפסו."]]],[2000460156,"שבחי' מקיף דטבעת זהו המקיף שהחתן משפיע להכלה מקיף פרטי לקדשה, פי' הפשוט להפרישה לו, וגם לפי פי' לקדשה ע\"ד שנת' בענין ברכת המצות<sup data-n=\"266\">9</sup> אשר קדשנו בקדש העליון להיות בחי' ואנשי קדש כו' זהו ג\"כ מקיף פרטי להעלותה, וכמארז\"ל עולה עמו, ע\"ד הקדשת הקרבן, ונדירת דבר הנדור שצריך להוציא בשפתיו דוקא שעקימת שפתים הוי מעשה, ובאירוסין הוא גם במעשה בפו\"מ בלבישת הטבעת כו'. אמנם כ\"ז הוא בחי' אירוסין לבד, אמנם בכדי שיהי' ענין בחי' נשואין בחי' יחוד פנימי' א\"א בלא חופה שזהו המקיף כללי המקיף חו\"כ ביחד דוקא, כי כדי שיהי' נמשך השפעה פנימיות צ\"ל נמשך תחלה גם בבחי' חתן. והענין הוא, שבחי' אירוסין זהו מה שהחתן משפיע להכלה מבחי' נובלות חכ' שלמעלה תו' שזהו הארה בעלמא וכמו מ\"ט אמר קרא שזהו מבחי' רמזים ואותיות לבד וכמו וא\"ו דוכי ישאל מזה נלקח כל פרק השואל כו', אמנם בכדי שיומשך שפע פנימיות החכ' שזהו שרשו מבחי' מו\"ס שלמעלה מחכ' סתם שזהו לא יש גם בבחי' חתן לזה צריכי' שניהם להתעלות תחת בחי' מקיף החופה שזהו מבחי' ישת חשך סתרו בחי' כתר ומשם נמשך להחתן בחי' פנימיות החכ' שיוכל להשפיע להכלה בחי' תושבע\"פ להוליד בדומה לו כו', כמ\"ש מזה בד\"ה תורה צוה וביאורו בפ' הברכה<sup data-n=\"267\">10</sup>.\n<b>וענין</b> בחי' חופה בעבודה זהו ענין תשובה שאע\"פ שנת\"ל שירידת הנשמה הוא בשביל תורה, הנה באמת ענין ירידת הנשמה הוא בשביל תשובה ג\"כ, דהנה הנשמה קודם שירדה לעוה\"ז היתה במדריגת צדיקי', פי' שכמו קריאת שם צדיק בהתלבשות הנשמה בגוף יקרא למי שמקיים תומ\"צ כמ\"ש מזה בד\"ה מי יתנך כאח לי שלא נדפס ובהביאורי' באורך<sup data-n=\"268\">11</sup>, ובקצרה לפי שכלליות כל המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו כו' לכן המקיים נק' בשם צדיק, ועוי\"ל לפי שעל מצות שלנו נצטוינו לברך אשר קדשנו במצותיו, והיינו מפני שעי\"ז ממשיכי' בחי' מצותיו שיהי' הקב\"ה מניח תפילין המשכת מוחין לז\"א, וכדומה בכל המצות, ולמעלה כתי' כל מצותיך צדק שבאמת זהו צדקה לבד כי מאי איכפת לי' אם שוחט מן העורף כו' אלא שזהו בדרך צדקה להחיות רוח שפלי' שקמי' כל העולמות עליוני' הם שפלי' כו' כמ\"ש במ\"א באורך<sup data-n=\"269\">12</sup>, ועש\"ז נק' המקיים תומ\"צ בשם צדיק וכתי' ועמך כולם צדיקי' כו', כן עד\"ז הנשמה כמו שהיא למעלה כשעומדת לפניו ית' וכמשנ\"ת לעיל בד\"ה אריב\"ל<sup data-n=\"270\">13</sup> שענין העמידה זהו בחי' ביטולה בבחי' אהוי\"ר, ה\"ה אז במדרגת הצדיקי' היינו כמו בהתלבשותה בגוף כשמקיימת המוטל עלי' נק'",[["266","9","<b>שנת' בענין ברכת המצות</b>: לעיל סד\"ה מי כה' אלקינו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380433\" data-slug=\"likkutei-torah\" data-id=\"4001380433\">לקו\"ת בהעלותך ל, ד</a>. ובכ\"מ."],["267","10","<b>בד\"ה תורה צוה וביאורו בפ' הברכה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381110\" data-slug=\"likkutei-torah\" data-id=\"4001381110\">לקו\"ת ברכה שם צה, ד</a> ואילך."],["268","11","<b>בד\"ה מי יתנך כאח לי שלא נדפס ובהביאורי' באורך</b>: סה\"מ תקס\"ה ע' תפז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770306\" data-slug=\"or-hatorah-hb\" data-id=\"8316770306\">אוה\"ת שה\"ש ע' תרעד</a>. וראה ד\"ה זה תרל\"א (סה\"מ תרל\"א ע' קטו ואילך. וש\"נ)."],["269","12","<b>להחיות רוח שפלי'. . כמ\"ש במ\"א באורך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. סה\"מ תרל\"ג ח\"ב ע' תסה. ובכ\"מ."],["270","13","<b>וכמשנ\"ת לעיל בד\"ה אריב\"ל</b>: נדפס לפני מאמר זה."]]],[2000460157,"בשם צדיק, כן קודם התלבשותה ה\"ה במדריגת צדיק בשם המושאל ע\"ש שמקיימת עמידתה כו', אבל אח\"כ נעשה בחי' בע\"ת, ע\"ד מ\"ש והרוח תשוב אל האלקי' אשר נתנה כו', דהנה ארז\"ל יפה שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב, ואם הפי' תשובה הוא על חטא ועון מהו יפה כ\"כ הלא משביעין אותו תהי צדיק, שלא יצטרך לתשובה, אלא שבאמת אין הפי' תשובה על עוונות דוקא, אלא הפי' תשובה הוא כמ\"ש והרוח תשוב<sup data-n=\"271\">14</sup> אל האלקי' אשר נתנה, דהיינו החזרת פב\"פ, דהנה אם אדם נמשך אחר גשמי' הוא בחי' רחוק מאלקות וכמו למשל ב' בנ\"א שהם עומדים אחור באחור אף שעומדי' מקרוב מ\"מ כיון שהם אחור באחור נקראי' רחוקי', אבל כשהם עומדי' פב\"פ נקראי' קרובים, וכמ\"כ למעלה בעבודה הנה שכשאדם נמשך אחר גשמי' אף שהוא סור מרע ועשה טוב מ\"מ כיון שהוא בבחי' חיצוני' נק' רחוק וכמ\"ש כי פנו אלי עורף<sup data-n=\"272\">15</sup> ולא פנים אף שפנו אלי הוא רק בבחי' עורף, אבל תשובה היא החזרת פב\"פ שהוא בחי' אהבה בבחי' רעו\"ד דהיינו אהבה דבכל מאדך שהוא בלי גבול ממש.\n<b>והנה</b> כדי לבוא לבחי' אהבה זו בבחי' רעו\"ד זהו דוקא למטה, כי הנשמות למעלה אף שהי' להם אוי\"ר בהתגלות מ\"מ הוא רק בחי' בכל לבבך ובכל נפשך שאהבה זו מתלבשת בכלי הנפש, משא\"כ אהבה דכל מאדך זהו דוקא למטה מבחי' העלם והסתר הגוף דוקא, כי יתרון האור הוא מתוך החשך דוקא, וכמשל המים כשסותמין אותה מתגברת הילוכה כמ\"ש במ\"א בד\"ה רפאני ה'<sup data-n=\"273\">16</sup> וארפא, ונמצא שאע\"פ שיש לה גרעון באהוי\"ר טבעיות שבחיצוני' הלב הגלוי' מ\"מ יהי' לה יתרון בבחי' רעו\"ד בנקודת פנימי' הלב כיתרון האור הבא מן החשך.\n<b>ועפ\"ז</b> יובן מה שבא הציווי על ההתבוננות שמפני שנתלבשה בגוף ונה\"ב הנה בכדי שתבוא לבחי' אהבה דבכל לבבך ובכל נפשך צריכה ג\"כ התבוננות ויגיעה כו', והעיקר הוא בחי' בכל מאדך שזהו בחי' החופה שע\"ז הוא ההבטחה שסופך לבוא לידי אהבה כו'.",[["271","14","<b>אין הפי' תשובה על עוונות. . אלא. . כמ\"ש והרוח תשוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380962\" data-slug=\"likkutei-torah\" data-id=\"4001380962\">לקו\"ת</a> דרושים לר\"ה ס, ד. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a>. האזינו עא, ג. סה\"מ תרח\"צ ע' יג ואילך. וש\"נ."],["272","15","<b>למשל ב' בנ\"א. . וכמ\"ש כי פנו אלי עורף</b>: ראה בכ\"ז לקו\"ת אחרי כו, ד. דרושים לשמע\"צ פז, א."],["273","16","<b>כמ\"ש במ\"א בד\"ה רפאני ה'</b>: ראה סה\"מ תרס\"ח ח\"א ע' רטו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940284\" data-slug=\"or-hatorah-hb\" data-id=\"8159940284\">אוה\"ת בחוקותי ע' תרצ</a> ואילך. נ\"ך ע' שמז."]]],[2000460158,"<h3>טעמה כו' לא יכבה בלילה נרה כו'</h3>\n<b>בס\"ד.</b>\n<b></b>ה' אלקינו ה' כו' עשה רצונו כו' כדי כו'\nטעמה<sup data-n=\"274\">1</sup> כי טוב סחרה לא יכבה בלילה נרה, ופי' המצ\"ד שמפני שטעמה שטוב סחרה גם בלילה לא יכבה הנר. . .\n<b><b></b>[המשך המאמר עד גמירא נמצא לקמן, בתוך ד\"ה שמע ישראל<sup data-n=\"275\">2</sup> פיסקא: והענין הוא דכתי' טעמה]. </b>",[["274","1","<b>טעמה</b>: מאמר זה נכלל בתוך ד\"ה שמע ישראל, הנדפס בסמוך (ובגוכתי\"ק נרשם בתחילה המאמר ד\"ה טעמה, ואח\"כ ניתוסף בגוכי\"ק התחלה נוספת ד\"ה שמע ישראל)."],["275","2","<b>שמע ישראל</b>: מאמר זה הוא המשך להמאמרים הקודמים ד\"ה מי כה' אלקינו וד\"ה אריב\"ל וד\"ה ואהבת והוא מהדו\"ב ותוס' הגהות לד\"ה וישב יעקב הנדפס לעיל (מפיסקא: והנה כדי לבוא לבחי' רעו\"ד, ואילך). וראה עניני המאמר באריכות בד\"ה טעמה כי טוב סחרה בסה\"מ תש\"ה ע' 159 ואילך. לתחילת המאמר ראה גם ד\"ה טעמה בסה\"מ תש\"ט ע' 28-27 וע' 33."]]],[2000460159,"<h3>שמע ישראל כו' (ד)</h3>\n<b></b><b>בס\"ד. (ש\"פ וארא, ט\"ל).</b>\nטעמה כו' לא יכבה בלילה נרה\nוארא\n<b>שמע</b> ישראל ה' כו' ואהבת כו' ובכל מאדך, והיו הדברי' האלה כו', והקשו המפרשים למה א' בפסוק ראשון ג' שמות רצופי', שלכאו' לפי נושא הענין כפשוטו הי' די אם הי' אומר ה' אלקינו אחד, ולמה כפל ש' הוי' באמרו ה' אלקינו ה' אחד, ומה בא להשמיענו בזה. וגם צ\"ל אמרם ז\"ל ע\"פ והיו הדברי' האלה שבד\"ת הכתוב מדבר, והיינו כי א\"א לפרש שקאי על מצות ק\"ש שהרי היא רק פעמי' ביום לבד, ומהו שא' בשבתך ובלכתך כו' שכפשוטו משמע תמיד שזה אינו שייך בדבר שמצותו פעמי' במעל\"ע, אלא שקאי על ד\"ת שעיקר מצותה הוא כמ\"ש והגית בה יומם ולילה, ולכן ארז\"ל בסוף מנחות בענין לימוד שארי דברים בשעה שאינו לא יום ולא לילה ע\"ש, רק שלבעלי עסקים די בפרק א' שחרי' ופ\"א ערבי', (ועמ\"ש בהגהות לד\"ה כתפוח בעצי היער<sup data-n=\"276\">1</sup>, שאין ההמשכה שוה למי שעוסק בתורה תמיד), אמנם עיקר מצותה הוא תמיד שע\"ז שייך לו' בשבתך כו', ולכן אמרו שבד\"ת הכתוב מדבר, אך לכאו' אינו מובן מ\"ע לבכל מאדך שנת' במא' הקודמי' שזהו בחי' רעו\"ד לדבקה בו שלמעלה מהגבלת הכלי' ומהו שייך לתורה שבא כל דבר בהגבלה את זה תאכלו, וזה לא תאכל כו' עד\"מ, וכן כל דיני התו' הכל הוא בהגבלה כשר פסול טמא טהור איסור והיתר כו'.",[["276","1","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640189\" data-slug=\"or-hatorah-hb\" data-id=\"8316640189\">ועמ\"ש</a> בהגהות לד\"ה כתפוח בעצי היער</b>: אוה\"ת שה\"ש (כרך א) ס\"ע קפט. סה\"מ תרל\"ו ח\"ב ע' שעב."]]],[2000460160,"<b>והענין</b> הוא דכתי' טעמה כי טוב סחרה לא יכבה בלילה נרה, ופי' המצ\"ד שמפני שטעמה שטוב סחרה גם בלילה לא יכבה הנר שעוסקת בסחורה בלילה ג\"כ. ואמנם יש לפרש עוד ע\"פ משארז\"ל במד\"ר פ' ראה התורה והנפש קרוי' נר, נר הוי' נשמת אדם, ובתו' כתי' כי נר מצוה ותו\"א. וצ\"ל שהגם שהתו' נק' אור, זהו בחי' אור תו' שארז\"ל בכתובות קי\"א, אבל עצם מצוותה י\"ל שנכלל בכלל נר מצוה, וע\"ש שא' ז\"ל נרי בידך שקאי על נר התו' ונרך היינו נר הנשמה בידי כו' אם כבית כו' ע\"ש. ולפ\"ז יש לפרש מ\"ש לא יכבה בלילה נרה קאי על נר התו' ונר הנשמה שהרי במד\"ר פ' בא ע\"פ ויהי בחצי הלילה, אמרו ז\"ל שבתיה בת פרעה הגם שהיתה בכורה עכ\"ז ניצולה בזכות משה ע\"ש, ובילקוט שם ובמקומו במשלי הוסיף ליל כתי' וקאי על ליל שמורים היינו בשעה שמתו כל הבכורות ניצולה בתיה וזהו לא יכבה בליל שמורי' נרה היינו נשמתה כמד\"א נר ה' נשמת אדם, א\"כ גם פסוק זה פירושו על נר הנשמה. ופי' בלילה י\"ל ב\"פ, הא' כמארז\"ל ריש פסחי' עוה\"ז שדומה ללילה, א\"כ קאי על ירידת הנשמה בגוף, ועיקר פי' לילה הוא בזמן שאין בהמ\"ק קיים, שאז הוא חשך ולילה כו', ועכ\"ז באמת גם בלילה לא יכבה נר הנשמה ע\"י שמירת נר התורה, אך זה כשטועם כי טוב סחרה, שקאי על ירידת הנשמה בגוף שנק' בשם עסקא כמ\"ש בעה\"כ של הסה\"ד וכמ\"ש מזה במ\"א באורך<sup data-n=\"277\">2</sup> בענין היתר עיסקא ע' ד\"ה כי בועליך עושיך<sup data-n=\"278\">3</sup>, וכשטועם כי טוב סחרה היינו מסחור זה של ירידת הנשמה בגוף, אזי גם בלילה לא יכבה הנר מלהאיר שגם זמן הלילה כיום יאיר כו'.\n<b>ושרש</b> ענין המסחור זהו כמשנ\"ת לעיל בד\"ה אריב\"ל ובד\"ה ואהבת, שהגם שאהוי\"ר שלה מתמעט עכ\"ז ע\"י הפיזור של האהוי\"ר שלה מוסיף עוד שטוב לי תורת פיך כו' ושע\"י ירידתה באה לבחי' תשובה בחי' חופה, שבעבודה זהו בחי' רעו\"ד בכל מאדך כו', שזה בא מהתלבשותה בגוף דוקא.\n<b>אך</b> הנה כדי לבוא<sup data-n=\"279\">4</sup> לבחי' רעו\"ד זהו ע\"י ההתבוננות שיתבונן בהעמקת הדעת במ\"ש אני ראשון ואני אחרון ומבלעדי אין אלקי', פי' אני ראשון היינו כמו קודם בריאת העולמות שהי' לבדו וכמ\"ש עד שלא נבה\"ע הי' הוא ושמו בלבד, ואני אחרון קאי על מה שיהי' לאחר נו\"ן אלפי' יובלות כו', ומבלעדי אין אלקי' פי' מה שהוא זולת בחי' זו דהיינו באמצעית הזמן שנראה העולם ליש ודבר בפ\"ע בחי' זמן ומקום אין אלקי' זולתי כו', כי אין ההסתר דש' אלקי' מסתיר לפניו כו', כי רק לעינינו נראה בחי' הסתר והעלם שנראה העולם ליש ודבר נפרד, אבל באמת קמי' ית' אין הסתר וכמו שהוא",[["277","2","<b>בעה\"כ של הסה\"ד וכמ\"ש מזה במ\"א באורך</b>: בערכי הכינויים של בעל הסדר הדורות (מערכת הלואה). וראה בכ\"ז גם (בנוסף לד\"ה כי בועלייך הנסמן לקמן): אוה\"ת משפטים ע' א'קע. שם (כרך ח) ע' ג'ל. סה\"מ תרכ\"ו (הוצאת תשמ\"ט) ע' פ-פא. סה\"מ תרכ\"ט ע' עד-עה. קפה-קפו. ד\"ה טעמה בסה\"מ תש\"ט שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031272\" data-slug=\"likkutei-sichot\" data-id=\"1300031272\">לקו\"ש ח\"ג ע' 1010</a> ואילך."],["278","3","<b>ע' ד\"ה כי בועליך עושיך</b>: ס' ”תורת שמואל — דרושי חתונה\" ע' קלב."],["279","4","<b>אך הנה כדי לבוא</b>: פיסקא זו היא מתוך ד\"ה וישב יעקב דלעיל (ראה בהמ\"מ בתחילת המאמר כאן)."]]],[2000460161,"לבדו קודם שנבה\"ע כמ\"כ הוא גם עתה הוא לבדו הוא כי אין העולם תופס מקום כלל, וכמ\"ש אני הוי' לא שניתי וכולא קמי' כלא חשיב ממש. והנה כשיתבונן אדם בבחי' רוממות אלקות כו' ובפחיתות ערכו איך שהוא רחוק מאלקות, אי לזאת תכלה ותכסוף נפשו ליבטל במציאות אליו ית' לצאת ממאסר הגוף ונרתקה להשתפך נפשה אל חיק אבי' בבחי' רעו\"ד ממש, שהוא בחי' בכל מאדך כנ\"ל ובדרושי' הקודמי'.\n<b>ואמנם</b> עדיין צ\"ל אי' מרומז התבוננות זו בפסוק שמע כו' שהוא ההתבוננות על כל ג' בחי' האהבה שא' בפסוק ואהבת, הנה זהו מה שנא' בפסוק שמע ג' שמות ה' אלקינו ה', שלכאו' הי' מספיק שיאמר ה' אלקינו אחד כנ\"ל, ותי' הרוקח<sup data-n=\"280\">5</sup> שג' שמות אלו מורים על מ\"ש אני ראשון, ואני אחרון ומבלעדי, והיינו כנ\"ל שאני ראשון הכוונה קודם שנבה\"ע, וכמו\"כ קודם שנאצל אצי' העליון, וכמ\"ש בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, ובעה\"ק שעד שלא נאצל אצי' העליון הי' הוא ושמו בלבד, שהוא שמו העצמי ש' הוי' כו', ואני אחרון הכוונה על לע\"ל דכתי' בי' ונשגב ה' לבדו ביום ההוא שיהי' גילוי אוא\"ס באופן אחר לגמרי מכמו שהוא עתה אפי' בעולמות העליוני', שהרי יהי' נו\"ן אלפי' יובלות שנת' במ\"א שזהו בא\"א ששם הוא מספר גדול<sup data-n=\"281\">6</sup> כו', ואני אחרון י\"ל שזהו בכלות בחי' הנו\"ן אלפי' יובלות שאז יהי' בחי' ונשגב ה' לבדו ביום ההוא, שיהיו ביטול העולמות כו', ומבלעדי באמצעיתא אין אלקי' כנ\"ל שבחי' ההסתר זהו לעינינו לבד אבל קמי' אין שום דבר מסתיר כלל, וע\"ז רומזי' הג' שמות ה' אלקינו ה', שב' שמות ה' רומזי' על אני ראשון ואני אחרון, וש' אלקי' מורה על מבלעדי אין אלקי' שגם באמצעיתא דהיינו בהיות שנמשך הנהגת והתהוות העולמות ע\"י בחי' ש' אלקי' המעלים ומסתיר, שהרי אלקי' בגימ' הטבע שנראה לעיני בשר שהעולם יש ודבר נפרד בפ\"ע ועולם כמנהגו נוהג, אמנם באמת גם הנהגת הטבע הוא בחי' נסים תכופי' כמ\"ש בתשו' ח\"צ<sup data-n=\"282\">7</sup>, וה' אלקי' כולא חד שההסתר נמשך מאתו ית' שכמו שהוא מקור בחי' הגילוי כ\"ה מקור בחי' ההסתר כמ\"ש וחכיתי לה' המסתיר פניו, וכמ\"ש מזה במ\"א באורך<sup data-n=\"283\">8</sup> שכשם שיש בבחי' ש' הוי' שהוא הנראה מקור בחי' הגילוי כמ\"כ יש בבחי' ש' הוי' שהוא מסתיר פניו פי' שאינו מאיר בבחי' גילוי ע\"ד מ\"ש יאר ה' פניו כו' אלא שהוא מסתיר ע\"י אמצעית ש' אלקי' בכדי שעי\"ז יאיר בחי' היותר גבוה וכמ\"ש במ\"א וע' בד\"ה תתן אמת ליעקב שבתוך ד\"ה ואולם חי אני<sup data-n=\"284\">9</sup>, ששרש בחי' ההסתר הוא מבחי' היותר נעלה משרש בחי' הגילוי' כו'.",[["280","5","<b>שנא' בפסוק שמע ג' שמות ה' אלקינו ה'. . ותי' הרוקח</b>: בהבא לקמן בפיסקא זו ושלאחרי' ראה בארוכה סה\"מ תרכ\"ז ע' שה ואילך. וש\"נ. תרכ\"ט ע' רעו ואילך. וש\"נ."],["281","6","<b>נו\"ן אלפי' יובלות שנת' במ\"א שזהו בא\"א ששם הוא מספר גדול</b>: ראה גם שע\"ת לאדהאמ\"צ כט, ב ואילך. קמה, א ואילך."],["282","7","<b>הטבע. . נסים תכופי' כמ\"ש בתשו' ח\"צ</b>: ראה בארוכה לקמן ד\"ה מזמור לתודה. וש\"נ."],["283","8","<b>וחכיתי לה' המסתיר פניו וכמ\"ש מזה במ\"א באורך</b>: ראה סה'מ תרכ\"ו ע' רז. תרכ\"ז ע' שפה. תרכ\"ט ע' קסג (וע\"ש בהמ\"מ). תרל\"ב ח\"א ע' רעו. ח\"ב ע' תקפז וע' תר."],["284","9","<b>וע' בד\"ה תתן אמת ליעקב שבתוך ד\"ה ואולם חי אני</b>: ראה סה\"מ תרל\"ד ע' רסב. שסב ואילך."]]],[2000460162,"<b>ועל</b> ג' בחי' אלו נא' בק\"ש ג' שמות ה' אלקינו ה', שב' שמות הוי' זהו בחי' ש' הוי' שמו הגדול שקודם שנאצל אצילות העליון הי' הוא ושמו בלבד כנ\"ל, והוי' השני זהו כמ\"ש ונשגב ה' לבדו ביום ההוא, וש' אלקי' רומז על בחי' באמצעיתא דהיינו בשית אלפי שני דהוי עלמא, ובחי' וחד חרוב, וכל עליות הנו\"ן אלפים יובלות שהם בחי' הגילוי' מא\"א כו' הנה גם באמצעיתא בשית אלפי שני שנראה העולם ליש ודבר זהו רק לעינינו בכדי שיהי' נראה מציאות היש, ואז ע\"י העבודה יכול להיות בחי' ביטול היש לאין שע\"ז ארז\"ל גדולים מעשה צדיקים ממעשה שמים וארץ (כתובות ד\"ה) שע\"י בחי' ביטול היש זוכים להיות במדריגת גדולי' שי\"ל גם בחי' מספר גדול דא\"א הנ\"ל כו', אמנם קמי' אין אלקי' שאין זה הסתר כלל, שזהו כמשל אב חכם ורחמן המסתיר עצמו מבנו, בכדי שבנו יהי' לו געגועי' עליו ויכלה נפשו להשתפך אל חיק אביו, כן ענין ירידת הנשמה שהיא חלק אלקה ממעל להתלבש בגוף ונה\"ב שמאפיל ומסתיר אורה היתה זאת מלפניו ית' בכדי שע\"י ההסתר הזה תתגבר תשוקת הנפש לצאת מנרתיקה הוא הגוף המגבילה ולבוא לידי רעו\"ד שהוא רצון פשוט ליכלל וליבטל באוא\"ס לדבקה בו כו'.\n<b>וכ\"ז</b> הוא ע\"י היותו בחי' אל מסתתר דוקא שהרי לבוא לבחי' רעו\"ד זו זהו ע\"י ההסתר דוקא שמסתיר פניו, והנשמה ירדה ממשכן כבודה שהיתה עומדת לפניו ית' באהוי\"ר כמ\"ש בדרושים הקודמי', ונתלבשה בבחי' ההסתר דחשך כפול הגוף ועוה\"ז כו', אמנם כ\"ז הוא בשביל כי יתרון האור הוא מתוך החשך דוקא, שעי\"ז יאיר אור הנפש לבוא לבחי' רעו\"ד שהיא גבוה מאד נעלה יותר מכמו שהיתה קודם ירידתה, שהרי קודם ירידתה להתלבש בגוף היתה אהבתה ודביקותה בשרשה לפ\"ע השגתה לבד, אבל ע\"י ירידתה בגוף באה לבחי' בכל מאדך שהוא בלי גבול, פי' למעלה מהגבלת הכלים כל אחד לפי מדרגתו, וכמ\"ש במ\"א שמחסד ה' אלינו מקבל בחי' מאד שלנו שעי\"ז יומשך מאד העליון<sup data-n=\"285\">10</sup> כו', וזהו בחי' רעו\"ד כו'. וזהו ג\"כ העלי' שע\"י הירידה, שע\"י רעו\"ד רצון פשוט הנ\"ל שיוצאה מהגבלת כלי הגוף, עי\"ז בשרשה יוצאה ג\"כ מהגבלתה הנבראת או גם הנאצלת, שהרי גם נשמות דאצי' מרוחקי' מן הק\"ו כמ\"ש באגה\"ק<sup data-n=\"286\">11</sup>, כי פתחי לי כחודה של מחט ואני אפתח לך כפתחו של אולם כו', שזהו עלי' שכדאי הפיזור בשביל ריוח זה כו', וכ\"ה בבחי' היראה כו'.",[["285","10","<b>וכמ\"ש במ\"א. . בחי' מאד שלנו שעי\"ז יומשך מאד העליון</b>: ראה סה\"מ תרכ\"ט ע' קכא. תרל\"ב ח\"א ע' שב. תרל\"ג ח\"ב ע' תקעד ואילך. ובכ\"מ."],["286","11","<b>שהרי גם הנשמות דאצי' מרוחקים מן הק\"ו כמ\"ש באגה\"ק</b>: ס\"כ (קל, א)."]]],[2000460163,"<b>והנה</b> בזמן שבהמ\"ק הי' קיים<sup data-n=\"287\">12</sup> הי' נמשך בחי' זו רעו\"ד מגילוי אוא\"ס ב\"ה בהיכל ק\"ק, דהנה איתא עשה רצונו כרצונך<sup data-n=\"288\">13</sup> כדי שיעשה רצונך כרצונו, פי' שיעשה רצונך כרצונו דהיינו כמו שרצה\"ע ב\"ה הוא בלי גבול ממש כמ\"כ יהי' רצון האדם ג\"כ בלי גבול בחי' רעו\"ד, והנה באמת האדם מצ\"ע א\"א לו להגיע לבחי' רצון זה רק שרצון זה נמשך מלמעלה, וזהו מ\"ש רז\"ל כדי שיעשה רצונך כרצונו שהקב\"ה עושה רצון זה באדם וכמ\"ש פותח את ידיך ומשביע לכל חי רצון, שהקב\"ה משביע רצון זה, רק שמתחלה צריך שיהי' פותח את ידיך, ידיך הוא בחי' יודיך, דהיינו פתיחת דיודי\"ן יו\"ד בחי' חכ' דהיינו שיעשה האדם רצון העליון ב\"ה כרצונו שמתחלה צריך לייגע אדם א\"ע שיגיע לבחי' רצון שע\"פ חכ' שהוא בחי' רצון התחתון ועי\"ז אח\"כ ומשביע לכל חי רצון, רצון שלמעלה מן השכל, וזהו עשה רצונו כרצונך שמתחלה צריך שיעשה האדם רצון העליון ב\"ה כרצונו ממש, שהוא בחי' רצון שע\"פ השכל ועי\"ז יעשה הקב\"ה רצונך כרצונו.\n<b>והנה</b> בזמן בהמ\"ק היו עושים רצונו ש\"מ ע\"י עבודת הקרבנות וכמ\"ש ריח ניחוחי ופי' רז\"ל נחת רוח לפני שאמרתי ונעשה רצוני, ועי\"ז שהיו עושים רצונו של מקום עי\"ז הי' נמשך מלמעלה שיגיעו לבחי' רצה\"ע ממש, אך בזמן הגלות מצרים הנה כתי' ובקשתם משם את ה' אלקיך ומצאת, משם דוקא דהיינו מסט\"א, וכמ\"ש קראו שם פרעה<sup data-n=\"289\">14</sup> מלך מצרים, כי אלקי' יכולים למצוא בכל מקום. וביאור ענין משם זהו ע\"ד שארז\"ל על ר\"ע כשראה כרך גדול של רומי שחק ואמר אם לעוברי רצונו כך לעושי רצונו עאכ\"ו, והיינו שאנו רואי' שעוברי רצונו מקבלי' השפעתם יתירה שלא לפ\"ע מעשיהם כלל ומאין נשפע להם שפע וחיות להיות בהם חיות וקיום מרצונו ית', שהרי רצונו ית' הוא המחי' אותם וכמ\"ש ואתה מחי' את כולם, אך ע\"ז אמרו כמה ארך אפים לפניו<sup data-n=\"290\">15</sup> שמבחי' ארך אפים נמשך ונשתלשל ממדרגו' העליונות דרך נפילה להחיות העובדי כוכבי' אף שהם עוברי רצונו, וזהו אם לעוברי רצונו כך שהם מקבלי' מבחי' רצה\"ע שלמעלה מן השכל, לעושי רצונו עאכו\"כ שיקבלו מבחי' רצה\"ע שהוא למעלה מעלה מגדר עלמין שלא בבחי' ירידות והשתלשלו' המדרגו' בבחי' חכ' ומדות אלא בבחי' פנימי' נקודת הלב שהוא בחי' תשו\"ע שקדמה לעולם, וזהו כי תדרשנו בכל לבבך ובכל נפשך שתחלה צ\"ל בכל לבבך ובכל נפשך אהבה שע\"פ טעם ודעת וכמ\"ש לאהבה את ה' כי הוא חייך כו', וכן בענין המצות הנה נודע כי אהוי\"ר הם שרש רמ\"ח מ\"ע ושס\"ה ל\"ת, וזהו עשה רצונו כרצונך שהרי התומ\"צ נתלבשו בדברים גשמיי' והם יכולים להיות נעשים כרצונך שע\"פ טו\"ד כו', ועי\"ז הקב\"ה נותן לנו כח ועוז",[["287","12","<b>והנה בזמן שבהמ\"ק הי' קיים</b>: מכאן עד קרוב לסיום המאמר (פיסקא: וז\"ש והי' הדברים), הוא מתוך ד\"ה וישב יעקב דלעיל (ראה בהמ\"מ בתחילת המאמר כאן)."],["288","13","<b>איתא עשה רצונו כרצונך</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381232\" data-slug=\"likkutei-torah\" data-id=\"4001381232\">לקו\"ת שה\"ש כה, ד</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380316\" data-slug=\"likkutei-torah\" data-id=\"4001380316\">לקו\"ת במדבר ב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380796\" data-slug=\"likkutei-torah\" data-id=\"4001380796\">ראה כ, א</a>. ובכ\"מ."],["289","14","<b>ובקשתם משם. . מסט\"א. . קראו שם פרעה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380845\" data-slug=\"likkutei-torah\" data-id=\"4001380845\">לקו\"ת ראה לב, ג</a>. ועוד."],["290","15","<b>ע\"ז אמרו כמה ארך אפים לפניו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>. ועוד."]]],[2000460164,"שיעשה רצונינו כרצונו בלי גבול שזהו בחי' בכל מאדך רעו\"ד, והיינו שיהפוך לבו מן הקצה אל הקצה ואתהפכא חשוכא לנהורא ע\"י בחי' רעו\"ד זו למאוס בחיי עוה\"ז ותענוגי' ולימשך לבו ונפשו לדבקה בו ית'.\n<b>והנה</b> כ\"ז עד\"מ הסוחר שמוציא כסף וזהב מרשותו להיות מפזר ונוסף עוד, כך הנשמה אע\"פ שמוציאה כסף וזהב שהוא בחי' אוי\"ר הגלוים להתלבש ולהסתיר בגוף ונה\"ב, הנה עי\"ז יש לה יתרון בבחי' רעו\"ד כרשפי אש מן ההיפוך, וזהו וחם הוא אבי כנען בזקף גדול שחמימות רשפי אש ושלהבת העולה מאלי' מן ההיפוך הוא העושה בחי' כנען לסחור כנ\"ל כמ\"ש טעמה כי טוב סחרה.\n<b>והנה</b> בחי' רעו\"ד זו הוא בחי' החופה לפי שאהבה מאיר בבחי' מקיף על הנפש שאין כלי הנפש יכולה להכיל את אהבה זו, ואח\"כ ביום חתונתו זו מ\"ת שע\"י התורה נעשה בחי' היחוד שהוא בחי' לאשתאבא בגופא דמלכא, כו'. וזהו מ\"ש הקל קול יעקב<sup data-n=\"291\">16</sup> קלא קדמאה חסר וא\"ו שהוא בחי' קלא דלא אשתמע וקול בתראה מלא וא\"ו שהוא בחי' קלא דאשתמע כמ\"ש בזוה\"ק, והנה בחי' קלא דאשתמע הוא בחי' התורה שהוא בחי' המשכה כמשל הקול המחבר וממשיך מצפוני כוונת הלב לבוא לידי גילוי בדבור, וכך התורה היא בחי' ח\"ע בחי' חכים ולא בחכ' ידיעא, שהרי טעמי המצות לא נתגלו להיות בהתגלות רב להבין כל עמקי סודותי' בפרטי פרטיות, ונמשכת לבחי' גילוי ע\"י התלבשותה בדברים גשמיי' סדר זרעים מועד כו', והיא בחי' קול והמשכה של יעקב יו\"ד עקב דהיינו מבחי' יו\"ד שהוא ח\"ע להיות נמשך עד עקב והוא העשי'. אך כדי שיהי' האדם כלי ומכון שיהי' ח\"ע שורה ומתגלה בו בעסק התורה צ\"ל תחלה בבחי' ביטול בבחי' רעו\"ד שהוא בחי' חופה והוא בחי' קלא דלא אשתמע דרוח אמשיך רוח להיות אור ה' שורה ומתגלה בו להיות חכמת ה' בקרבו בהתגלות וחב\"ד שבנפשו בטלי' אליו וה\"ע אתדבקות רוחא ברוחא.\n<b>וזהו</b> שא' והיו הדברי' האלה שבד\"ת הכתוב מדבר, אחר אומרו ובכל מאדך, שהיא בחי' רעו\"ד בחי' חופה, ושוב יכול להיות בחי' היחוד דתו' שהוא יחוד נפלא שאין כמוהו כמ\"ש בסש\"ב פ\"ה ע\"ש.",[["291","16","<b>מ\"ש הקל קול יעקב</b>: ראה בכ\"ז סידור עם דא\"ח יט, א-ב. לעיל סד\"ה כמים הפנים. ובכ\"מ."]]],[2000460165,"<h3>וזהו וישב כו' ענין השפלה</h3>\n<b></b><b>[סיום ד\"ה מי כה' אלקינו]</b>\n[סיום המשך מי כה' אלקינו]\nוזהו וישב יעקב<sup data-n=\"292\">1</sup> בארץ מגורי אביו, וישב הוא ענין השפלה וירידה ממקום עמידתו, ופי' שבחי' יעקב יו\"ד עקב נמשך ונשפל להיות בארץ מגורי אביו, ומגורי יש בו ב' פירושים<sup data-n=\"293\">2</sup> הא' הוא לשון יראה וכמו לא תגורו מפני איש, מגור מסביב, והב' הוא ל' אוצר כמו מגורה מליאה פירות שהוא כלי שאוצרין לתוכה, ושניהם עולים בקנה אחד כי יראת ה' היא אוצרו כתי' וכן בדרז\"ל אוצר של י\"ש שהוא בחי' יר\"ע יראה בשת בבחי' ביטול הוא כלי קבול לחכ' שיהי' שורה ומתגלה בו ונק' מגורי אביו כי יעקב הוא בחי' יו\"ד עקב הוא בחי' הארה והמשכה מבחי' ח\"ע להמשיך עד סוף כל דרגין, ובחי' ח\"ע נק' אביו, ויר\"ע שהוא בחי' ארץ עילאה שהיא בחי' בינה עילאה מקור הג\"ע העליון נק' מגורי אביו שהיא בחי' כלי לח\"ע ממש. ועוד יש ישיבה והשפלה אחרת ממדותיו של יעקב להמשיך מדת חסד מראש כל דרגין עד סכ\"ד בארץ התחתונה הוא כנען שהוא בחי' מל' ית' מקור געה\"ת ומלך במשפט יעמיד ארץ והוכן בחסד כסאו, שקיום העולם הוא בחסד כמ\"ש עולם חסד יבנה, דהיינו בעשיית המצות בכלל ששרשם הוא בחי' חסד ובפרטיות הוא מצות הצדקה וחסד שלכן נקראת בשם מצוה סתם שהיא שקולה כנגד כל המצות כמ\"ש בתניא<sup data-n=\"294\">3</sup>.\n<b>והנה</b> אח\"כ כתי' אלה תולדות יעקב יוסף, והענין הוא דהנה ג' אבות הם כנגד ג' רגלים וכנ\"ל, ויוסף הוא בחי' נהורא רביעאה לנהורין עילאין הוא בחי' ומדרגת שמע\"צ. והנה מתחלה י\"ל ענין שמע\"צ מה שעושין בשמע\"צ שמח\"ת<sup data-n=\"295\">4</sup> שלכאורה הי' צריך לעשות שמח\"ת בשבועות. אך הנה כתי' ביום חתונתו זו מ\"ת ופרש\"י ביום חתונתו זה יוהכ\"פ שבו נתנו לוחות האחרונות, והיינו לפי שהלוחות הראשונות נשתברו ולא הי' להם קיום, והלוחות האחרונות נתקיימו, לכן ביום חתונתו זו מ\"ת קאי על יוה\"כ כו'. ועוי\"ל לפי שבלוחות הראשונות הי' במדריגת צדיקי' ואח\"כ בלוחות האחרונות נעשו בחי' בע\"ת והנה במקום שבע\"ת עומדי' צד\"ג אין יכולי' לעמוד, וכן הלוחות הראשונות הי' צד\"ג, והלוחות האחרונות הוא העיקר, ובזה יובן מה שעושי' שמח\"ת בשמ\"ע לפי שעיקר השמחה עושי' על לוחות האחרונות דוקא. אך עדיין י\"ל למה אין עושין שמח\"ת תיכף אחר יוהכ\"פ.\n<b>אך</b> הענין הוא דהנה שמע\"צ הוא בחי' היחוד<sup data-n=\"296\">5</sup>, והנה היחוד צ\"ל תחלה בחי' חופה, והנה יוכ\"פ הוא בחי' החופה, דהנה המעלה של יוכ\"פ הוא שהוא יום התשובה",[["292","1","<b>וזהו וישב יעקב</b>: הבא לקמן הוא סיום הדרוש להמשך ד\"ה מי כה' אלקינו והמאמרים שלאח\"ז. והוא מהדו\"ק בתוס' הגהות ולא נרשם בגוכי\"ק במהדו\"ב."],["293","2","<b>ומגורי יש בו ב' פירושים</b>: ראה גם סה\"מ מלוקט חלק ב ע' רו-ז. וש\"נ."],["294","3","<b>שהיא שקולה כנגד כל המצות כמ\"ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</b>: פל\"ז (מח, ב</a>)."],["295","4","<b>מה שעושין בשמע\"צ שמח\"ת</b>: בהבא לקמן ראה בארוכה ד\"ה ביום השמע\"צ תרל\"ב בסה\"מ תרל\"א. וש\"נ."],["296","5","<b>אך הענין הוא דהנה שמע\"צ הוא בחי' היחוד</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381111\" data-slug=\"likkutei-torah\" data-id=\"4001381111\">לקו\"ת ברכה צו, א</a> (בשינויים)."]]],[2000460166,"שהוא בחילא יתיר בחי' חופה לפי שהוא למעלה מגדר הכלי ואינו יכול להתלבש בכלי כלל, ולכן יוהכ\"פ הוא בחי' חופה כנ\"ל, ואח\"כ בשבעת ימי הסוכה שהוא בחי' שבעת ימי המשתה הוא ג\"כ המשכה זו רק בבחי' מקיף בחי' צל סוכה שהוא המשכת המקיפי' שמלמעלה, וכדי שיומשך היחוד בבחי' פנימי' זהו ע\"י המשכת הדעת כי דעת הוא בחי' התחברות ולכן היחוד נק' בשם דעת, וכמ\"ש והאדם ידע, והנה המשכת הדעת הוא ע\"י ד' מינים שבלולב וכמ\"ש בפע\"ח שד' מינים הוא ממשיך בחי' דעת ולכן ע\"י ד' מינים אלו נמשך אח\"כ היחוד בשמע\"צ שהיא המשכה בבחי' פנימי', וכמ\"ש ביום השמיני עצרת תהי' לכם, עצרת לשון קליטה כו', ולכן עושי' שמח\"ת בשמע\"צ דוקא, לפי שאז הוא עיקר השמחה לפי שאז נמשכה המשכה בבחי' פנימי', משא\"כ ביוה\"כ וסוכות הוא הכל רק המשכה שבבחי' מקיף כו'.\n<b>והנה</b> בחי' שמע\"צ הוא מדרגת יוסף שהוא רגלא רביעאה לכורסי', דהנה באמת י\"ל בענין שמע\"צ שבגמ' אמרו ששמע\"צ הוא רגל בפ\"ע וא\"כ אינו מובן למה אינו נא' בתורה כ\"א שלש רגלים וכמ\"ש שלש רגלים תחוג לי בשנה, אך הנה איתא בגמ' שאפי' למ\"ד ששמע\"צ הוא רגל בפ\"ע הני מילי לענין פז\"ר קש\"ב, אבל לענין תשלומין חדא רגל נינהו. והענין הוא דהנה שמע\"צ הוא ענין מה שנמשך המשכה זו בבחי' פנימי' ממש, שביוהכ\"פ הוא רק המשכה שבבחי' מקיפי' לבד דהיינו שהמשכה זו הוא רק למעלה באצי' כי סוכות הוא מדרגת יעקב, והנה על מדת יעקב נא' והבריח התיכון מבריח מן הקצה כו' דהיינו מקצה העליון עד בחי' קצה התחתון שהוא בחי' מל', אבל מ\"מ המשכה זו היא רק למעלה באצי', וזהו וישב יעקב בארץ מגורי אביו בארץ כנען שהוא ממשיך בבחי' ארץ עילאה עד בחי' ארץ תתאה שהוא בחי' מל', אבל מ\"מ ההמשכה זו היא רק למעלה באצי' ונק' רק בחי' מקיף לבד, אבל כדי שיומשך המשכה זו בבי\"ע זהו ע\"י יוסף דוקא שיוסף הוא הממשיך למטה בבחי' פנימי' ממש שזה\"ע שמע\"צ שהוא המשכה בבחי' פנימי' כו', והנה כדי שיומשך המשכה למטה זהו\"ע פיזור, כי א\"א שיומשך למטה כמו שנמשכה למעלה ולכן נק' פיזור (הג\"ה. וזהו מ\"ש צדקת פרזונו בישראל, צדקה עשה הקב\"ה עם ישראל שפיזרן בין האומות, שפירזונו הוא לשון פיזור ונא' פרזונו ע\"ש פרזות תשב ירושלים, והיינו שעתה נא' על חומותיך ירושלים, שיש לירושלים בחי' חומה, שזהו ג\"כ ענין חותם כי חומת וחותם<sup data-n=\"297\">6</sup> הוא ענין אחד כדי שלא יהי' יניקת החיצוני', וזהו ענין חותם של נעילה של יוהכ\"פ לפי שביוהכ\"פ ממשיכי' ממקום גבוה מאד בחי' לפני הוי' תטהרו, ומצד שהוא המשכה ממקום גבוה מאד שם כחשיכה כאורה שוין, ויכול להיות מזה יניקת החיצוני' לכן צריך לחותם, והושענא רבא הוא בחי' חותם בתוך חותם, אך שמע\"צ הוא מבטל את החותם לפי שהוא ע\"ד לע\"ל שנא' פרזות תשב ירושלים שלא יהי' יניקת החיצוני' כלל, ולכן שמע\"צ מבטל את החותם כו' לפי שבשמע\"צ נא' עצרת תהי' לכם דוקא ואין צריך לחותם כלל, ולכן נא' פרזות וגם הוא לשון פיזור לפי שהמשכה זו נמשך למטה דוקא בבחי' פנימי' כו').",[["297","6","<b>וזהו מ\"ש צדקת פרזונו. . חומת וחותם</b>: בהבא לקמן בפיסקא זו ראה סה\"מ תרכ\"ו ס\"ע רפז-ח. תרכ\"ט ע' נט ואילך. וש\"נ."]]],[2000460167,"<b>והנה</b> המשכה זו בבחי' פנימי' הוא ע\"י יוסף דוקא לפי שיוסף הוא בן שבע עשרה שנה שהוא בגי' טוב שיוסף הוא מדרגת טוב, וכמ\"ש אמרו לצדיק כי טוב, והנה טוב הוא מקור ההשפעה, שמקור ההשפעה הוא מדת הטוב כו' לפי שטבע הטוב להטיב כו' ולכך ע\"י יוסף דוקא נמשך המשכה בבחי' פנימי' כו', ולכך הי' יוסף למטה פזרן מאד וכמ\"ש ויוסף הוא המשביר לכל עם הארץ, ויכלכל יוסף את כל בית אביו כו'. וזהו הני מילי לענין פזר, שהוא רגל בפ\"ע לענין פזר דהיינו לענין המשכה שנמשך למטה כו', וקשב הוא ל' הקשיבו אלי ואדברה שהוא ל' קליטה והיינו שיוקלט השפעה במקבל וכמ\"ש עצרת תהי' לכם עצרת הוא ל' קליטה בפנימי' והשפעה זו נקלטת במקבל ע\"ד בור סוד שאינו מאבד טפה, ולענין זה הוא רגל בפ\"ע, אבל לענין תשלומין חדא רגל נינהו, לפי שבאמת אין המשכה זו המשכה חדשה ממש רק מה שנמשך בסוכות ע\"י יעקב שהוא בחי' בריח התיכון, המשכה זו ממש נמשכה בשמע\"צ ע\"י יוסף. וזהו שיעקב ויוסף הוא וא\"ו עם המילוי<sup data-n=\"298\">7</sup>, וזהו שנא' ביעקב ואלקי יעקב שיעקב הוא בבחי' וי\"ו בריח התיכון כו' ויוסף הוא המילוי של הוי\"ו, והנה וי\"ו עם המילוי הוא בחי' אחת שמילוי הוי\"ו הוא ג\"כ וי\"ו וא\"א לומר וי\"ו בלתי<sup data-n=\"299\">8</sup> המילוי וי\"ו שאין במילוי שום התחדשות כלל, והיינו לפי שמה שיעקב ממשיך למעלה זה עצמו ממשיך יוסף למטה נמצא שאין בהמשכה זו דבר חדש כלל לכן לא נא' בתורה כ\"א שלש רגלי' ולא נחשב שמע\"צ לרגל בפ\"ע רק לענין פזר קשב דהיינו שלענין זה הוא רגל בפ\"ע שאע\"פ שע\"י יעקב שהוא רק המשכה שבבחי' מקיף לבד אבל כדי שיהי' הפיזור בהמשפיע שיומשך למטה, וגם לענין קשב כדי שיוקלט השפעה זו במקבלי' לענין זה הוא רגל בפ\"ע כו', אך אעפ\"כ בחי' ומדרגת יוסף הוא בחי' שמיני דוקא ששמיני הוא בחי' שומר את המקיף שלמעלה מהשבעה, ולפי שזהו הכלל שכדי שיומשך למטה דוקא צריך שיהי' ההמשכה ממקום גבוה יותר, וכמ\"ש המגביהי לשבת המשפילי לראות בשמים ובארץ, והיינו לפי שהוא מגביהי לשבת שלמעלה מסדר השתלשלות לכך המשפילי כו', שכח ההשפעה נמשך דוקא מבחי' המגביהי כו', וזהו שמדרגת יוסף היא בחי' שמיני, לכן נק' יוסף ע\"ש תוס' אורות כו'.\n<b>ובזה</b> יובן ג\"כ ענין חנוכה שהוא תמני יומי' דוקא כי בבהמ\"ק הי' המנורה של ז' נרות ונר חנוכה היא שמונה נרות, דהנה בנר יש ד' בחי'<sup data-n=\"300\">9</sup> שמן ופתילה ותרי גווני אור, שמן ופתילה היא בחי' העלאה והמשכה וב' גווני אור שהוא נהורא אוכמא ונהורא חיוורא שהוא בחי' הקול קול יעקב שהוא בחי' רעו\"ד ותורה כו', והנה בבהמ\"ק הי' רק ז' נרות, ובנ\"ח הי' שמונה נרות דהנה נר חנוכה היא על פתח רשות הרבים מבחוץ שהוא בחי' טורי דפרודא, וכדי שיומשך למטה גם בטורי דפרודא לכן צריך שיומשך דוקא מבחי' שמונה שהוא מדרגת שמע\"צ שהיא מדרגת יוסף שמשם לא יוכל להיות יניקת החיצוני' כלל וכמ\"ש ולא עמד איש<sup data-n=\"301\">10</sup> בהתוודע יוסף אל אחיו,",[["298","7","<b>שיעקב ויוסף הוא וא\"ו עם המילוי</b>: ראה סה\"מ תרכ\"ט ע' כז. וש\"נ. וע' שפו."],["299","8","<b>וי\"ו בלתי</b>: תיבות אלו חסרות בס' תרל\"ט. וניתוספו כאן מכת\"י 1063."],["300","9","<b>בנר יש ד' בחי'</b>: ראה גם לקמן ד\"ה וככה הא' והב'. וש\"נ."],["301","10","<b>שמע\"צ. . מדרגת יוסף. . ולא עמד איש</b>: ראה בכ\"ז אוה\"ת דרושים לשמע\"צ ע' א'תשעא. א'תשצג."]]],[2000460168,"כמ\"ש בזח\"א דר\"ח ב' בזמנא דקוב\"ה כו' בגין כך ביום השמיני עצרת תהי' לכם דוקא, כי ז' ימי הסוכו' הקריבו ע' פרים כנגד ע\"ש שמשם יוכלו גם הם לקבל, לפי שהמשכה זו רק בבחי' מקיף כו', משא\"כ ביום השמיני<sup data-n=\"e14\">*</sup> עצרת תהי' לכם דוקא, לפי שממדרגת שמיני אינם יכולים לקבל, וכך בנ\"ח לפי שהיא על פתח הבית שמשם יוכל להיות יניקת החיצוני' לכן הם תמניא דוקא, ושרש המשכה זו הוא ג\"כ ע\"י טוב, וזהו מ\"ש בנרות בהטיבו את הנרות שהוא בחי' מקור טוב ששרש מדת הטוב נמשך מבחי' הטוב כי לא כלו רחמיך שהוא בחי' מקור י\"ג מדה\"ר ולכך נא' בנרות בהטיבו את הנרות לפי שהנרות הם המשכה למטה זהו ע\"י מדת הטוב כו'.\n<b>והנה</b> בבהמ\"ק לא הי' רק ז' נרות לפי שהי' המנורה בהיכל שמשם לא יוכל להיות יניקת החיצוני' לכן הי' רק ז' נרות, משא\"כ בנ\"ח שהיא על פתח הרבים לכן צריך שמונה דוקא ע\"י שמע\"צ שהוא רגל בפ\"ע לענין פזר קשב כו', נמצא שיש שייכות לנ\"ח לשמע\"צ וסוכות. וזהו שב\"ש אומרים פוחת והולך כפרי החג, ולכאורה אינו מובן מה שייך נ\"ח לפרי החג, אך לפי הנ\"ל יובן היטב לפי שבאמת הם ענין אחד ולכך מדמה אותם ב\"ש לפרי החג כו', וב\"ה אומרים טעם אחר הגם שהסברא נותנת שיהי' מדמין לפרי החג אך מעלין בקודש ולא מורידין, אבל באמת ענין נ\"ח ושבעת ימי הסוכות ושמע\"צ הם ענין אחד, וזהו ג\"כ ענין מילה שניתנה בשמיני, שהיא ג\"כ המשכה מבחי' שומר את המקיף, לכן ע\"י המילה נא' ג\"כ בשם הוי' כי אמילם, שמשם נכרתים כל החיצוני' שאינם יכולים לקבל שום יניקה לפי שהוא מדרגת שמיני כו'. וזהו וישב יעקב בארץ מגורי אביו בארץ כנען, שיעקב הוא הממשיך בארץ עילאה ובארץ תתאה אך מ\"מ המשכה זו היא רק למעלה, אבל למטה היא רק בבחי' מקיף, אך אלה תולדות יעקב יוסף שעיקר המכוון הוא שיומשך למטה דוקא בבי\"ע זהו ע\"י יוסף דוקא, ומפרש הטעם יוסף בן שבע עשרה שנה, כי יוסף הוא מדת הטוב, אמרו לצדיק כי טוב, ומצד זה יכול להמשיך אפי' למטה ג\"כ וכו'.",[["e14","*","<b>ביום השמיני עצרת. . וכך בנ\"ח. . הם תמניא דוקא</b>: בשולי הגליון רשום בגוכי\"ק:\nלכאו' א\"מ מאחר שמדריגת יוסף הוא שמיני ועד\"ז חנוכה שמונה ימי', א\"כ למה הי' צריך להוציא כל איש מעליו עד שלא עמד איש אתו בהתודע כו' הלא נ\"ח עיקר מצותה משתשקע החמה ועד שתכלה רגל היינו דכלי' רגלי דתרמודאי שזהו עכ\"פ בשעה שנמצאי' אנשי' דתרמודאי הנ\"ל, וגם נ\"ח ברה\"ר שזהו רשות לכל, וביוסף הוא לכאו' בהיפך שצוה שיוציאו כל איש מרשותו ולא ישאר רק הוא ואחיו כו', וכן בשמע\"צ צ\"ל ג\"כ למה פר אחד איל אחד מדוע גם כשהיו מקריבי' פרי' ואילי' הרבה עכ\"ז יהי' לכם דוקא פר אחד איל אחד כו'."]]],[2000460169,"<h3>צאינה וראינה כו'</h3>\n<b>בס\"ד.</b>\n<b></b>חתונתו זו מ\"ת כו' נתיב הל\"ב כו' חופה (ואח\"כ) קידושין\nצאינה וראינה<sup data-n=\"302\">1</sup> כו' ביום חתונתו, וארז\"ל במשנה שלהי תענית זו מ\"ת, וקאי על לוחות אחרונו' שהרי או' ולא היו יו\"ט כו' וכיוהכ\"פ, והגם שבודאי לוחות ראשונו' קרוי' ג\"כ ביום חתונתו מ\"מ רז\"ל אמרו על מ\"ת דלוחות אחרונו' שנתקיימו.\n<b>והענין</b> הוא שצ\"ל מה שתקנו בברכת אירוסין לחתום מקדש עמו ישראל על ידי חופה וקדושין, מה\"ע חופה דוקא כו', שהיא הקדמה לקדושין כו' וכמארז\"ל כלה בלא ברכה אסורה לבעלה כנדה. והענין הוא דהנה תלת קשרין מתקשראין דא בדא ישראל כו'.\n<b>והענין</b> הוא דהנה כתי'<sup data-n=\"303\">2</sup> ביום חתונתו זו מ\"ת, שתו' נק' בשם חתונה בחי' יסוד, והיינו שע\"י תומ\"צ שלמטה עי\"ז מתאחד הנשמה באא\"ס ממש שהוא בחי' לאשתאבא בגופא דמלכא ממש וכמשל יחוד חתן וכלה שנעשים אדם אחד ממש, וכמ\"ש זכר ונקבה בראם ויקרא שמם אדם, ונק' תרי פלגא גופא כמ\"ש בזהר, משא\"כ הנשמה קודם ירידתה לעוה\"ז אף שהי' לה אוי\"ר בהתגלות אעפ\"כ היתה בבחי' נפרד, וכמו המלאכי' שהם נפרדי' אף שאומרי' קדוש וברוך תמיד באהבה ברשפי אש, אבל ע\"י התורה עי\"ז מתאחדי' ממש לפי שהתורה היא בחי' תורת הוי' וכן במצות נא' מצות הוי', הקב\"ה מניח תפילין ומתעטף בציצית כו', והמצות עליונות ממש כמו שהן למעלה נמשכו ונתלבשו למטה במצות גשמי', ואף שנתלבשו בגשמי' אך באמת היא הנותנת כו' וכמ\"ש במ\"א<sup data-n=\"304\">3</sup>, וזהו המשל מבחי' חתונה שאף שהטפה שנמשך ממוח האב היא נתגשמה ממש בבחי' טפה גשמי' מ\"מ מלובש בה מעצמיות המוחי' ממש, שהרי מטפה זו נתהווה להוליד בדומה לו ממש, וכך עד\"מ זה יובן שמה שהקב\"ה מניח תפילין כו' כי ע\"י שאנו מניחי' תפילין שלנו, עי\"ז ממשיכי' שיהי' הקב\"ה מניח תפילין וכידוע, ועמ\"ש במ\"א בענין פי' המד\"ר ע\"פ מגיד דבריו ליעקב<sup data-n=\"305\">4</sup> כו' מה שהוא עושה אומר לישראל לעשות שמה שהוא עושה כבי' זהו ע\"י שאומר כו'.\n<b>ויש</b> להעיר לענין הנמשל למעלה ממארז\"ל במד\"ר וישלח ס\"פ ע\"ט ע\"פ ויקרא לו אל אלקי ישראל א\"ל אתה אלקה בעליוני' ואני אלקה בתחתוני', ונענש ע\"ז ע\"ש",[["302","1","<b>צאינה וראינה</b>: במאמר זה נמצא גם תוכן מאמרים דלעיל, ד\"ה אמר ריב\"ל וד\"ה ואהבת את ה' אלקיך. וע\"ש בהמ\"מ. [וראה הערת כ\"ק אדמו\"ר זי\"ע ברשימת מאמרי דא\"ח למאמר זה]. וראה לקמן בהוספות הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ד\"ה ואהבת את ה\"א וד\"ה לה\"ע מה שחותמים בברכת אירוסין."],["303","2","<b>והענין הוא דהנה כתי'</b>: התוכן מכאן (עד פיסקא: וביאור הענין) נמצא ג\"כ לעיל בד\"ה אמר ריב\"ל. וראה גם לעיל ד\"ה וישב יעקב, פיסקא: והענין הוא דהנה כתיב."],["304","3","<b>והמצות עליונות. . ואף שנתלבשו בגשמי'. . וכמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380496\" data-slug=\"likkutei-torah\" data-id=\"4001380496\">לקו\"ת שלח מו, א</a>. ועוד."],["305","4","<b>ועמ\"ש במ\"א בענין פי' המד\"ר ע\"פ מגיד דבריו ליעקב</b>: ראה סה\"מ תרכ\"ח ע' פז. תרכ\"ט ע' רכג."]]],[2000460170,"במפרשי', ובמגילה די\"ח ארז\"ל שהקב\"ה קרא ליעקב אל, וע' בהרמב\"ן בפי' החומש במקומו, והענין הוא כי דברי המד\"ר הנ\"ל נת' במ\"א<sup data-n=\"306\">5</sup> בענין ספי' ת\"ת שאבינו יעקב הי' מרכבה לה שע\"ז אמר ואני אלק' בתחתונים, ואינו שייך כ\"כ לכוונת דרוש זה, אמנם דברי רז\"ל במגילה שאמרו שהקב\"ה קרא ליעקב אל, י\"ל הכוונה ע\"פ מ\"ש בס\"י בל\"ב נתיבות פליאות חכ' חקק כו' שיש בחכ' בחי' ל\"ב נתיבות, וכן בבינה יש נש\"ב, כמארז\"ל חמשים שערי בינה נבראו בעולם, והנה במשה נא' ותחסרהו מעט מאלקי' ופירשו בזה שהשיג רק מ\"ט שערי בינה, ועד יום מותו לא השיג שער החמשים וזהו ותחסרהו מעט היינו בחי' שער הנו\"ן דבינה מבחי' אלקי' דבינה, רק שבעת הסתלקותו השיג גם שער הנ' ג\"כ ולכן ארז\"ל לעליוני' נדמה להם למטה לתחתוני' נדמה להם למעלה שקאי עשה\"נ כמ\"ש מזה במ\"א ע' מזה בד\"ה את שבתותי תשמורו שלא נדפס, ובהגהות לשם<sup data-n=\"307\">6</sup>, וכמו שהוא בנש\"ב כן גם בל\"ב נת\"ח יש ג\"כ נתיב אחד אשר עליו נא' (איוב ך\"ח וא\"ו) נתיב לא ידעו עיט ולא שזפתו עין איה, שבחי' נתיב זה לא ידעו כלל, וי\"ל פי' איה קאי על האומרי' איה מקום כבודו (כ\"פ במא\"א<sup data-n=\"308\">7</sup>) שגם הם אינם יודעי' מנתיב זה, ויש לבאר ע\"פ משנ\"ת במ\"א שאי' מקום כבודו אומרי' האופני' וחיות הקדש<sup data-n=\"309\">8</sup>, שהרי השרפי' אומרי' מלא כה\"כ, וארז\"ל בחולין פרק גיד הנשה שאני אופני' שמכסא עצמו, לכן מזכירים את השם אחר ב' תיבות, ועכ\"ז גם הם אינם יודעי', והיינו לא מיבעי שהשרפי' אינם משיגי' זה שהרי זהו בעצם למעלה מהשגה, ולכן א\"א להם להשיג בחי' זה כלל, כי השרפי' הם משיגי' רק בד\"כ שאוא\"ס ב\"ה הוא קדוש ומובדל מגדר עולמות, ולכן רצונם וחפצם ליכלל וליבטל באוא\"ס שלמעלה מבחי' מקור לעולמות, ומאן דכסיף אע\"ג דלא יכיל שבחא אית לי', ולכן נאמר עליהם שרפי' עומדים ממעל לו היינו לש' אד' הנז' תחלה, או ממעל לבחי' וא\"ו מקור דמקור לעולמות כי ששת ימים כו' וכתי' כי אמרתי עולם חסד יבנה, וכפי ב' הפי' שבתי' יבנה כמ\"ש במ\"א<sup data-n=\"310\">9</sup>, וכמו שפי' הבעש\"ט ז\"ל שבמקום שרצונו של אדם<sup data-n=\"311\">10</sup> עד\"מ שם הוא בחוזק ה\"ז כאלו עומד שם כו', ולכן גבי השרפי' מאחר שרצונם ליכלל באוא\"ס הסוכ\"ע שלמעלה מהארה המתצמצם בעולמות ה\"ז כאלו עומדי' שם כו', ועכ\"ז מזכירי' את השם אחר ב' תי' לפי שהם מכסא עצמו, ומ\"מ הם ברעש גדול כמשנ\"ת במ\"א<sup data-n=\"312\">11</sup> שזהו מפני העדר ההשגה שעי\"ז נעשה הרעש גדול, ולכן הם הם הממשיכי'",[["306","5","<b>כי דברי המד\"ר הנ\"ל נת' במ\"א</b>: ראה סה\"מ תרל\"ב ח\"א ע' לז ואילך. ושם ע' קנט וע' קצט ואילך."],["307","6","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940212\" data-slug=\"or-hatorah-hb\" data-id=\"8159940212\">ע' מזה</a> בד\"ה את שבתותי תשמורו שלא נדפס, ובהגהות לשם</b>: ראה מאמרי אדה\"ז תק\"ע ס\"ע פח ואילך. אוה\"ת בהר כרך ב ע' תריח. סה\"מ תרל\"ב ח\"ב ע' תקנב."],["308","7","<b>כ\"פ במא\"א</b>: תיבה זו אינה ברורה בגוכתי\"ק. [וראה מאו\"א א, כב]. ובכת\"י המעתיק הר\"ש סופר רשום כאן: במאמ\"א."],["309","8","<b>ע\"פ משנ\"ת במ\"א שאי' מקום כבודו אומרי' האופני' וחיות הקדש</b>: ראה סה\"מ תרל\"ג ח\"א ע' יג ואילך. ח\"ב ע' תקפד ואילך. תרל\"ד ע' רמה ואילך."],["310","9","<b>וכפי ב' הפי' שבתי' יבנה כמ\"ש במ\"א</b>: ראה סה\"מ תרל\"ד ע' נד ואילך."],["311","10","<b>וכמו שפי' הבעש\"ט ז\"ל שבמקום שרצונו של אדם</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830086\" data-slug=\"or-hatorah-hb\" data-id=\"8158830086\">אוה\"ת</a> בראשית כרך ו תתרכז, ב. במדבר (הוספות) ע' 86. ובכ\"מ."],["312","11","<b>ומ\"מ הם ברעש גדול כמשנ\"ת במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380383\" data-slug=\"likkutei-torah\" data-id=\"4001380383\">לקו\"ת במדבר יח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380423\" data-slug=\"likkutei-torah\" data-id=\"4001380423\">נשא כח, ד</a> ואילך. ובכ\"מ."]]],[2000460171,"בחי' כבוד ה' ממקומו פי' ממקורו ושרשו ע\"ד ממקומו הוא מוכרע כמ\"ש מזה בד\"ה ואולם חי אני ובהביאורי' שלא נדפסו ובהג\"ה לשם<sup data-n=\"313\">12</sup>, וע' בד\"ה כי במקלי עברתי<sup data-n=\"314\">13</sup> בענין כי ב\"מ ר\"ת ברוך כבוד ה' ממקומו, שזהו ע\"י היותם מי בכים כו', וע' בד\"ה אני דפ' ציצית<sup data-n=\"315\">14</sup> שמרעש נעשה שער בימין ושער בשמאל ע\"ש, ואחר כל השבח הזה דאופנים עכ\"ז בחי' נתיב זה הל\"ב לא שזפתו עין איה שגם האומרי' איה מקום כבודו ג\"כ אינם יודעי' ממנו שיהי' מזה אצלם בחי' רעש מפני העדר השגתם, כי הרעש על העדר ההשגה צריך לידע עכ\"פ שיש מה להשיג והם אינם משיגי' ומזה נעשה הרעש, אבל בנתיב זה אינו שייך גם שזיפת עין מין הנק' איה היא הראה והדיה שבס' דברים כמארז\"ל בחולין<sup data-n=\"316\">15</sup> היא ראה דיה היא אי', ונק' ראה ע\"ש שרואה למרחוק, ע\"ד אמרתי אחכמה והיא רחוקה, וה\"ז משל שגם ראיית השכל ע\"ד ידיעת המציאות אינו ידוע לאותם האומרי' אי' מקום כבודו, (רק לנשמות שגבהה מעלתם ממלאכי' כנודע, וירדו להתלבש בגוף דוקא ולברר נה\"ב, נתגלה לנו ע\"פ ס\"י שיש ל\"ב נ\"ח).\n<b>והנה</b> ארז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות שנא' להנחיל אוהבי יש, יש הוא ש\"י עולמות, וצ\"ל מ\"ע מספר ש\"י דוקא, אך הענין הוא שזהו נגד בחי' הל\"א נתיבות דחכ', שכ\"א כלול מעשר עולה מספר ש\"י כו', ונודע כי ארז\"ל שלשה הטעימן הקב\"ה מעין עוה\"ב ולכן נא' ביעקב ויקרא לו אל, היינו בחי' ל\"א נ\"ח הנ\"ל שזהו מעין עוה\"ב שיהיו ש\"י עולמות כו', ולכן פי' בזהר שאל הוא נהירא דחכמתא לפי שקאי על ל\"א נת\"ח כו', וה\"ז הוא בדומה לו כבי' שקראו אל, ע\"ד שארז\"ל עתידים צדיקי' שיקראו ע\"ש של הקב\"ה, ופרש\"י שיהי' שמם הוי', היינו בחי' הוי' בחכמה כו'.\n<b>וביאור</b> הענין איך ע\"י תומ\"צ<sup data-n=\"317\">16</sup> תהי' הנשמה מתאחדת באוא\"ס ממש, הענין הוא דהנה תורה נק' ביום חתונתו, והנה חתונה צריך מתחלה בחי' חופה, וע\"י החופה עי\"ז יכול להיות אח\"כ היחוד, וזהו מ\"ש מקדש עמו ישראל ע\"י חופה וקדושין, והובא בהרא\"ש קושי' למה מזכירין חופה בברכת אירוסין, הלא כשהיו מברכין ברכת אירוסין בזמן שנהגו לארס תחלה לא הי' חופה כלל, ול\"ל להזכיר דבר שא\"צ, ותירצו שזהו בכדי להזכירו שלא ברכת האירוסין מתיר כ\"א החופה שבשעת הנשואין דוקא כו'. אמנם עדיין אינו מובן מדוע אינם מזכירי' בברכת נשואין ענין החופה שאז הוא",[["313","12","<b>כמ\"ש מזה בד\"ה ואולם חי אני ובהביאורי' שלא נדפסו ובהג\"ה לשם</b>: ראה ס' מאמרי אדה\"ז תקס\"ט ע' קפג ואילך. מאמרי אדה\"ז עה\"ת ע' תרכז. וע' תרלב ואילך. מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'עח ואילך. א'קנד ואילך. א'קמז ואילך. אוה\"ת שלח ע' תקי ואילך. סה\"מ תרל\"ד ע' רמה ואילך."],["314","13","<b>וע' בד\"ה כי במקלי עברתי</b>: סה\"מ תרל\"ג ח\"א ע' רלה."],["315","14","<b>וע' בד\"ה אני דפ' ציצית</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a> ואילך."],["316","15","<b>הראה והדיה שבס' דברים כמארז\"ל בחולין</b>: פ' ראה יד, יג. חולין סג, ב."],["317","16","<b>וביאור הענין איך ע\"י תומ\"צ</b>: התוכן מכאן (עד סיום המאמר), נמצא ג\"כ לעיל בד\"ה ואהבת את ה' אלקיך. וראה גם לעיל ד\"ה וישב יעקב, פיסקא: וביאור הענין איך ע\"י תומ\"צ."]]],[2000460172,"דבר בעתו גם למנהגיהן שהיו מארסין תחלה ואח\"כ חופה ונשואין, ולמה הקדימו להזכיר בברכת אירוסין שא\"צ לחופה כלל שההיתר הוא ע\"י חופה דוקא, ובנשואין עצמם לא תיקנו להזכיר, וגם אצלינו שאירוסין ונשואין הם ביחד לא זזה ממקומה כו'.\n<b>והענין</b> הוא כנודע שענין האירוסין הוא בחי' מקיף שמקדשה בטבעת ואומר לה הרי את מקודשת כו', שהטבעת הנה רק בחי' מקיף שממשיך לה חיות מועט להיות מקודשת לשון הפרשה לו כו', וכמ\"ש מזה בלק\"ת בד\"ה תורה צוה בפ' הברכה<sup data-n=\"318\">17</sup>, אמנם נשואין הוא בחי' השפעה פנימי' להוליד בדומה לו, וכמ\"ש מזה בביאור מאה\"ז ע\"פ לא טוב היות האדם לבדו (הלשון שלא נדפס)<sup data-n=\"319\">18</sup> בביאור ענין ההבדל שבין זיווג נשיקין כו' לענין זיווג גופני דזו\"נ להוליד נשמות ע\"ש, רק שבחי' מקיף דטבעת זהו המקיף שהחתן משפיע להכלה מקיף פרטי לקדשה, פי' הפשוט להפרישה לו, וגם לפי פי' לקדשה ע\"ד שנת' בענין ברכת המצות<sup data-n=\"320\">19</sup> אשר קדשנו בקדש העליון להיות בחי' ואנשי קדש כו' זהו ג\"כ מקיף פרטי להעלותה וכמארז\"ל עולה עמו, ע\"ד הקדשת הקרבן, ונדירת דבר הנדור שצריך להוציא בשפתיו דוקא שעקימת שפתים הוי מעשה, ובאירוסין הוא גם במעשה בפו\"מ בלבישת הטבעת כו'. אמנם כ\"ז הוא בחי' אירוסין לבד, אמנם בכדי שיהי' ענין בחי' נשואין בחי' יחוד פנימי א\"א בלא חופה שזהו המקיף כללי המקיף חו\"כ ביחד דוקא, כי כדי שיהי' נמשך השפעה פנימיות צ\"ל נמשך תחלה גם בבחי' חתן, והענין הוא שבחי' אירוסין זהו מה שהחתן משפיע להכלה מבחי' נובלות חכ' שלמעלה תורה שזהו הארה בעלמא וכמו מ\"ט אמר קרא שזהו מבחי' רמזים ואותיות לבד וכמו וא\"ו דוכי ישאל מזה נלקח כל פרק השואל כו', אמנם בכדי שיומשך שפע פנימיות החכ' שזהו שרשו מבחי' מו\"ס שלמעלה מחכ' סתם שזהו לא יש גם בבחי' חתן, לזה צריכי' שניהם להתעלות תחת בחי' מקיף החופה שזהו מבחי' ישת חשך סתרו בחי' כתר ומשם נמשך להחתן בחי' פנימיות החכ' שיוכל להשפיע להכלה בחי' תושבע\"פ להוליד בדומה לו כו' כמ\"ש מזה בד\"ה תורה צוה וביאורו בפ' הברכה<sup data-n=\"321\">20</sup>.\n<b>וענין</b> בחי' חופה בעבודה זהו ענין תשובה, שאע\"פ שנת\"ל שירידת הנשמה הוא בשביל תורה, הנה באמת ענין ירידת הנשמה היא בשביל תשובה ג\"כ, דהנה הנשמה קודם שירדה לעוה\"ז היתה במדרגת צדיקים, פי' שכמו קריאת שם צדיק בהתלבשות הנשמה בגוף יקרא למי שמקיים תומ\"צ כמ\"ש מזה בד\"ה מי יתנך כאח לי שלא נדפס ובהביאורי' באורך<sup data-n=\"322\">21</sup>, ובקצרה לפי שכלליות המצות נק' בשם צדקה כמ\"ש",[["318","17","<b>וכמ\"ש מזה בלק\"ת בד\"ה תורה צוה בפ' הברכה</b>: דף צד, ד."],["319","18","<b>בביאור מאה\"ז ע\"פ לא טוב היות האדם לבדו (הלשון שלא נדפס)</b>: ראה ביאוה\"ז לאדהאמ\"צ א, ד ואילך. ולהצ\"צ ח\"ב ע' תריב. ועוד נוסחאות של הביאוה\"ז (מליל ש\"ק פ' תולדות תקס\"ו) נמצא בכתבי-יד ועדיין לא נדפסו."],["320","19","<b>שנת' בענין ברכת המצות</b>: לעיל סד\"ה מי כה' אלקינו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380433\" data-slug=\"likkutei-torah\" data-id=\"4001380433\">לקו\"ת בהעלותך ל, ד</a>. ובכ\"מ."],["321","20","<b>בד\"ה תורה צוה וביאורו בפ' הברכה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381110\" data-slug=\"likkutei-torah\" data-id=\"4001381110\">לקו\"ת ברכה שם צה, ד</a> ואילך."],["322","21","<b>בד\"ה מי יתנך כאח לי שלא נדפס ובהביאורי' באורך</b>: סה\"מ תקס\"ה ע' תפז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770306\" data-slug=\"or-hatorah-hb\" data-id=\"8316770306\">אוה\"ת שה\"ש ע' תרעד</a>. סה\"מ תרל\"א ע' קטו ואילך. וש\"נ."]]],[2000460173,"וצדקה תהי' לנו כו' לכן המקיים נק' בשם צדיק. ועוי\"ל לפי שעל מצות שלנו נצטוינו לברך אשר קדשנו במצותיו, והיינו מפני שעי\"ז ממשיכי' בחי' מצותיו שיהי' הקב\"ה מניח תפילין המשכת מוחין לז\"א, וכדומה בכל המצות, ולמעלה כתי' כל מצותיך צדק שבאמת זהו צדקה לבד כי מאי איכפת לי' אם שוחט מן העורף כו' אלא שזהו בדרך צדקה להחיות רוח שפלים שקמי' כל העולמות עליונים הם שפלים כו' כמ\"ש במ\"א באורך<sup data-n=\"323\">22</sup>, ועש\"ז נק' המקיים תומ\"צ בשם צדיק, וכתי' ועמך כולם צדיקים כו', כן עד\"ז הנשמה כמו שהיא למעלה כשעומדת לפניו ית' וכמשנ\"ת לעיל בד\"ה אריב\"ל שענין העמידה זהו בחי' ביטולה בבחי' אהוי\"ר, ה\"ה אז במדרגת הצדיקי' היינו כמו בהתלבשותה בגוף כשמקיימת המוטל עלי' נק' בשם צדיק כן קודם התלבשותה ה\"ה במדריגת צדיק בשם המושאל ע\"ש שמקיימת עמידתה כו', אבל אח\"כ נעשה בחי' בע\"ת, ע\"ד מ\"ש והרוח תשוב אל האלקי' אשר נתנה כו', והנה ארז\"ל יפה שעה אחת בתשומע\"ט בעוה\"ז מכל חיי העוה\"ב, ואין הפי' תשובה על עוונות דוקא אלא הפי' תשובה הוא כמ\"ש והרוח תשוב אל האלקי' אשר נתנה, דהיינו החזרת פב\"פ, דהנה אם אדם נמשך אחר גשמי' הוא בחי' רחוק מאלקו', וכמו למשל ב' בני אדם שהם עומדי' אחור באחור אף שעומדי' מקרוב מ\"מ כיון שהם אחור באחור נקראי' רחוקים, אבל כשהם עומדים פב\"פ נקראי' קרובי', וכמו\"כ למעלה בעבודה, הנה שכשאדם נמשך אחר גשמי' אף שהוא סור מרע ועשה טוב מ\"מ כיון שהוא בבחי' חיצוני' נק' רחוק וכמ\"ש כי פנו אלי עורף ולא פנים אף שפנו אלי הוא רק בבחי' עורף, אבל תשובה היא החזרת פב\"פ שהוא בחי' אהבה בבחי' רעו\"ד דהיינו אהבה דבכל מאדך שהוא בלי גבול ממש.\n<b>והנה</b> כדי לבוא לבחי' אהבה זו בבחי' רעו\"ד זהו דוקא למטה כי הנשמות למעלה אף שהי' להם אהוי\"ר בהתגלות מ\"מ הוא רק בחי' בכל לבבך ובכל נפשך שאהבה זו מתלבשת בכלי הנפש, משא\"כ אהבה דכל מאדך זהו דוקא למטה מבחי' העלם והסתר הגוף דוקא, כי יתרון האור הוא מתוך החשך דוקא, וכמשל המים כשסותמין אותה מתגברת הילוכה כמ\"ש במ\"א בד\"ה רפאני ה' וארפא<sup data-n=\"324\">23</sup>, ונמצא שאע\"פ שיש לה גרעון באהוי\"ר טבעיות שבחיצוניות הלב הגלוי' מ\"מ יהי' לה יתרון בבחי' רעו\"ד בנקודת פנימי' הלב כיתרון האור הבא מן החשך. ועפ\"ז יובן מה שבא הציווי על ההתבוננות שמפני שנתלבשה בגוף ונה\"ב הנה בכדי שתבוא לבחי' אהבה דבכל לבבך ובכל נפשך צריכה ג\"כ להתבוננות ויגיעה כו' והעיקר הוא בחי' בכל מאדך שזהו בחי' החופה שע\"ז הוא ההבטחה שסופך לבוא לידי אהבה כו'.",[["323","22","<b>להחיות רוח שפלים. . כמ\"ש במ\"א באורך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. סה\"מ תרל\"ג ח\"ב ע' תסה. ובכ\"מ."],["324","23","<b>כמ\"ש במ\"א בד\"ה רפאני ה' וארפא</b>: ראה סה\"מ תקס\"ח ח\"א ע' רטו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940284\" data-slug=\"or-hatorah-hb\" data-id=\"8159940284\">אוה\"ת בחוקותי ע' תרצ</a> ואילך. נ\"ך ע' שמז."]]],[2000460174,"<h3>שמח תשמח כו'</h3>\n<b>בס\"ד.</b>\n<b></b>כנס\"י נק' חתן, כלה כו' כשמחך כו' מקדם\nשמח תשמח<sup data-n=\"325\">1</sup> ריעים כו' כשמחך יצירך בג\"ע, ולכאו' יפלא הלא הבריאה יש מאין הנה היא ירידה צורך עלי', ומהו\"ע כשמחך יצירך בג\"ע. וגם צ\"ל מה\"ע שמח תשמח ריעים האהובים דהנה נודע ממ\"ש במ\"א בענין אכלו ריעים לעילא<sup data-n=\"326\">2</sup> שקאי על חו\"ב ונודע כי השמחה היא בבינה כמ\"ש אם הבנים שמחה<sup data-n=\"327\">3</sup> אבל אבא הוא למע' מן השמחה ולכן רק מועדים לשמחה אבל שבת מוחין דאבא הוא מנוחה ועונג<sup data-n=\"328\">4</sup> כמ\"ש וקראת לשבת ענג וא\"כ צ\"ל ענין אומרו שמח תשמח דמשמע שמח בעצמו ותשמח שתפעול השמחה גם בריעים הוא חו\"ב שנמצא מצד עוצם הגילוי גם החכ' תהי' שמחה כו' וצ\"ל מהו<sup data-n=\"329\">5</sup>.\n<b>אך</b> הענין יובן ע\"פ משנ\"ת בד\"ה אז ישיר דאגוסטוס<sup data-n=\"330\">6</sup> וד\"ה ועשו ארון<sup data-n=\"331\">7</sup> שפעם נק' כנס\"י חתן אל תקרי מורשה אלא מאורסה ופעם אמרו ביום חתונתו זו מ\"ת נמצא כי כנס\"י נק' כלה והענין הוא דשניהם אמת דהנה איתא בזהר תלת קשרין<sup data-n=\"332\">8</sup> מתקשראן דא בדא ישראל ואורייתא וקוב\"ה וכולהו דרגין על דרגין סתים וגלי', דהגם שהנשמה היא חלק אלוק' ממעל מ\"מ מצד שהנשמה מלובשת בגוף מתקשראן באורייתא סתים וגלי' אמנם ענין התו' שיומשך בה המשכת התו' הרוחניות כמו מה שלומדין בג\"ע<sup data-n=\"333\">9</sup> וכדומה זהו ע\"י ישראל, וגם ע\"ד דוד הי' מחבר תורה שלמעלה בהקב\"ה<sup data-n=\"334\">10</sup> שזהו בחי' המשכת אוא\"ס ע\"י שרש ומקור נש\"י שלא כל הנשמה מלובש בגוף כמ\"ש בלק\"ת בשה\"ש בד\"ה יונתי בחגוי כו'<sup data-n=\"335\">11</sup>, ואי לזאת עדיין צ\"ל דא\"כ שורש הנשמה יכולה להמשיך יותר המשכת אלקות עד שע\"י נק' נש\"י חתן לגבי התו' וא\"כ",[["325","1","<b>שמח תשמח</b>: נמצא גם בסה\"מ תרל\"א (וכאן המאמר הוא בכמה הוספות) ובסה\"מ תרל\"ה ח\"ב ע' תכד. ובס' ”תורת שמואל — דרושי חתונה\" ע' סז. עניני המאמר נמצאים בארוכה גם בד\"ה ועשו ארון המובא להלן בפנים המאמר. וראה גם ד\"ה משמח חו\"כ בס' מאמרי אדה\"ז על מארז\"ל ע' תצד ואילך. ובארוכה בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תצט ואילך. וע' תקיג ואילך."],["326","2","<b>ממ\"ש במ\"א בענין אכלו ריעים לעילא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370348\" data-slug=\"torah-or\" data-id=\"3901370348\">תו\"א משפטים עח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. ובכ\"מ.."],["327","3","<b>כי השמחה היא בבינה כמ\"ש אם הבנים שמחה</b>: ראה לקו\"ת דרושים לשמע\"צ פח, ג. ובכ\"מ."],["328","4","<b>אבל שבת מוחין דאבא הוא מנוחה ועונג</b>: ראה לקו\"ת צו יא, ריש ע\"ד. ובכ\"מ."],["329","5","<b>גם החכ' תהי' שמחה כו' וצ\"ל מהו</b>: ראה גם רד\"ה שמח תשמח תרנ\"ז (סה\"מ תרנ\"ז ע' קעג)."],["330","6","<b>ע\"פ משנ\"ת בד\"ה אז ישיר דאגוסטוס</b>: סה\"מ תרכ\"ט ע' קמה ואילך. וד\"ה זה בסה\"מ תרל\"א. וראה גם אוה\"ת בשלח ע' תצ."],["331","7","<b>וד\"ה ועשו ארון</b>: ד\"ה ועשו ארון בסה\"מ תרל\"א. וראה גם אוה\"ת תרומה ע' א'תמה. סה\"מ תרל\"ה ח\"ב ע' תמז ואילך."],["332","8","<b>דהנה איתא בזהר תלת קשרין</b>: ראה סה\"מ תרל\"ה ח\"ב ע' שמו הע' 121."],["333","9","<b>המשכת התו' הרוחניות כמו מה שלומדין בג\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. סה\"מ תרל\"ה ח\"ב ע' תנא ואילך. תרל\"ח ע' קסא ואילך. וש\"נ."],["334","10","<b>דוד הי' מחבר תורה שלמעלה בהקב\"ה</b>: ראה זהר ח\"ג רכב, ב (ברע\"מ). ספר הבהיר (סנ\"ח) סקצ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380502\" data-slug=\"likkutei-torah\" data-id=\"4001380502\">לקו\"ת שלח מז, ג</a> (במעין החכמה). שם נא, א (בס' הבהיר (נ\"א במעין החכמה)."],["335","11","<b>בלק\"ת בשה\"ש בד\"ה יונתי בחגוי כו'</b>: טז, ד."]]],[2000460175,"למה ירדה הנשמה בגוף ומהו העלי' הלא גם כמו שנתלבשה יש יתרון להנשמה שאינה מלובשת.\n<b>אך</b> הענין דבכדי שתמשיך שרש הנשמה המשכת אוא\"ס בתורה זהו ע\"י הנשמה המלובשת בגוף, וזהו\"ע התפלה שנק' סולם מוצב ארצה שכמו הסולם מחבר הגג עם הארץ כן סולם דתפלה מחברת נשמה המלובש בגוף עם שרש ומקור הנשמה, ולכן מתחלת התפלה מדברים תחתונים שלא עשני עבד, עד שעולה בשליבות הסולם פסוד\"ז וברכת ק\"ש עד ק\"ש למס\"נ באחד ושמ\"ע המשכת אוא\"ס, מפני כי מגיע שרש נפשו ואז תוכל הנשמה מצד שרש נפשה להמשיך המשכת אוא\"ס ב\"ה בתו', וזהו\"ע על שלא ברכו בתו'<sup data-n=\"336\">12</sup> הוא בחי' המשכת אוא\"ס בתורה.\n<b>ועפ\"ז</b> יובן ענין כשמחך יצירך שאין הכוונה היצירה לבדה כמו שהיא רק מכוון מה שיוצא ע\"י היצירה, שע\"י ירידה זו נעשה עלי', כי שרש הנשמה מפנימי' הכלים<sup data-n=\"337\">13</sup> וע\"י ירידתה והתקשרות נשמה שבגוף לשורש הנשמה ע\"ד העבודה מלמטלמ\"ע אז ע\"י התו' מלמעלמ\"ט ממשיכים אוא\"ס בתורה כו'. ועי\"ז מתעלים הנשמות לבחי' האור, ונמצא שהעלי' הוא מכלים לאורות. וע\"ז הי' השמחה שבשעת היצי' להיות כי הוא צופה ומביט, ומגיד מראשית אחרית, לכן אמר כשמחך יצירך בג\"ע מקדם היינו מקדם עד שלא נעשה עדיין ומ\"מ השמחה הוא ע\"י העלי' שע\"י ירידה. ואמר עוד שגם ריעים האהובים חו\"ב הגם שהם אורות המלובשים בכלים וחכ' ראשית ההשתל' הנה גם בהם תהי' השמחה פי' הגילוי כמו ששמח הוא ית' על יצירת האדם בג\"ע בבחי' קדם, שגם בסדר ההשתל' יומשך גילוי אור כ\"כ כמו בבחי' קדם שלפני ההשתל' כו'<sup data-n=\"338\">14</sup>, וזהו שמח תשמח ריעים האהובים כשמחך יצירך בג\"ע בחי' קדם כו'.\n<b>והענין</b> הוא דהנה בנין התהו הי' בנין ע\"מ לסתור<sup data-n=\"339\">15</sup> וסתירת התהו הוא ע\"מ לבנות וא\"כ הרי שניהם מחודשים, אבל קדם הוא מה שהוא בחי' קדמון שאינו מחודש, וענין כשמחך יצירך בג\"ע מקדם היינו שע\"י לעשות לתקן עי\"ז יומשך מבחי' קדם בחי' קדמון וא\"כ כשנמשך בחי' זו בחו\"ב פועל בהם השמחה, וזהו שמח מצד עצמו תשמח ריעים ג\"כ הם בחי' חו\"ב כו'.",[["336","12","<b>וזהו\"ע על שלא ברכו בתו'</b>: ראה בארוכה ס' מאמרי אדה\"ז תקס\"ט ע' ריא. אוה\"ת פינחס ע' א'קל. א'קמב. ואתחנן ע' תב-ג. סה\"מ תרכ\"ט ס\"ע רפט ואילך."],["337","13","<b>כי שרש הנשמה מפנימי' הכלים</b>: ראה עץ חיים שער כח (שער העיבורים) פ\"א. שער מ (שער פנימיות וחיצוניות) דרוש י. פרי עץ חיים הקדמה לשער השבת פ\"ה. שער השבת פ\"י. לקו\"ת פ' ראה כו, ריש ע\"ד. דרושים ליוהכ\"פ ע, ג."],["338","14","<b>כמו בבחי' קדם שלפני ההשתל' כו'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380112\" data-slug=\"likkutei-torah\" data-id=\"4001380112\">לקו\"ת צו ט, א</a>. מאמרי אדה\"ז תקע\"א ע' סז. מאמרי אדה\"ז על מארז\"ל ע' תצג. מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תצב ואילך."],["339","15","<b>בנין התהו הי' בנין ע\"מ לסתור</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. מאמרי אדמו\"ר האמצעי דברים ח\"ב ע' תקפג ואילך."]]],[2000460176,"<h3>כל הנהנה כו'</h3>\n<b>בס\"ד.</b>\n<b></b>ה' קולות כו' נשמות ומלאכים כו' קול ה' על המים\nלהבין מארז\"ל כל הנהנה<sup data-n=\"340\">1</sup> מסעודת חתן ואינו משמחו עובר בה' קולות כו', ואם משמחו זוכה לתורה שניתנה בה' קולות כו', להבין זה מהו ענין מצות השמחה לשמח החתן, ולמה הופרשה מצוה צו דפרו ורבו מכל המצות שבתורה שלא נצטוו לשמוח כ\"כ זולתי במצוה זו גדלה אזהרת השמחה לשמח חתן כו', לשמחה זו מה זה עושה.\n<b>והענין</b> הוא דהנה ידוע ההפרש שבין נשמו' למלאכי' שהמלאכי' הן בשרשן למטה במדרגה מן הנשמו', והיינו שהמלאכי' נמשכו מדבר ה' ורוח פיו ית' כמ\"ש וברוח פיו כל צבאם וגו', משא\"כ נש\"י נמשכו ממחשבה עילאה כמארז\"ל ישראל עלו במח' לפניו ית'<sup data-n=\"341\">2</sup>, ומעתה צ\"ל מדוע הנשמות הגבוהות בשרשן מאד נעלה מן המלאכי' יכולים לירד למטה בעוה\"ז להתלבש בגוף החומרי, והמלאכי' שלמטה מהם במדריגה אינן יכולי' להתלבש בגוף החומרי דעוה\"ז, ואף שיש להם גופי' הם הכלי' שבהן מתלבש החיות של המלאך ההוא, הנה הגופים שלהם הם הכלי' הם רוחנים וזכים מאד שמורכבי' גופותיהם רק מב' יסודו' הרוחנים והמעולים המה יסוד האש ויסוד הרוח<sup data-n=\"342\">3</sup>, שמב' יסודו' אלו הרוחני' מורכבי' גופותיהם כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט וגו', ואף המלאכי' דעשיי' שמתלבשי' בגופי' דעשי' המה רוחני' וזכים מאד עד שהם רואים ואינם נראים מחמת זכות ודקות גופותיהם כו' כנ\"ל, וכמארז\"ל מיכאל באחת גבריאל בשתים כו', אדרבה איפכא מסתברא שהמלאכי' יהיו מתלבשי' בגוף ולא הנשמות כו'. אך הענין הוא שלכן הנשמו' יכולי' לירד כ\"כ למטה ולהתלבש בגופי' גשמיי' מצד מעלת מדרגתן שנמשכו ממח' עילאה כמ\"ש אתה בראת אתה יצרת ואתה נפחת בי ואתה משמרה בקרבי כו', וכדכתי' ויפח באפיו נשמת חיים, והקב\"ה הוא השומר אותה להיות מתקיים בגוף, משא\"כ המלאכי' שנמשכו מרוח פיו ית' שלמטה מהמח' לכך אין באפשרי להן להתלבש בגופי' גשמיים.",[["340","1","<b>להבין מארז\"ל כל הנהנה</b>: מאמר זה נמצא בשינויים קלים בסה\"מ תקס\"ה ח\"א ע' מג, ונאמר ע\"י כ\"ק אדמו\"ר מהר\"ש בשנת תרל\"ט (ונרשם בכת\"י מעתיק בס' תרל\"ט). תוכן המאמר בשינויים מכ\"ק אדמו\"ר מהר\"ש נמצא בס' ”תורת שמואל דרושי חתונה\" ע' לט ואילך. כללות המאמר נמצא ג\"כ באריכות הביאור בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' רמא-רנ. ועוד שם ח\"ב ע' תסט-תפה."],["341","2","<b>כמאמרז\"ל ישראל עלו במח' לפניו ית'</b>: בס' תורת שמואל דרושי חתונה שם (ע' לט) מציין ע\"ז ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">לקו\"ת שה\"ש</a> ביאור יונתי (יז, ד ואילך) בפי' עלו במחשבה."],["342","3","<b>שמורכבי' גופותיהם רק מב' יסודות. . יסוד האש ויסוד הרוח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370015\" data-slug=\"torah-or\" data-id=\"3901370015\">תו\"א בראשית ד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, א</a>. ובסידור ערה, ד — בשם ”ספר הגמול\" להרמב\"ן. וראה לקמן ד\"ה אז ישיר. ולקמן בהוספות ד\"ה אריב\"ל כשעלה משה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091431\" data-slug=\"likkutei-sichot\" data-id=\"1300091431\">לקוטי שיחות ח\"ט ע' 405</a>."]]],[2000460177,"<b>ביאור</b> הדבר הוא, בהיות הנשמו' נמשכי' ממח' עילאה היא החכ' שמאין תמצא כידוע לי\"ח שהחכ' דוקא נמשכה מאין המוחלט, שאין לה ערך כלל אל מקורה האין האמיתי, שהוא בחי' יש הנמשך מהאין שאין להם ערך ושייכות זל\"ז בהדרגת ההשתל' כלל שלא הי' באפשרי להתמשך היש מהאין ע\"פ הדרגת ההשתלשלו' מאחר שאין ערך ויחוס ביניהם כלל, כ\"א המשכתה מהאין הוא שלא כדרך השתל' כו', משא\"כ מחכ' ואילך הוא סדר ההשתלשלות עילה ועלול בהדרגה וסדר דהיינו שבינה נמשכה מחכ' והמדות מבינה והמח' מן המדות והדבור מן המחשבה כו' שזהו נק' בחי' המשכה יש מיש שיש להן ערך ושייכות זל\"ז (שכמו שיש ערך המדות אל הבינה כך הוא ממש ערך הבינה אל החכ' כמ\"ש במ\"א<sup data-n=\"343\">4</sup>), משא\"כ המשכת החכ' מלמעלה מן החכ' היא שלא כסדר ההשתל' וכמ\"ש והחכ' מאין תמצא, ולכן הנשמו' שעלו במח' עילאה שנמשכה מאין כנ\"ל יורדי' למטה להתלבש בגופי' גשמיים ולהוליד בנים ובני בנים כו', שכח המוליד שנמצא באדם הוא שמהוה אדם אחר מאין ליש ממש הוא מצד שרש נשמתו שנמשכה ממח' עילאה שמאין תמצא לכך יש בו כח כזה להוליד ולהתהוות נשמה אחרת מאין ליש ממש שהיא בחי' התחדשות גמורה, וזהו נמצא בהנשמו' מצד שרשם הגבוה מאד נעלה שעלו במח' לפניו שהחכ' מאין תמצא שזהו כח אור א\"ס ית' בעצמו שכשמו כן הוא לחדש חדשות אין קץ בבחי' א\"ס ממש, וזה הכח ניתן בהנשמו' ג\"כ שיהי' נמצא בהן כח המוליד להוליד חדשות ממש מאין ליש ממש, משא\"כ המלאכי' שנמשכו מדבר ה' ורוח פיו ית' שהדיבור הוא בחי' יש ממש, לכך אין באפשרי להן להוליד מאין ליש מלאכי' אחרי' כו' כ\"א כמו שנתהוו מדבר ה' ית' כך יעמדו לעולם במעמד ומצב א' להיות כאו\"א נפרד בפ\"ע כו' (כמ\"ש במ\"א ע\"פ וכנפיהם פרודות<sup data-n=\"344\">5</sup> וגו' ע\"ש), כמו עד\"מ בנפש האדם כשהדבור יוצא מפיו בהתחלקו' ופירוד אותיות הדבור זמ\"ז אין להשיבם עוד וא\"א שיתהוה מדבור א' שיצא מפיו עוד דבור אחר כו', שכיון שיצא הדיבור מפיו ונעשה נפרד כך יהי' כמו שהוא ואינו יכול לחדש עוד כלל, משא\"כ המחשבה נובע תמיד מן השכל חדשות כו', כמ\"כ עד\"מ למעלה המלאכי' שנמשכו מדבר ה' ית' אינם יכולים לחדש ולהוליד מלאכי' אחרי', כ\"א כמו שנמשכו כאו\"א לפי מזגו ותכונתו מצרופי אותיות הדבור, כך יעמוד לעולם נפרד בפ\"ע ואין לו התחברות עם השני, כמו שאין התחברו' לדיבור אחד אל חבירו.\n<b>וזה\"ע</b> מצות השמחה לשמח החתן כו', דהנה ידוע שהשמחה היא באה על דבר הנעלם שנתגלה מהעלמו לידי גילוי ממש דוקא כמ\"ש במ\"א<sup data-n=\"345\">6</sup>, ולכן",[["343","4","<b>כך הוא ממש ערך הבינה אל החכ' כמ\"ש במ\"א</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370016\" data-slug=\"torah-or\" data-id=\"3901370016\">תו\"א בראשית ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370289\" data-slug=\"torah-or\" data-id=\"3901370289\">בשלח סד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370308\" data-slug=\"torah-or\" data-id=\"3901370308\">יתרו סט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">ברכה צה, ב</a>. ובכ\"מ."],["344","5","<b>כמ\"ש במ\"א ע\"פ וכנפיהם פרודות</b>: ראה ד\"ה וספרתם לכם (משנת תקס\"ד) ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380348\" data-slug=\"likkutei-torah\" data-id=\"4001380348\">לקו\"ת במדבר י, א</a>. ונו\"א בסידור עם דא\"ח שז, ג ואילך. [וראה בהמ\"מ בסו\"ס הלקו\"ת שם]."],["345","6","<b>ידוע שהשמחה היא באה על דבר הנעלם שנתגלה. . כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370170\" data-slug=\"torah-or\" data-id=\"3901370170\">תו\"א מקץ לז, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370358\" data-slug=\"torah-or\" data-id=\"3901370358\">תרומה פ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380478\" data-slug=\"likkutei-torah\" data-id=\"4001380478\">לקו\"ת שלח מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381043\" data-slug=\"likkutei-torah\" data-id=\"4001381043\">שם סוכות עט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381052\" data-slug=\"likkutei-torah\" data-id=\"4001381052\">פב, א</a>. פח, ד. ברכה צד, ג. שה\"ש ב, ב. כד, ב. ובכ\"מ."]]],[2000460178,"כשרואה האדם שנמצא למטה ג\"כ בחי' כח המוליד להוליד חדשות מאין ליש שזה הכח נמשך מן אור א\"ס ב\"ה אשר הוא כל יכול לחדש חדשו' אין קץ להפעיל מאין המוחלט ליש ממש כמ\"ש והחכ' מאין תמצא וגו', ע\"כ ישמח לב האדם מזה, וזוהי המצוה לשמח החתן כו' כנ\"ל. וזהו שארז\"ל ואם משמחו זוכה לתורה שניתנה בה' קולות וכו', פי' כי התורה נמשכה ג\"כ מאין ליש ממש מהעלם לגילוי, כי אוריי' מחכ' נפקת והחכ' מאין תמצא, לכן כאשר ישמח האדם מבחי' כח המוליד מאין ליש הנמצא בהאדם שזהו המצוה לשמח החתן כו' יזכה לתורה שנמשכה ג\"כ משרש ומקור זה מאין ליש דאוריי' מחכ' נפקת והחכ' מאין תמצא כנ\"ל.\n<b>אך</b> להבין ענין ה' קולות שניתנה בהן התורה כמ\"ש ויהי קול השופר וגו', משה ידבר והאלקי' יעננו בקול וגו', ששם נא' במ\"ת ה' קולות כו', הענין הוא דהנה כתי' אז ראה ויספרה הכינה וגם חקרה ויאמר לאדם וגו', פי' שזהו ה' בחי' ומדרגות שנמשכי' בסדר ההשתלשלו' מחכ' עד הדבור, ראה הוא בחי' ומדרגת החכ' שהיא בחי' ראיי' כנודע, ויספרה הוא בחי' בינה כו' כמשנ\"ת במ\"א<sup data-n=\"346\">7</sup> ע\"ש. וכמ\"כ עד\"מ למעלה נמצאי' ה' מדרגו' המשתלשלו' מחכ' דאצי' ואילך עד מל' דאצי' היא דבר ה' ית' דהיינו מהחכ' נמשכה הבינה דאצי' שנקראת בחי' זה כמ\"ש והחכ' מאין תמצא ואי זה מקום בינה וגו', ומהבינה נמשכי' המדות ומן המדו' המחשבה ומן המח' הדבור הרי הם ה' מדרגו' המשתלשלו' מחכ' עד הדבור כנ\"ל, והן הן הה' קולות שניתנה בהן התו', פי' דאוריי' מחכ' נפקא וכאשר נצטרך להמשיכה מן החכ' למטה הוצרכה לירד ולהתמשך דרך ה' מדרגו' המשתלשלו' מחכ' ואילך כנ\"ל, והן הן הה' קולות שקול הוא ל' המשכה שנמשך בחי' התורה למטה דרך ה' בחי' ומדרגו' ההשתל' הנ\"ל.\n<b>וז\"ש</b> קול ה' על המים וגו' פי' זהו המשכה ראשונה של התו' שהוא נגד קול הראשון דמ\"ת, דהנה מים הוא בחי' חכ' שמאין תמצא כנודע ועז\"נ קול ה' על המים שהוא ההמשכה מלמעלה מן החכ' אל ים החכ' שלמעלה וז\"ש על המים, ואח\"כ נמשכה עוד למטה במורד אל המדו' דאצי', וז\"ש אח\"כ קול ה' בהדר וגו' עד סוף כל החמשה קולות הוא שיומשכו כ\"כ למטה עד סוף כל דרגין הוא בחי' דבר ה' ית' דכתי' ויאמר לאדם הן יראת ה' היא חכ' וגו' כמשנת\"ל",[["346","7","<b>ויספרה הוא בחי' בינה כו' כמשנ\"ת במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381009\" data-slug=\"likkutei-torah\" data-id=\"4001381009\">לקו\"ת האזינו עא, ג</a>. סה\"מ תקס\"ג ח\"ב ע' תשנז. וראה גם ס' מאמרי אדהאמ\"צ בראשית ע' לב. נד. תצה. שמות ח\"ב ע' שסט. שפג. ויקרא ח\"ב ע' תתכח. תתסז. במדבר ח\"ד ע' א'תנג. דברים ח\"א ע' שיט. ח\"ג ע' תתס. ח\"ד ע' א'קסז. סה\"מ תרכ\"ט ע' שכז (מלקו\"ת להאריז\"ל ר\"פ בראשית). ובכ\"מ."]]],[2000460179,"שהיא מדרגה החמישי' סופא דכל דרגין בחי' יראת ה', אך כ\"ז בס\"י<sup data-n=\"347\">8</sup> שנעוץ תחלתן בסופן וסוב\"ת לכך כתי' הן יראת ה' היא חכ' שבסופא דכל דרגין הוא היראת ה' שהיא מדרגה החמישי' כנ\"ל נעוץ התחילה היא החכ' הראשית לכל, ונעוץ סופן בתחלתן שבחכ' ריש כל דרגין נעוץ היראה שהיא סופא דכ\"ד וכמארז\"ל אם אין יראה אין חכ' ואם אין חכ' אין יראה וכנ\"ל, וזהו כוונת רז\"ל זוכה לתורה שניתנה בה' קולות כו' ע\"י שמשמח את החתן דייקא במצוה זו דכולא חדא מילתא היא (וכאשר אינו משמחו עובר בה' קולות) שגם בחתן ימצא ה' קולות כו' כנ\"ל.\n<b>והטעם</b><sup data-n=\"348\">9</sup> לזה שהתורה ניתנה בקולות ורעש גדול דוקא, הוא שע\"י הקול והרעש יתמשך עיקר שפע החכ' למטה שהקול והרעש הוא הממשיכה דייקא, משא\"כ בלא\"ה לא יתמשך החכ' למטה כ\"א יהיו נשארי' למעלה ולכן עיקר מצות לימוד התורה לשמה (לשם ה\"א דהיינו המשכת התורה דרך ה' קולות הנ\"ל) הוא בקול דוקא כמ\"ש בגמ' בתלמיד א' שגרס תלמודו בחשאי ושכח תלמודו כו' ע\"ש, והיינו מפני שקריאת והמשכת התורה הנמשך מח\"ע הוא ע\"י הקול דוקא, כמ\"ש קרוב ה' לכל קוראיו לכל אשר יקראוהו באמת, ואין אמת אלא תורה שממשיכי' אותו אל האמת היא התורה, וז\"ש באמת בתוך האמת כו', שכ\"ז הקריאה וההמשכה הוא ע\"י הקול דוקא, ולכן אותו תלמיד שגרס בחשאי שכח תלמודו כנודע שהשכחה היא הפך החכ'<sup data-n=\"349\">10</sup> כמ\"ש לא תשכח זהו בחי' החכ' והזכרון, וההיפך לזה הוא תשכח שהשכחה היא מאחוריי' של החכ' כנודע, ולכן כאשר למד בחשאי שלא המשיכה למטה שכח תלמודו, אך אעפ\"כ מצוה לעסוק בתורה בעיון השכלי אף בלא קול ודבור ג\"כ, שזהו מ\"ש קול ה' על המים דהיינו שממשיך את אור א\"ס ב\"ה לתוך החכ' של התורה המלובשת בשכלו שמקשר חב\"ד שלו בחב\"ד של אור א\"ס ב\"ה כמ\"ש בלק\"א<sup data-n=\"350\">11</sup>, וז\"ש על המים לתוך עיון השכלי כנ\"ל.",[["347","8","<b>אך כ\"ז בס\"י</b>: כ\"ה בהכתבי-יד. ובהמאמר בתורת שמואל דרושי חתונה שם (ע' מ) הלשון מתוקן: זהו מצד שנת' בס' יצירה כו'."],["348","9","<b>שיש מצות שהם בבחי' חוקים. . ג\"כ למעלה מן הטעם</b>: בד\"ה זה בסה\"מ תרכ\"ט תוקן בגוכי\"ק: והיינו כמשנ\"ת בד\"ה זאת חוקת (סה\"מ תרכ\"ט שם ע' רנב-ג) שהמצות הם חוקים בלא הבנת טעם למה ירצה כך וכך דוקא שלכן נקראו כל המצות בשם רצון העליון להיותם מבחי' רצונו העליון, שהרצון הוא למעלה מן הטעם המושג כמשנ\"ת שם באריכות, ומפני זה במצוה זו דפרה אדומה נאמר לשון חוקה מפני כי היא נגד השכל לגמרי שהרי היא מטהרת את הטמאים ומטמאת את הטהורים שזהו נגד השכל ממש, וע\"ז אמר שלמה אמרתי אחכמה והיא רחוקה ממני, לכן נאמר לשון חוקה שזהו חוק בלי טעם כו'."],["349","10","<b>כנודע שהשכחה הוא היפך החכמה</b>: ראה תו\"א תצוה פה, ב. קיא, א. סה\"מ תקס\"ב ח\"א ע' קעג. דרמ\"צ להצ\"צ צט, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ חתונה שם ע' תפד. ועוד."],["350","11","<b>שמקשר חב\"ד שלו בחב\"ד של אוא\"ס ב\"ה כמ\"ש בלק\"א</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>."]]],[2000460180,"<h3>וידבר כו' זאת חקת כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תשא פ' פרה, ט\"ל).</b>\nחקת ג' פי'\nתשא, פ' פרה\n<b>וידבר</b> ה' אל משה לאמר, זאת חקת התורה<sup data-n=\"351\">1</sup> אשר צוה ה' ויקחו אליך פרה אדומה כו'. הנה מה שיש לדקדק בפסוק זה למה נאמר ב' פעמים הוי', וידבר הוי', ציוה הוי'<sup data-n=\"352\">2</sup>, והל\"ל וידבר ה' אל משה לאמר זאת חקת התורה ויקחו אליך כו'. הנה פי' חוקת יש בו ג' פירושי'<sup data-n=\"353\">3</sup>, הא' ל' חוק ומשפט ע\"ד שאמר הכתוב מגיד דבריו ליעקב חוקיו ומשפטיו לישראל, שיש מצות שהם בבחי' חוקי' ויש מצות שהם משפטי', כמו דיני ממונות הרי הם ע\"פ הטעם והשכל, אבל יש כמה מצות שהם שלא ע\"פ הטעם כלל, וזהו הנק' חוקה שהם חוק לבד שלמעלה מן הטעם, ומכללם גם פרה אדומה שהיא ג\"כ למעלה מן הטעם. הב' ל' חקיקה כמשרז\"ל במד\"ר חוקה חקקתי גזירה גזרתי, חוקות שבהם חקקתי שמים וארץ. הג' ל' הטריפני לחם חוקי, שהוא בחי' חוק שלא ישנה את תפקידו וכמו כי חק לכהנים מאת פרעה ואכלו את חוקם כו'. וכל הג' פירושי' יש בבחי' פרה אדומה.",[["351","1","<b>וידבר ה'. . זאת חקת התורה</b>: המאמר מיוסד על ד\"ה במ\"א בהביאור ע\"פ וירא ישראל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830027\" data-slug=\"or-hatorah-hb\" data-id=\"8158830027\">אוה\"ת חקת</a> בהוספות (הוצאת תשנ\"ח) ע' 27 ואילך. חלק מהמאמר (מפיסקא: ולהבין ענין הפרה, עד פיסקא: ומעתה יובן ענין פרה) מיוסד על ד\"ה וירא ישראל משנת תקס\"ד נדפס בתוס' הגהות באוה\"ת בשלח ע' תלב ואילך. תנב ואילך. תסא ואילך. וחלקו נמצא בד\"ה לה\"ע תרומת הדשן בסידור עם דא\"ח ל, סע\"ג ואילך. ובארוכה בדרך חיים נב, א ואילך.\nהמאמר נמצא בשינוי ההתחלה [ועוד איזה שינויים שהובאו לקמן] בד\"ה זה בסה\"מ תרכ\"ט ע' רנח ואילך. ובשינויים ובתוס' הגהות בד\"ה זה בסה\"מ תרס\"ה ע' רכד ואילך [שם חסר המשך המאמר מפיסקא: ועוד זאת הי' העבודה, ואילך]. ובד\"ה זה תשי\"א.\nלכללות המאמר ראה ד\"ה וידבר גו' זאת חקת ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380540\" data-slug=\"likkutei-torah\" data-id=\"4001380540\">לקו\"ת חקת נו, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">נז, ג</a> ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב ואילך. תרפ ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830001\" data-slug=\"or-hatorah-hb\" data-id=\"8158830001\">אוה\"ת חקת ע' תשנט</a> ואילך. תשס. תשסא ואילך. תשסו ואילך. תשסח ואילך. שם בהוספות (הוצאת תשנ\"ח) ע' 1 ואילך [הוא המאמר דתקס\"ה שם בתוס' הגהות מחסיד א']. ע' 11. וע' 12 ואילך. ס\"ע 22 ואילך. סה\"מ תרכ\"ט ע' קא ואילך.\nראה גם לקמן מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["352","2","<b>בפסוק זה למה נאמר ב' פעמים הוי' וידבר הוי' ציוה הוי'</b>: עד\"ז מובא אודות פסוק זה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">לקו\"ת חקת שם נז, ג</a>: שנמצא שם הוי' ב' פעמים בפסוק אחד כו' אך כאן אע\"פ שאינן סמוכין רק שהם בפסוק אחד. ובד\"ה לה\"ע פרה אדומה בסה\"מ תשמ\"ה ע' 134 מעיר על ל' הלקו\"ת שם: דלכאורה ב' שמות אלו אינם בפסוק אחד. ואכ\"מ. ע\"כ. ובד\"ה זאת חקת בסה\"מ תשל\"ה ע' 338 מעיר (על מ\"ש בלקו\"ת שם ”בפסוק אחד\"): וצ\"ע אם הכוונה לענין א' (היינו ב' שמות הוי' שנאמרו בענין אחד), או דהכוונה לפסוק אחד והמסורת שלהם היתה שונה מזו שלנו. ע\"כ."],["353","3","<b>פי' חוקת יש בו ג' פירושים</b>: ראה עטרת ראש נז, סע\"ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830038\" data-slug=\"or-hatorah-hb\" data-id=\"8158830038\">אוה\"ת חקת ע' תשסו</a> ואילך. שם בהוספות (הוצאת תשנ\"ח) ע' 38. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380938\" data-slug=\"likkutei-torah\" data-id=\"4001380938\">לקו\"ת</a> דרושים לר\"ה נד, ד. אוה\"ת תצא ע' תתקס-סא."]]],[2000460181,"<b>ולהבין</b> כ\"ז הנה כל התורה<sup data-n=\"354\">4</sup> היא בחי' תושב\"כ, פי' תורה שבכתב כי התורה ניתנה באש שחורה ע\"ג אש לבנה שהוא כדמיון הכתב בדיו על גבי הקלף שהם משני דברים נפרדים ומחברי' אותם יחד בתמונת האותיות כו', אבל אותיות החקיקה הם מיני' ובי'<sup data-n=\"355\">5</sup> שאינם מדבר נפרד כלל כ\"א מיני' ובי'. והנה באברהם ארז\"ל קיים אברהם אבינו כל התורה כולה עד שלא ניתנה, ולכאו' יפלא איך קיים כל התורה הלא יש כמה מצות התלויות בארץ, והרבה מצות שתלוים ביצ\"מ כמו תפילין, ואיך קיים אותם. אך הענין הוא בהיות ידוע כי בד\"כ התורה היא בחי' רצוא ושוב, ואברהם קיים כל התורה ברצוא ושוב<sup data-n=\"356\">6</sup>, שזהו שנא' בו הלוך ונסוע הנגבה, שזהו כמו והחיות רצוא ושוב, שהי' תמיד בבחי' מרכבה וביטול ליכלל וליבטל אליו ית' שזהו כמו רצוא ושוב דתורה שנא' מימינו אש דת, אש הוא בחי' רצוא ומים הוא בחי' שוב<sup data-n=\"357\">7</sup>, ואברהם קיים זאת ברצוא ושוב עצמו, לכן קיים אברהם כו'.\n<b>וביאור</b> ענין רצוא ושוב<sup data-n=\"358\">8</sup>, הנה הרצוא הוא ברשפי אש ליכלל וליבטל אליו ית' שלא ירצה בשום דבר זולתו ית', שזהו מ\"ש ראה נתתי לפניך את החיים ואת הטוב ואת המות ואת הרע ובחרת בחיים, פי' מות ורע הוא בחי' תענוגי עוה\"ז השפל והגשמי, וחיים וטוב<sup data-n=\"359\">9</sup> הנה טוב הוא בחי' ההשפעה שבג\"ע, וחיים הוא מקור השפעת תענוגי' רוחני' שבג\"ע<sup data-n=\"360\">10</sup>, לכן ובחרת בחיים היינו בבחי' כי עמך מקור חיים כו', וזהו בחי' הרצוא. ובחי' השוב הוא בחי' עול מצות, וזהו מ\"ש ואהבת כו' בכל לבבך דהיינו בחי' אהבה שבלב שהיא בחי' רצוא שתהי' בכל לבבך דהיינו בחי' רצוא שלם, ואח\"כ אם רץ לבך שוב לאחד<sup data-n=\"361\">11</sup> דהיינו בחי' בכל נפשך כפשוטו, היינו לקשר ג' לבושי הנפש בחי' מחדו\"מ, שהמחשבה שלו יהי' מקושר במחשבת התורה, ודבורו בדבור התורה, והמעשה במעשה המצות כו', שזהו בבחי' השוב כו'. והנה אברהם שקיים כל",[["354","4","<b>ולהבין כ\"ז הנה כל התורה</b>: בהבא לקמן (עד פיסקא: ולהבין ענין הפרה) ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380540\" data-slug=\"likkutei-torah\" data-id=\"4001380540\">לקו\"ת חקת שם נו, א</a>-ב [ובדרושי זאת חקת שנסמנו לעיל בתחילת המאמר]."],["355","5","<b>הכתב בדיו על הקלף. . אותיות החקיקה הם מיני' ובי'</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380540\" data-slug=\"likkutei-torah\" data-id=\"4001380540\">לקו\"ת חקת שם נו, א</a>. נט, ג-ד. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">לקו\"ת בחקותי מה, א</a>. מה, ד ואילך. ובכ\"מ."],["356","6","<b>ארז\"ל קיים אברהם אבינו כל התורה. . ברצוא ושוב</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370327\" data-slug=\"torah-or\" data-id=\"3901370327\">תו\"א יתרו עג, ד</a>. מג\"א צו, ג. ועוד. לקמן ד\"ה ששים המה מלכות. וש\"נ."],["357","7","<b>מימינו אש דת אש הוא בחי' רצוא ומים הוא בחי' שוב</b>: ראה לקמן בהנחת כ\"ק אדמו\"ר מוהרש\"ב מהמאמר: ומימינו הוא מים שוב. ועד\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380541\" data-slug=\"likkutei-torah\" data-id=\"4001380541\">לקו\"ת חקת נו, ב</a>: ימינו הוא בחי' מים. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381201\" data-slug=\"likkutei-torah\" data-id=\"4001381201\">לקו\"ת שה\"ש יח, א</a>."],["358","8","<b>וביאור ענין רצוא ושוב</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ו ע' קכה ואילך. תרכ\"ט ע' רג ואילך. ועוד."],["359","9","<b>שזהו מ\"ש ראה נתתי לפניך. . פי' מות ורע. . תענוגי עוה\"ז. . וחיים וטוב</b>: ראה בכ\"ז תו\"א תשא פה, סע\"ג-ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380759\" data-slug=\"likkutei-torah\" data-id=\"4001380759\">לקו\"ת ואתחנן יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">תצא לה, סע\"ג</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380905\" data-slug=\"likkutei-torah\" data-id=\"4001380905\">ד. נצבים מו, רע\"ג</a>. האזינו עב, ב. ובכ\"מ."],["360","10","<b>טוב הוא בחי' ההשפעה שבג\"ע וחיים הוא מקור. . תענוגים רוחני' שבג\"ע</b>: ראה לקו\"ת ואתחנן שם יא, ב: בחי' הטוב הוא למעלה מבחי' החיים. עיי\"ש."],["361","11","<b>אם רץ לבך שוב לאחד</b>: ראה אוה\"ת יתרו ע' תתקעה. וע' תתקפא. סה\"מ תרנ\"ט ע' ריא (ובהוצאת תנש\"א ואילך בע' ריג). וש\"נ."]]],[2000460182,"התורה כולה היינו שלפי עוצם עבודתו בא לבחי' רצו\"ש, אבל אנו א\"א לנו להגיע לבחי' רצו\"ש מצד עבודתינו, וזהו\"ע התורה ומצות שניתן לנו, שלפי שהם בחי' רצו\"ש כנ\"ל בפי' מימינו אש דת וכמו\"כ מ\"ע ומל\"ת הם בבחי' רצו\"ש, לכן הם הנותנים כח ועוז לבוא לבחי' הרצו\"ש כו'.\n<b>וזהו</b> בד\"כ כל התורה, וענין פרה אדומה היא ג\"כ בחי' רצו\"ש, שאפר הפרה הוא בחי' רצוא והמים חיים הם בחי' השוב, רק שהרצו\"ש דפרה הוא למעלה מבחי' רצו\"ש דכל התורה<sup data-n=\"362\">12</sup>, שזהו כמו ההפרש בין בכל לבבך לבכל מאדך, שבכל לבבך הגם שהוא בחי' רצוא ליכלל וליבטל אליו ית' אך הוא לא יותר ממה שהלב מכיל רק בכלי הלב ולא יותר, אבל בחי' בכל מאדך הוא בבחי' בלי גבול ומדה ושיעור, וזהו בחי' הרצוא דפרה שהיא בלי גבול, והיינו שעי\"ז ממשיכי' בחי' והחיות רצוא ושוב פי' והחיות היינו חיות האלקי<sup data-n=\"363\">13</sup> שמאיר מאתו ית' להחיות כל הנבראי' והנאצלי' כו', וההתבוננות לבוא לבחי' רצוא זו דפרה הוא ג\"כ גבוה יותר, כי ההתבוננו' הנ\"ל דרצוא שבכל התורה הוא מצד ובחרת בחיים והיינו כמ\"ש לאהבה את הוי' כי הוא חייך, אבל בחי' רצוא זו דפרה היינו להיות ועמך לא חפצתי פי' עמך היינו בחי' כי עמך מקור חיים מאחר שהוא רק עמך לא חפצתי, כ\"א שירצה ליכלל וליבטל בעצמותו ית' כו', ולכן לפי ערך הרצוא דפרה השוב הוא בחי' מים חיים שהם גבוהי' במעלה יותר מבחי' השוב שלאחר הרצוא דכל התורה כו'.\n<b>ולהבין</b> ענין הפרה, הנה אמרו בזהר פרה דקבילת משמאלא<sup data-n=\"364\">14</sup>, ומאן איהי לשמאלא פני שור כמד\"א ופני שור מהשמאל. ולכאו' צ\"ל ההפרש שבין פרה לשאר כל הקרבנות, שכל הקרבנות היו בשמאל דוקא להעלות ולתקן קו השמאל, כי שרש יניקת החיצוני' הוא מקו השמאל ולכן רישא דעשו בעטפוי דיצחק להיות כי יצחק הי' מבחי' הגבו' לכן מצד ריבוי הגבורות יכול להיות יניקה לחיצוני' כנודע, וזה הי' ענין הקרבנות בשמאל לתקן קו השמאל<sup data-n=\"365\">15</sup>, ולכן ארז\"ל העולה קדש קדשים שחיטתה",[["362","12","<b>שהרצו\"ש דפרה הוא למעלה מבחי' רצו\"ש דכל התורה</b>: בד\"ה זה תרס\"ה ותשי\"א שם נת' בארוכה שזהו\"ע ההפרש בין רצו\"ש דממכ\"ע ורצו\"ש דסוכ\"ע. עיי\"ש."],["363","13","<b>והחיות רצוא ושוב פי' והחיות היינו חיות האלקי</b>: ראה ד\"ה זה תרס\"ה: והחיות רצוא ושוב ופי' הפשוט דקאי על חיות הקודש שהם ברצוא ושוב, אמנם יש פי' דהחיות קאי על האור והחיות האלקי שהוא בבחי' רצוא ושוב. וראה בכ\"ז אוה\"ת תרומה ס\"ע א'שנז [ושם: ”ויש בזה ב' פירושים ושניהם אמת\" ומתווך בין ב' הפירושים עיי\"ש]. סה\"מ תרכ\"ו שם ע' קכה. תרכ\"ט שם ע' רג. תש\"ד ע' 251. ועוד."],["364","14","<b>ולהבין ענין הפרה. . פרה דקבילת משמאלא</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חקת נו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380550\" data-slug=\"likkutei-torah\" data-id=\"4001380550\">נח, ג</a>. ביאוה\"ז לאדהאמ\"צ צו, ד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830084\" data-slug=\"or-hatorah-hb\" data-id=\"8158830084\">אוה\"ת חקת ס\"ע תשע</a> ואילך. תשפ ואילך. סה\"מ תרכ\"ט ע' קא ואילך."],["365","15","<b>וזה הי' ענין הקרבנות בשמאל לתקן קו השמאל</b>: בהבא לקמן (עד פיסקא: ומעתה יובן ענין פרה אדומה) ראה סידור עם דא\"ח שם ל, סע\"ג ואילך. דרך חיים שם נב, א ואילך. אוה\"ת בשלח שם ע' תלב ואילך. תנב ואילך. תסא ואילך. צו (כרך ג) ע' תתא. סה\"מ תרכ\"ז ע' רמח ואילך. תרע\"ח ע' צב ואילך. תרצ\"ט ע' 119 ואילך. תש\"ז ע' 201 ואילך."]]],[2000460183,"בצפון דייקא, משא\"כ שלמים שהם קדשים קלים שחיטתן בכל מקום בעזרה, אבל קדשי קדשי' שחיטתן בצפון דוקא מטעם הנ\"ל<sup data-n=\"366\">16</sup>.\n<b>וזהו</b> שארז\"ל על ג' דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח, שתורה הוא בחי' קו האמצעי וגמ\"ח בחי' קו הימין ועבודה הוא בחי' עבודת הקרבנות הוא בחי' תיקון קו השמאל כו'. ולהבין ענין העבודה, צ\"ל תחלה [ענין] התורה שהיא קו האמצעי, בהיות ידוע שהתורה נק' בשם מצוה, ובמצוה יש ב' פירושי', הא' ל' ציווי, הב' ל' צוותא וחיבור<sup data-n=\"367\">17</sup>. ולהבין מהו ענין צוותא וחיבור, כי הנה כתי' רבות עשית אתה ה' אלקי<sup data-n=\"368\">18</sup> נפלאותיך ומחשבותיך אלינו אין ערוך אליך, פי' רבות עשית קאי על ריבוי התהוות הנבראי' שזה נמשך מצד בחי' נפלאותיך היינו בחי' ל\"ב נתיבות חכמה כמ\"ש בס\"י בשלשים ושתים נתיבות פליאות חכ' חקק וברא י\"ה ה' צבאות, פי' פליאות שהיא בחי' חכ' נפלאה, ומצד כי שרש התהוותם הוא מל\"ב נתיבות חכמה לכן יש בהנפעל חכ' נפלאה ועמוקה, שענין הילוך הגלגלי' יש בו חכ' נפלאה כו', וענין ל\"ב נתיבות חכמה דוקא נודע כי הם כנגד ך\"ב אותיות ועשרה מאמרות. והנה מה שהם נקראי' נפלאות זהו רק אלינו פי' לגבי השגת הנבראי', אבל לגבי' ית' אין ערוך אליך שאין ערוך כלל בחי' הנפלאות<sup data-n=\"369\">19</sup>, ולכן כדי שיהי' גילוי אלקותו ית' בעולם זהו ענין התומ\"צ כי בהם וע\"י נמשך גילוי אלקותו ית' בעולם. וזהו משארז\"ל תנאי הי' לו להקב\"ה עם מע\"ב אם יקיימו ישראל תורתי מוטב וא\"ל יחזור את העולם לתהו, והיינו כנ\"ל שע\"י התורה שישראל מקיימין עי\"ז ממשיכי' גילוי אלקותו ית' בעולם כו'. וזהו כמ\"ש בזהר ובמד\"ר ע\"פ עשרה עשרה הכף שעשה\"ד מכוון כנגד עשרה מאמרות<sup data-n=\"370\">20</sup> כו', לפי שע\"י עשה\"ד שהם כללות תרי\"ג מצות כו' ע\"י ממשיכי' בחי' עשרה מאמרות כו' כמ\"ש במ\"א בד\"ה וירא ישראל את",[["366","16","<b>שחיטתן בצפון דוקא מטעם הנ\"ל</b>: במאמר כאן לא מובא סיום השאלה דלעיל, ובד\"ה זה תרס\"ה מסיים כאן: וא\"כ מהו ההפרש בין כל הקרבנות לפרה אדומה. אך הענין הוא דהנה אמרז\"ל על ג' דברים. . . [כדלקמן בפנים]."],["367","17","<b>ובמצוה יש ב' פירושי' הא' ל' ציווי הב' ל' צוותא וחיבור</b>: ראה אוה\"ת בשלח שם [ובדרושים שנסמנו לעיל הערה ד\"ה: וזה הי' ענין הקרבנות]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">לקו\"ת חקת שם נז, ג</a>. פינחס עו, א. מסעי צב, ג. סה\"מ תרכ\"ט ע' לח. וע' שז. לקמן ד\"ה הללוי' גו' מן השמים. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071030\" data-slug=\"likkutei-sichot\" data-id=\"1300071030\">לקו\"ש ח\"ז ע' 30</a> ואילך [שם נת' הקשר בין ב' הפירושים]."],["368","18","<b>הנה כתי' רבות עשית אתה ה' אלקי</b>: בהבא לקמן ראה [נוסף למקומות שנסמנו לעיל הערה ד\"ה: וזה הי' ענין הקרבנות] <a class=\"ft-cite\" href=\"#/read/torah-or/3901370147\" data-slug=\"torah-or\" data-id=\"3901370147\">תו\"א מקץ לא, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380127\" data-slug=\"likkutei-torah\" data-id=\"4001380127\">לקו\"ת צו יב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381289\" data-slug=\"likkutei-torah\" data-id=\"4001381289\">שה\"ש מ, ב</a> ואילך. סה\"מ תרכ\"ז ע' רמח. ובכ\"מ."],["369","19","<b>שאין ערוך כלל בחי' הנפלאות</b>: בסה\"מ תרכ\"ט נוסף כאן: (וכמו שאין ערוך העולמות לגבי' כמו\"כ בחי' הנפלאות מקור ושורש כל העולמות ג\"כ אין ערוך כו' וכמ\"ש כולם בחכ' עשית כו' כמ\"ש במ\"א)."],["370","20","<b>בזהר ובמדרש ע\"פ עשרה עשרה הכף שעשה\"ד מכוון כנגד עשרה מאמרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">לקו\"ת חקת שם נז, סע\"ג</a>-ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830082\" data-slug=\"or-hatorah-hb\" data-id=\"8158830082\">אוה\"ת תשא ע' א'תתנא</a>. חקת שם ע' תשסח ואילך. סה\"מ תרכ\"ז ע' רמח. תרפ\"ט ס\"ע 74 ואילך. ובכ\"מ."]]],[2000460184,"היד<sup data-n=\"371\">21</sup> הגדולה כו'. וזהו ענין התורה בחי' קו האמצעי שע\"י נמשך גילוי אלקות בעולמות הנבראי' שהם בחי' קדושה.\n<b>וענין</b> עליית קו השמאל שנפל זהו ענין העבודה הוא בחי' קו השמאל, ויובן בהקדם ענין הקרבת הבהמה על המזבח על חטא האדם, הלא האדם חטא הבהמה לא חטא, ומהו ענין הקרבתה ע\"ג המזבח, וגם איך מתתקן חטא האדם ע\"י הקרבת הבהמה. הנה ידוע כי שרש הבהמה גבוה מאד מבחי' בהמה רבה ואח\"כ נפלה בבחי' בהמה דאכלה אלף טורין<sup data-n=\"372\">22</sup> (ע' בזהר בראשית די\"ח ע\"ב ובמק\"מ שם בד\"ה על אלף טורין), ואח\"כ נפלה עוד עד שנתהוה בהמה הגשמיות שלנו, וע\"י הקרבתה מתעלית לשרשה, ולכן הוא מתקן את נפש האדם כמ\"ש במ\"א<sup data-n=\"373\">23</sup>. והנה עכשיו תפלה כנגד תמידין תקנו, שע\"י התפלה הוא בירור הנה\"ב ששרשו ג\"כ כנ\"ל, כי זהו שאמר הכתוב הגו סיגים מכסף ויצא לצורף כלי, וכתי' כמצרף לכסף וכור לזהב איש לפי מהללו, ופי' הגו סיגים מכסף כמו שכדי שיוכל הצורף לעשות כלי נאה צריך לברר תחלה הסיגים מהכסף ואז אח\"כ יעשנה כלי, כי קודם הבירור הכסף אינו בתכלית העילוי וכמו\"כ הפסולת אינם פסולת גמור עדיין, כך כדי שיהי' האדם כלי לקבל בחי' הקדושה היינו גילוי אלקותו ית', צ\"ל תחלה בירור הפסולת, וזהו כמצרף לכסף וכור לזהב איש לפי מהללו, לפ\"ע ההילול והשבח שלו בתפלה בעבודת בוראו כן הוא ערך בירור הפסולת שלו. ובזה יובן מה שאומרים סלח לנו כי חטאנו אחר העבודה<sup data-n=\"374\">24</sup> בהתבוננו' בק\"ש, שלכאו' הי' צ\"ל סלח לנו קודם התפלה, אך הענין הוא דהנה קודם התפלה דרך איש ישר בעיניו ואם אינו עושה עבירות ומקיים מצות ולומד תורה הרי הוא בעיניו כזכאי, אבל כשמתבונן בגדולת הבורא ית' בק\"ש באחד איך דכולא קמי' כלא חשיב, אזי הוא מבין שנמצא בו פסולת ג\"כ, ואז מבקש סליחה ומחילה. וזהו בד\"כ ענין הבירור דתפלה שמברר את הנה\"ב ומעלה אותה.\n<b>ועוד</b> זאת הי' העבודה בקרבנות שלאחר גמר הקרבנות הנה האפר שהי' נשאר היו תורמין תרומת הדשן<sup data-n=\"375\">25</sup>, ולכאו' צ\"ל מ\"ש בתרומת הדשן ולבש הכהן בגדי בד",[["371","21","<b>כמ\"ש במ\"א בד\"ה וירא ישראל את היד</b>: סה\"מ תרכ\"ז שם ע' רמח-ט. וראה גם אוה\"ת בשלח שם ע' תלג. וע' תסא. [ובדרושים שנסמנו לעיל הערה ד\"ה: וזה הי' ענין הקרבנות]."],["372","22","<b>בהמה דאכלה אלף טורין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370216\" data-slug=\"torah-or\" data-id=\"3901370216\">תו\"א ויחי מז, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380154\" data-slug=\"likkutei-torah\" data-id=\"4001380154\">לקו\"ת שמיני יט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380230\" data-slug=\"likkutei-torah\" data-id=\"4001380230\">אמור לו, א</a>. אוה\"ת ויקרא (כרך ג) ע' תתע. ועוד.\nבד\"ה זה בסה\"מ תרכ\"ט נוסף כאן הגה\"ה בגוכי\"ק: בבחי' בהמה רבה דאכלה אלף טורין, וכמ\"ש במאו\"א אות ב' ס\"ז שבהמות בהררי אלף זהו נוק' דבריאה דתמן אל שדי גימ' אלף, עכ\"ל, ויש בהמה רבה שלפני האצי', ושורש הבהמה הוא מבחי' בהמה רבה ונפלה בבחי' בהמות בהררי אלף הוא בחי' מל' דבריאה."],["373","23","<b>וע\"י הקרבתה מתעלית לשרשה. . כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381243\" data-slug=\"likkutei-torah\" data-id=\"4001381243\">לקו\"ת שה\"ש כח, ג</a>. סה\"מ תרכ\"ז ע' קלד ואילך. תרכ\"ט ע' סט ואילך. וע' קי ואילך. ובכ\"מ."],["374","24","<b>ובזה יובן מה שאומרים סלח לנו. . אחר העבודה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380431\" data-slug=\"likkutei-torah\" data-id=\"4001380431\">לקו\"ת בהעלותך ל, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380858\" data-slug=\"likkutei-torah\" data-id=\"4001380858\">תצא לה, סע\"ב</a>. דרושים לש\"ש סה, ג. סה\"מ תרכ\"ז ס\"ע רנ-נא. וע' תלג. [ובדרושים שנסמנו לעיל הערה ד\"ה: וזה הי' ענין הקרבנות]."],["375","25","<b>ועוד זאת הי' העבודה. . תרומת הדשן</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200089\" data-slug=\"or-hatorah-hb\" data-id=\"8159200089\">אוה\"ת צו (כרך ג) ע' תתא</a>-ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830027\" data-slug=\"or-hatorah-hb\" data-id=\"8158830027\">אוה\"ת חקת שם</a> בהוספות ע' 27. [ובדרושים שנסמנו לעיל הערה ד\"ה: וזה הי' ענין הקרבנות]."]]],[2000460185,"ומכנסי בד שהם לבושי' גבוהי'<sup data-n=\"376\">26</sup> למה היו צריכי' לתרומת הדשן ללבושי' גבוהי' כאלו דוקא. אך הענין הוא כי האפר שהי' נשאר הנה בעבודה הו\"ע המרירות שנעשה מחמת התבוננות הנ\"ל בק\"ש ותפלה, והנה במרירות יש ב' בחי', הא' הוא שפלות, והב' הוא בחי' עצבות<sup data-n=\"377\">27</sup>, והנה השפלות הוא כלי לגילוי אוא\"ס ב\"ה כמ\"ש מרום וקדוש אשכון את דכא ושפל רוח דוקא, וכמשארז\"ל גדולה ענוה יותר מכולם, אבל בחי' העצבות הנה היא אסקופה הנדרסת לכל העוונות מקור כל העוונות, לזה הו\"ע תרומת הדשן לברר הפסולת לגמרי. וזהו שבתרומת הדשן ארז\"ל שהטוב שבהאפר הי' נבלע במקומו והפסולת היו שופכין אל שפך הדשן, וכמו\"כ בעבודה ללקוט השפלות מתוך העצבות, והעצבות יודחה לגמרי כו'. וזהו בד\"כ ענין עבודה בירור קו השמאל בשלימות. וזהו על ג' דברים העולם עומד על התו' ועל העבודה ועל גמ\"ח, שג' קוין אלו הם נגד ג' קוין דבחי' אדם כו', וע\"י התורה נמשך גילוי אלקותו ית' כמ\"ש ונהר יוצא מעדן כו', וגמ\"ח הוא מלמעלמ\"ט, ועבודה היא מלמטלמ\"ע.\n<b>ומעתה</b> יובן ענין פרה אדומה<sup data-n=\"378\">28</sup> שהי' בה ג\"כ העבודה באפר הפרה, רק שבקרבנות הי' העיקר בחי' עשן המערכה, וגם בתרומת הדשן הי' ג\"כ עבודה, אבל בפרה נהפוך הוא שהעיקר הוא בחי' האפר.\n<b>ולהבין</b> זה צ\"ל ענין עשן המערכה הנה כתי' והר סיני עשן כולו פי' עש\"ן ר\"ת עולם שנה נפש<sup data-n=\"379\">29</sup>, עולם הוא בחי' מקום, ושנה הוא בחי' זמן, ונפש הוא",[["376","26","<b>ולבש הכהן בגדי בד ומכנסי בד שהם לבושי' גבוהי'</b>: ראה זח\"ב רלט, א [הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830027\" data-slug=\"or-hatorah-hb\" data-id=\"8158830027\">אוה\"ת צו ע' יז</a>]: ולבש הכהן מדו בד אלין לבושין מייחדין לקדושה, בד יחודאי מייחדי לקדושה וכתי' בגדי קדש הם ורחץ במים את בשרו ולבשם. ע\"כ. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950453\" data-slug=\"or-hatorah-hb\" data-id=\"8315950453\">אוה\"ת</a> חקת שם בהוספות ע' 27 מציין ע\"ז להרקנטי פ' צו (ע\"פ ולבש הכהן מדו בד) הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830020\" data-slug=\"or-hatorah-hb\" data-id=\"8158830020\">אוה\"ת</a> בשלח שם ע' תנג, וז\"ל הרקנטי שם: תרומת הדשן קודמת לכל עבודות שביום, וענינה וסודה להעביר רוח הטומאה הנשארת מעיכול איברים ופדרים כו' ע\"כ לא תעשה רק בבגדי לבן כי בחסד יכופר עוון. ע\"כ."],["377","27","<b><a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">במרירות יש ב</a>' בחי'. . שפלות. . עצבות</b>: ראה תניא פל\"א (לט, ב)."],["378","28","<b>ומעתה יובן ענין פרה אדומה</b>: בהבא לקמן (בפיסקא זו ושלאחרי') ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830027\" data-slug=\"or-hatorah-hb\" data-id=\"8158830027\">אוה\"ת חקת</a> בהוספות שם ע' 27 ואילך."],["379","29","<b>והר סיני עשן כולו פי' עש\"ן ר\"ת עולם שנה נפש</b>: ראה בכ\"ז מאמרי אדה\"ז על פרשיות התורה ח\"א ע' א. וע' שז. מאמרי אדהאמ\"צ בראשית ע' נו ואילך. במדבר ח\"ב ע' שלב ואילך. שלז ואילך. אוה\"ת יתרו ע' תתטז. וע' תתכג. סה\"מ תרכ\"ז ע' צט-ק. וש\"נ. שם ע' קלח. תרכ\"ח ע' קמד. תרל\"ח ע' יט-כ. וע' מג. [ובהנסמן בהע' שלאח\"ז]."]]],[2000460186,"בחי' החיות המחי' מקום וזמן<sup data-n=\"380\">30</sup> כו', וע\"ז נא' ויעל עשנו שבחי' עשן זה נתעלה בבחי' רצוא כו'. אך הנה נא' והרשעה כולה בעשן תכלה, וכתי' כי רשעים יאבדו כו' כלו בעשן כלו, שלכאו' צ\"ל איך שייך לומר על רשעי' שיתעלו בעשן הוא בחי' עולם שנה נפש כנ\"ל. אך הענין הוא, דהנה באמת בחי' עשן המערכה מתעלה כנ\"ל, אבל עשן דפרה הוא ע\"ד והרשעה בעשן תכלה, כי הנה נודע שבחטא ועון יש גוף החטא במח' או בדבור או במעשה, ויש בחי' הדקות והכחות רוחני' שיש בהחטא ועון דהיינו ההרהור והדבור בעניני החטא כו', הנה נודע כי הדקות והכחות רוחני' א\"א להם להתעלות כ\"א רק החטא והעון גופא יוכל להתעלות<sup data-n=\"381\">31</sup>, ואדרבה יוכל לבא לבחי' בכל מאדך כמשארז\"ל טוב מאד זה יצה\"ר. וזהו ענין העשן דפרה שע\"י העשן יוצא דקות החטא והאפר הנשאר הוא בירור החטא עצמו, והרי הוא כמו החטא לאחר הבירור שיתעלה יותר כו'. וביאור ענין זה, כי הנה נודע שכל דבר כלול מארמ\"ע והנה ע\"י האש יוצא ג' חלקי אמ\"ר<sup data-n=\"382\">32</sup> בבחי' העשן והנשאר הוא יסוד העפר ולכן העיקר נשאר דוקא, כי הכל הי' מן העפר, כמו\"כ יובן כאן שע\"י העשן דפרה הרשעה תכלה שהוא הדקות שבהחטא ועון, והאפר הנשאר הוא בחי' בירור החטא עצמו כנ\"ל.\n<b>ובזה</b> יובן משארז\"ל במד\"ר<sup data-n=\"383\">33</sup> כשהוא רוצה הוא קוראה לשון נקבה שנא' ויקחו אליך פרה אדומה, וכשהוא רוצה הוא קוראה לשון זכר שנא' לקח פר אחד בן בקר, כן הוא בפ' תצוה פל\"ח. ולכאו' צ\"ל הלא פר דאהרן הי' דוקא פר ופרה אדומה הי' דוקא פרה, כמו שמצינו בשארי קרבנות שמהם היו פרים ומהם היו נקבות. אך הענין הוא דהנה פר הוא בחי' קליפת נוגה אבל פרה היא בחי' ג' קליפות. ויובן זה הוא כמו ענין הנה\"ב שקודם ירידתה בגוף אינו רע כלל, אבל לאחר שירד בגוף יכול להיות נאחז ברע גמור. וזהו כמו ההפרש בין פר לפרה, שפר הוא בחי' ק\"נ ופרה בחי' ג' קליפות<sup data-n=\"384\">34</sup>, וזהו כשהוא רוצה קוראה פר שהו\"ע בירור ק\"נ אבל כשהוא רוצה הוא קוראה פרה דהיינו הבירור מג\"ק, וזהו ע\"ד כמו יעקב העלה אבק עד כסא הכבוד שאפי' בחי' אבק העלה ג\"כ<sup data-n=\"385\">35</sup>. וז\"ע הפרה ג\"כ",[["380","30","<b>ונפש הוא בחי' החיות המחי' מקום וזמן</b>: ראה אוה\"ת יתרו ע' תתכה: לפ\"ד כל מפרשי הס' יצירה עולם גבוה מבחי' שנה ושנה גבוה מבחי' הנפש, ואאזמו\"ר נ\"ע כאן פי' להיפוך דנפש הוא גבוה מבחי' שנה עולם. ובסה\"מ תרכ\"ז שם [ועד\"ז בסה\"מ תרכ\"ח ותרל\"ח שם]: ונפש הוא בחי' שמחי' המדות כן פי' רבינו ז\"ל כו', רבינו ז\"ל ברוב הדרושים אמר כנ\"ל ומסתמא שמע כן מהמגיד נ\"ע. וראה בהוספות לס' לקו\"א ואו\"ת להה\"מ (הוצאת קה\"ת) יח, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380575\" data-slug=\"likkutei-torah\" data-id=\"4001380575\">לקו\"ת חקת סד, ד</a>. מאמרי אדה\"ז תקס\"ד ע' קכה. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' א. וס\"ע שט ואילך. אוה\"ת וארא ע' ר. וע' ריח. יתרו ע' תתיח. [ובהנסמן ע\"ז בארוכה בסה\"מ תרכ\"ז שם ע' צט]."],["381","31","<b>יש גוף החטא. . ויש בחי' הדקות. . רק החטא והעון. . יוכל להתעלות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חקת שם נו, ג</a>-ד. דרושים לר\"ה סא, ב. ובכ\"מ."],["382","32","<b>נודע שכל דבר כלול מארמ\"ע והנה ע\"י האש יוצא ג' חלקי אמ\"ר</b>: ראה בכ\"ז אגה\"ק סי' טו (קכא, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380542\" data-slug=\"likkutei-torah\" data-id=\"4001380542\">לקו\"ת חקת שם נו, ג</a>. נח, סע\"ג. ס, ב. סה\"מ תרכ\"ט ע' קסג. וראה גם המשך תער\"ב ח\"ג ע' א'תמב. ועוד."],["383","33","<b>ובזה יובן משארז\"ל במד\"ר</b>: בהבא לקמן ראה (באו\"א) <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830077\" data-slug=\"or-hatorah-hb\" data-id=\"8158830077\">אוה\"ת חקת ע' תשסג</a>. ע' תשעד. שם בהוספות (הוצאת תשנ\"ח) ע' 22."],["384","34","<b>פר הוא בחי' ק\"נ אבל פרה היא בחי' ג' קליפות</b>: באוה\"ת שבהע' שלפנ\"ז פר הוא דכר דק\"נ ופרה היא בחי' נוקבא דק\"נ. וראה אגה\"ק סי' כח (קמח, א) שפרה אדומה מכפרת אף גם על הזדונות שהן מג' קליפות הטמאות שלמטה מנוגה כו' משא\"כ בקרבנות שע\"ג המזבח שאינן מכפרים אלא על השגגות שמנוגה. וראה אוה\"ת חקת שם ע' תשסב [ושם: פרה אדומה שהיא נוק' דק\"נ היא יותר רע]. תשעה-ו. תשפח-ט. ס\"ע תשצג-ד. ועוד."],["385","35","<b>יעקב העלה אבק עד כסה\"כ שאפי' בחי' אבק העלה ג\"כ</b>: ראה תו\"א וישלח כ, ד. לעיל ד\"ה אתה אחד וד\"ה כמים הפנים. וש\"נ."]]],[2000460187,"שמטהר טמא מת היינו בחי' מה שהרשעי' קרוי' מתים, משא\"כ שאר הקרבנות אין באי' כ\"א על שגגות דוקא<sup data-n=\"386\">36</sup> כנודע.\n<b>והנה</b> לפ\"ע העלי' דבחי' רצוא דפרה כן הוא המשכת השוב הוא בחי' ונתן עליו מים חיים<sup data-n=\"387\">37</sup> אל כלי, דהנה מים חיים הוא כמו שהם נובעי' מהמקור. ויובן זה ממה שאנו רואי' שכאשר בא לאדם איזה השכלה הנה הוא מתמלא תענוג משא\"כ לאחר שמתיישן השכל אינו מקבל תענוג ממנו כלל, והיינו מפני שכאשר השכל הוא קרוב למקורו אז מאיר בו התגלות התענוג אבל לאחר שמתיישן הלא הוא מתרחק ממקורו לכן לא נמצא בו בחי' התענוג כו'. ועד\"ז יובן ההפרש בין השוב דתומ\"צ לבחי' השוב דפרה שהוא בחי' מים חיים, דבכל התו' השוב הוא בחי' מים סתם, אבל השוב דפרה הוא בחי' מים חיים שנובעי' מהמקור כו'. וההמשכה הוא אל כלי היינו בחי' המצות הנק' כלים להמשכת אוא\"ס ב\"ה. וזהו בד\"כ ענין ק\"ש שמתחלה ואהבת בכל לבבך הוא בחי' רצוא דכל התורה, ובכל נפשך הוא בחי' השוב כו', ואח\"כ בכל מאדך ה\"ע רצוא דפרה, והיו הדברים האלה אשר אנכי כו'<sup data-n=\"388\">38</sup> הוא בחי' מים חיים שוב דפרה, וקשרתם הוא בחי' המצות כי הוקשה כל התורה כולה לתפילין הם בחי' הכלים להמשכת אוא\"ס ב\"ה. והנה עוד הי' בפרה תולעת שני ואזוב ועץ ארז, כי התולעת מכה ארזים בפי'<sup data-n=\"389\">39</sup>, כן הוא בחי' נש\"י שע\"י הדבור בתורה ותפלה שהתורה היא בחי' ודברי אשר שמתי בפיך<sup data-n=\"390\">40</sup> וכמו\"כ בחי' התפלה, ע' בדרוש אד' שפתי תפתח<sup data-n=\"391\">41</sup>, וע\"י הם מכים ארזי', כי כמו שיש ארזי' בקדושה בחי' צדיק כתמר כן יש בלעו\"ז כו'<sup data-n=\"392\">42</sup>.\n<b>ומעתה</b> יובן סדר הפסוק<sup data-n=\"393\">43</sup> וידבר ה' ולמה נאמר ב\"פ הוי', דהנה כתי' וירא ישראל את היד הגדולה אשר עשה ה' במצרים, ופי' אשר עשה הוי' במצרים<sup data-n=\"394\">44</sup>,",[["386","36","<b>שאר הקרבנות אין באי' כ\"א על שגגות דוקא</b>: ראה בארוכה ע\"ז בסה\"מ תרל\"ג ח\"א ע' קמט ובשוה\"ג שם. וע' קצג ובשוה\"ג שם. וש\"נ."],["387","37","<b>המשכת השוב. . ונתן עליו מים חיים</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380541\" data-slug=\"likkutei-torah\" data-id=\"4001380541\">לקו\"ת חקת שם נו, סע\"ב</a>-ג."],["388","38","<b>והיו הדברים האלה אשר אנכי כו'</b>: בד\"ה זה בסה\"מ תרכ\"ט נוסף כאן הגה\"ה בגוכי\"ק: פי' הדברים האלה דתומ\"צ כמו שנמשכים מבחי' אנכי שקרובים להמקור."],["389","39","<b>והנה עוד הי' בפרה תולעת שני. . מכה ארזים בפי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380544\" data-slug=\"likkutei-torah\" data-id=\"4001380544\">לקו\"ת חקת שם נז, א</a>. נח, סע\"ד. ועוד."],["390","40","<b>שהתורה היא בחי' ודברי אשר שמתי בפיך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">תו\"א יתרו סז, סע\"ג</a> ואילך."],["391","41","<b>בדרוש אד' שפתי תפתח</b>: סה\"מ תרכ\"ו ע' רפה. תרכ\"ז ע' תעז."],["392","42","<b>כמו שיש ארזי' בקדושה בחי' צדיק כתמר כן יש בלעו\"ז כו'</b>: בד\"ה זה תרכ\"ט נוסף כאן הגה\"ה בגוכי\"ק: כמ\"ש קול ה' שובר ארזים, ע' בפי' רש\"י ע\"פ זה. [ז\"ל רש\"י עה\"פ (תהלים כט, ה): קול ה' שובר ארזים, האומות כענין שנאמר וירעם ה' בקול גדול על פלשתים וגו', כי מקול ה' יחת אשור, ובשעת מתן תורה כי מי כל בשר וגו' ויחי, אתה שמעת וחיית ואומות העולם שומעים ומתים. ע\"כ. וראה מאמרי אדה\"ז הקצרים ע' רה: ארזים דהיינו התאוות שהם קשים כארז]."],["393","43","<b>ומעתה יובן סדר הפסוק</b>: בהבא לקמן עד סוף הפיסקא ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830027\" data-slug=\"or-hatorah-hb\" data-id=\"8158830027\">אוה\"ת חקת</a> בהוספות שם ע' 27-8."],["394","44","<b>דהנה כתי' וירא ישראל. . ופי' אשר עשה הוי' במצרים</b>: בהבא לקמן ראה בהביאור לד\"ה וירא ישראל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950451\" data-slug=\"or-hatorah-hb\" data-id=\"8315950451\">אוה\"ת בשלח שם ע' תנא</a> ואילך. ס\"ע תנו-ז. וע' תסח-ט."]]],[2000460188,"שבמצרים עשו ישראל שיהי' התגלות ש' הוי', דקודם יצי\"מ נא' וארא אל אברהם באל שדי ושמי הוי' לא נודעתי להם שהי' הגילוי אל האבות רק בש' שדי אבל שמי הוי' לא נודעתי<sup data-n=\"395\">45</sup> להם, אבל במצרים נתגלה ש' הוי', וזהו אשר עשה הוי' במצרים היינו שש' הוי' עשו במצרים, פי' גילוי ש' הוי', והיינו ע\"י השעבוד כו' וכמאמר רב מתיבתא בזהר פ' שלח אעא דלא סליק בה נורא<sup data-n=\"396\">46</sup> מבטשין לי', גופא דלא סליק בי' נהורא דנשמתא מבטשין לי', וגם ע\"י בירור הניצוצות שביררו במצרים כו'. ולכן בפרה אדומה שמרומז בה ד' מלכיות<sup data-n=\"397\">47</sup> כמשארז\"ל פרה זו מצרים שנא' עגלה יפיפי' מצרים, אדומה זו בבל שנא' אנת הוא רישא דדהבא, תמימה זו מדי כי מלכי מדי תמימי' היו כו', אשר לא עלה כו'<sup data-n=\"398\">48</sup>, נאמר [בה] ב' פעמים הוי' והיינו כי ע\"י בירור ד' מלכיות עי\"ז יתגלה ש' הוי' דלעילא כו'. וזהו פי' הפסוק וידבר הוי' הוא ש' הוי' דז\"א, אל משה הוא יסוד ז\"א<sup data-n=\"399\">49</sup>, לאמר שיהי' הגילוי במל', זאת חקת התורה אשר צוה הוי' היינו ש' הוי' דלעילא בחי' עתיקא שיתגלה ע\"י בחי' פרה בירור ד' מלכיות כו', לאמר הוא בחי' חכ' היינו כי הגילוי הוא בחכ'.\n<b>וענין</b> זאת חקת התורה ית' בו ענין הג' פירושי'<sup data-n=\"400\">50</sup>, הא' לשון אותיות החקיקה, דהנה אותיות הכתיבה הוא שכותבין בדיו על הקלף, והרי הדיו מסתיר על מקום הלבן שבקלף, אבל אותיות החקיקה הם מיני' ובי' שאין שום דבר המסתיר ומעלים כו', ואותיות אלו גבוהי' מאד. ומזה נמשך פי' חוק ל' חוק ומשפט שלמעלה מן השכל כי לעוצם גדלות בחי' אותיות החקיקה אינם יכולים להיות נמשכי' בבחי' הטו\"ד, כ\"א הם בבחי' שלמעלה מן הטו\"ד. ומזה נמשך ג\"כ ל' חוקה דהיינו ל' קביעות כי חוק נק' המל'<sup data-n=\"401\">51</sup> והנה במל' יש עליות וירידות וזהו ענין חוקה ל' קביעות שיומשך הקביעות במל', וזהו מבחי' אני ה' לא שניתי כו', והיינו כי כתי' אכלו ריעים",[["395","45","<b>הגילוי אל האבות רק בשם שדי אבל שמי הוי' לא נודעתי</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' מט. וש\"נ. וע' צד ואילך. ובכ\"מ."],["396","46","<b>וכמאמר רב מתיבתא. . אעא דלא סליק בה נורא</b>: הובא ונת' ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט (לה, סע\"ב</a>). בזהר ובתניא שם: בי' נהורא. וראה לקמן ד\"ה אך הנה כו' זית רענן."],["397","47","<b>בפרה אדומה שמרומז בה ד' מלכיות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380561\" data-slug=\"likkutei-torah\" data-id=\"4001380561\">לקו\"ת חקת סא, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830091\" data-slug=\"or-hatorah-hb\" data-id=\"8158830091\">אוה\"ת חקת ע' תשעז</a>. ועוד."],["398","48","<b>אשר לא עלה כו'</b>: במדרש תנחומא (באבער) פ' חקת סכ\"ז [ועד\"ז בפסיקתא פי\"ד. ובפסיקתא דר\"כ פ' פרה. ובילקוט פ' חקת] ממשיך כאן: אשר לא עלה עליה עול, זו אדום שלא קבלה עליה עולו של הקב\"ה, ולא דייך שלא קבלה אלא מחרפת ומגדפת ואומרת מי לי בשמים וגו'."],["399","49","<b>משה הוא יסוד ז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש ח\"ו ע' 244</a> ואילך."],["400","50","<b>וענין זאת חקת התורה ית' בו ענין הג' פירושים</b>: בהבא לקמן ראה אוה\"ת חקת שם ע' תשסו-ז. אוה\"ת תצא שם ע' תתקס-סא."],["401","51","<b>חוק נק' המל'</b>: בד\"ה זה תרכ\"ט: חוק הוא היסוד [כמ\"ש] וחוק בשארו שם. — וראה יהל אור להצ\"צ ע' יג. ביאוה\"ז להצ\"צ ח\"א ע' תפו. שם ח\"ב ע' תתקפט ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830104\" data-slug=\"or-hatorah-hb\" data-id=\"8158830104\">אוה\"ת חקת ס\"ע תשצ</a>-צא [ושם: (מביא בשם המאו\"א אות ח' סנ\"ב-ג): חק מצד היסוד וחק בשארו שם כו', חקה נק' המל' הנחקקת ע\"י היסוד המחוקק אותה]. ועד\"ז בסה\"מ תרכ\"ט ע' רסה. תרל\"ב ח\"ב ע' תסח. תרל\"ג ח\"א ע' ריט (בשם הפרדס)."]]],[2000460189,"שתו ושכרו דודים ואיתא בזהר<sup data-n=\"402\">52</sup> אכלו ריעי' לעילא שתו ושכרו דודי' לתתא, והיינו כי יחוד זו\"נ אינו תדיר אבל או\"א זיווגייהו תדיר, וזהו ענין הקביעות שגם בזו\"נ יהי' זיווגייהו תדיר, וזהו ע\"ד שביקש יעקב בשכמל\"ו שיומשך כבוד מל' ית' ע\"ד ואולם חי אני וימלא כבוד הוי', וע\"ד ברוך כבוד הוי' ממקומו כמ\"ש בד\"ה ואולם חי אני<sup data-n=\"403\">53</sup> יעו\"ש. [וזהו\"ע זאת חקת שיומשך החוק והקביעות בזאת היא בחי' מל'].",[["402","52","<b>אכלו ריעים שתו ושכרו דודים ואיתא בזהר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381262\" data-slug=\"likkutei-torah\" data-id=\"4001381262\">לקו\"ת שה\"ש לג, סע\"ב</a>-ג. סה\"מ תרל\"ג ח\"א ע' קי-יא. וש\"נ."],["403","53","<b>כמ\"ש בד\"ה ואולם חי אני</b>: סה\"מ תרל\"ד ע' רמג ואילך. וראה גם מאמרי אדה\"ז תקס\"ט ע' קפה. פרשיות ח\"ב ע' תרכח. אוה\"ת שלח ע' תקיא ואילך. דרמ\"צ קעח, א ואילך."]]],[2000460190,"<h3>החדש הזה כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ ויק\"פ, פ' החודש, ט\"ל).</b>\nשמחה ש\"מ כו' צבי כו' ניסן, תשרי\nויק\"פ, פ' החודש\n<b>החדש</b> הזה לכם<sup data-n=\"404\">1</sup> ראש חדשים ראשון הוא לכם, הנה כתי' ויקהלו כו' בירח האתנים<sup data-n=\"405\">2</sup> בחג הוא החדש השביעי ות\"י עתיקייהו הוי קרי לי' ירחא קדמאה, כי בך\"ה באלול נברא העולם ותשרי הוא ר\"ה לשנים, כמ\"ש והיו לאותו ולמועדים ולימים ושנים, וכען הוא ירחא שביעאה, לפי שניסן הוא ראש חדשי'. וזהו כמ\"ש רז\"ל במד\"ר פ' בא פט\"ו משבחר הקב\"ה בעולמו קבע בו ראשי חדשים ושנים, וכשבחר ביעקב ובניו קבע בו ר\"ח של גאולה שבו נגאלו ישראל ממצרים, ובו עתידי' ליגאל שנא' כימי צאתך כו', וזהו כר' יהושע שבניסן עתידי' להגאל בפ\"ק דר\"ה די\"א.\n<b>ולהבין</b> זה צ\"ל מה שבכ\"י צריך להזכיר יצ\"מ בבקר ובערב. ויובן בהקדם הדרוש שבת\"א לכן אמור לבנ\"י<sup data-n=\"406\">3</sup> אני ה' והוצאתי אתכם מתחת סבלות מצרים,",[["404","1","<b>החדש הזה לכם</b>: המאמר מיוסד על ד\"ה זה באוה\"ת בא ע' רסד ואילך. והערות וקיצורים ע\"ז שם (כרך ז) ע' ב'תריב ואילך. הנחה ממאמר הצ\"צ [משנת תרכ\"א] נדפסה באוה\"ת בא (כרך ח) ע' ב'תתקכ ואילך. [וראה בהנסמן לקמן פיסקא: ולהבין זה צ\"ל מה שבכ\"י].\nעניני המאמר נמצאים באריכות בד\"ה אני ישנה בסה\"מ תרל\"ד ע' קס ואילך. ובשינויים והוספות בד\"ה החודש הזה בסה\"מ עזר\"ת ע' קלד ואילך. ד\"ה מה יפית בסה\"מ תרפ\"ג ע' ריא ואילך. ד\"ה אריב\"ל כו' כל העוסק בתורה בסה\"מ תרפ\"ח ע' קד ואילך. ד\"ה מה יפית: בסה\"מ תרצ\"ט ע' 157 ואילך. תש\"ט ע' 76 ואילך. תש\"י ע' 207 ואילך. ד\"ה החודש הזה תשי\"ד. תשי\"ז. תשי\"ט. תשכ\"ו. וראה גם ד\"ה זה בפלח הרמון שמות ע' סו ואילך.\nלחלק הב' של המאמר (פיסקא: ומעתה יובן ענין המד\"ר, ואילך) ראה בארוכה ד\"ה זה בסה\"מ עטר\"ת ע' שכג. וע' של ואילך. ה'ש\"ת ע' 19 ואילך. וס\"ע 27 ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011245\" data-slug=\"likkutei-sichot\" data-id=\"1300011245\">לקו\"ש ח\"א ע' 231</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171147\" data-slug=\"likkutei-sichot\" data-id=\"1300171147\">חי\"ז ע' 147</a> ואילך. ועוד.\nראה גם לקמן מאמר זה בהנחות כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["405","2","<b>הנה כתי' ויקהלו כו' בירח האתנים</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600061\" data-slug=\"or-hatorah-hb\" data-id=\"8316600061\">אוה\"ת נ\"ך (כרך א) ע' סא</a>. לקמן ח\"ב רד\"ה ויקהלו אל המלך שלמה. וש\"נ."],["406","3","<b>ולהבין זה. . הדרוש שבת\"א לכן אמור לבנ\"י</b>: הבא לקמן (עד פיסקא: ומעתה יובן ענין המד\"ר) מיוסד על ד\"ה לכן אמור לבנ\"י וביאורו ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370256\" data-slug=\"torah-or\" data-id=\"3901370256\">תו\"א וארא נז, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370260\" data-slug=\"torah-or\" data-id=\"3901370260\">נח, ב</a> ואילך. ונו\"א בס' מאמרי אדה\"ז תקס\"ג ח\"א ע' קו ואילך. וע' קיג ואילך. ונו\"א בתו\"ח שמות (כת\"י הר\"ש סופר) קא, א ואילך. קג, סע\"א ואילך. ובארוכה בס' מאמרי אדהאמ\"צ שמות ח\"א ע' מו ואילך. אוה\"ת וארא (כרך ז) ס\"ע ב'תקצז ואילך. והגהות ע\"ז באוה\"ת וארא שם ס\"ע קעא ואילך. וע' קעז ואילך."]]],[2000460191,"דהנה כתי' מה יפית ומה נעמת אהבה בתענוגי' שקאי על כנס\"י כמו שהיא למעלה<sup data-n=\"407\">4</sup>. ולהבין בחי' זו בעבודה בנפש האדם, הנה היא בחי' שמחה של מצוה ישמח ישראל בעושיו, דהנה כתי' תחת אשר לא עבדת כו' בשמחה כו' מרוב כל, פי' כל<sup data-n=\"408\">5</sup> הוא העמוד המחבר ג\"ע העליון וג\"ע התחתון, וארז\"ל יפה שעה אחת בתשובה ומעשים טובים בעוה\"ז מכל חיי העוה\"ב, ולכן הוא מרוב כל, יותר מבחי' כל. וביאור הענין דהנה כתי' כי נשגב שמו<sup data-n=\"409\">6</sup> שכל השתלשלות העולמות הוא רק מבחי' שמו שהוא הארה בעלמא כמשל שם האדם<sup data-n=\"410\">7</sup> כו', וכמ\"ש כי בי\"ה הוי' צור עולמים בב' אותיות לבד, ובאמת כי נשגב שמו, שבחי' שמו הוא ג\"כ נשגב, ורק הודו על ארץ ושמים שרק הארה מבחי' שמו נמשך על ארץ ושמים הוא ג\"ע התחתון והעליון<sup data-n=\"411\">8</sup>, כי השגת הנבראי' בהבורא ית' א\"א להיות כ\"א בהארה מבחי' שמו ולא בבחי' שמו ית' עצמו, וגם בבחי' זו הגם שהיא רק הארה בעלמא מבחי' שמו מ\"מ יש בה ג\"כ תענוג נפלא עד אין קץ לפי שהוא מהארת שמו ית' שהוא א\"ס. אבל המצות הם מצותיו ממש כמשרז\"ל הקב\"ה מניח תפילין הקב\"ה מתעטף בציצית, שבת להוי', מועדי הוי', שבמועדי' נמשך תוס' הארה בש' הוי', וכמו\"כ בצדקה כתי' אני מדבר בצדקה, שהם מצותיו ממש של עצמותו ית', לכן העבודה בשמחה הוא מרוב כל מכל תענוגי עוה\"ב.\n<b>אך</b> העבודה צ\"ל בשמחה דוקא, שהשמחה היא פנימיות המצוה, משא\"כ כשעושה המצוה בדרך מצות אנשי' מלומדה היא כגוף בלא נשמה, שכמו באברי הגוף יש עצם האבר, והחיות, כן עד\"ז הוא במצות, שהשמחה של מצוה היא הפנימיות של המצוה, וצ\"ל העבודה בשמחה שיתבונן שהם מצותיו כנ\"ל, ועי\"ז יהי' ישמח ישראל בעושיו, וממילא יומשך להיות ישמח הוי' במעשיו. והנה כתי' אם הבנים שמחה, וכתי' כי אם לבינה תקרא, שהשמחה היא בינה<sup data-n=\"412\">9</sup>, וצ\"ל אם הבנים דהיינו שיומשך השמחה במדות דוקא ולא שישאר השמחה וההתבוננו' במוחו, ובחי' מצרים הוא המונע להיות גילוי השמחה מהמוח למדות, וזהו מצרים מיצר הגרון, שמהמוח",[["407","4","<b>דהנה כתי' מה יפית. . שקאי על כנס\"י כמו שהיא למעלה</b>: ראה תו\"א וארא שם. [ובדרושים שנסמנו בהע' שלפנ\"ז]. וראה גם אוה\"ת שה\"ש (כרך ב) ע' תריג ואילך. סה\"מ קונטרסים ח\"א קמז, ב. קנא, סע\"א-ב."],["408","5","<b>דהנה כתי' תחת אשר. . מרוב כל פי' כל</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370363\" data-slug=\"torah-or\" data-id=\"3901370363\">תו\"א תצוה פא, ב</a>-ג. ובכ\"מ."],["409","6","<b>דהנה כתי' כי נשגב שמו</b>: ראה לקמן ד\"ה הללוי' גו' מן השמים פ\"ב. וש\"נ."],["410","7","<b>שמו שהוא הארה בעלמא כמשל שם האדם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370354\" data-slug=\"torah-or\" data-id=\"3901370354\">תו\"א תרומה עט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380588\" data-slug=\"likkutei-torah\" data-id=\"4001380588\">בלק סז, ג</a>. ובכ\"מ."],["411","8","<b>ארץ ושמים הוא ג\"ע התחתון והעליון</b>: ראה תו\"א וארא שם נו, ג."],["412","9","<b>אם הבנים שמחה וכתי' כי אם לבינה תקרא שהשמחה היא בינה</b>: ראה מאמרי אדהאמ\"צ במדבר ח\"ג ס\"ע תתקסח-ט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600547\" data-slug=\"or-hatorah-hb\" data-id=\"8316600547\">אוה\"ת נ\"ך (כרך א) ע' תקמז</a> ואילך. וראה גם לקו\"ת דרושים לשמע\"צ פח, ד."]]],[2000460192,"נמשך ללב ע\"י הקנה כמ\"ש קנה חכ', ומצרים מונעים לבחי' זו. וזהו ג' שרי פרעה קנה ושט ורידין<sup data-n=\"413\">10</sup> שהם המונעי' ומעכבי' להיות נמשך השמחה מהתבוננות שבמוחו למדות, ובנפש הוא כאשר נמשך אחר תאוות תענוגי גשמי' והשמחה מלובש בתענוגי' גשמי'. וזהו ההפרש בין בחי' עיבור לבחי' לידה, שבחי' עיבור הוא כשהוא בהעלם, דהיינו כמו שהוא רק בהתבוננות במוחו ולא נמשך ממוח ללב, ולמעלה הוא כמשרז\"ל כשאתה מתמלא עליהם עברה כאשה עוברה, שאז דיני' שורים, אבל לידה הוא בחי' גילוי, ולכן בשעת הלידה יוצא דם שהוא בחי' דינים, והיינו כי ע\"י הלידה הוא בחי' גילוי השמחה ממוח ללב עי\"ז נעשה המתקת הדיני', וז\"ע יציאת מצרים.\n<b>וזהו</b> והוצאתי אתכם מתחת סבלות מצרים והוא ע\"י בחי' אני הוי' הוא בחי' התורה, כי מצרים הוא בחי' מיצר הגרון שהוא בחי' נחר גרוני, כי קול הוא בחי' המשכה ממוחין ומדות לבחי' הדבור, כמו קול מבשר שהוא בחי' גילוי והמשכה, אבל בגלות הוא בחי' נאלמתי דומי'<sup data-n=\"414\">11</sup> החשיתי, וגם נחר גרוני שאינו מאיר הקול והדבור. אך ע\"י התורה הוא בחי' יציאת מצרים כי התורה היא ג\"כ בחי' קול שבבחי' צוואר דקדושה<sup data-n=\"415\">12</sup>, שהוא בחי' קול גדול ולא יסף שפי' לא פסק שנמשך תמיד, וכמ\"ש קול דודי הנה זה בא ל' הוה שנמשך תמיד<sup data-n=\"416\">13</sup> רק שנמשך בדרך דילוג. וזהו שמברכין נותן התורה ל' הוה<sup data-n=\"417\">14</sup> שתמיד בכ\"י הוא יצ\"מ בעבודה ע\"י בחי' קול גדול שבתורה כו'. ופי' קול גדול ע\"ד מ\"ש באברהם משתה גדול, גדול עולמים הי' שם, וכמו גדול הוי' כו', ולכן ע\"י התורה שהוא בחי' קול גדול בחי' הקל קול יעקב נמשך בחי' יציאת מצרים. וזהו לכן אמור לבנ\"י אני הוי' שע\"י בחי' התורה הוא בחי' יציאת מצרים והוצאתי אתכם כו'.\n<b>והבאתי</b> אתכם אל הארץ אשר נשאתי כו' היא בחי' תושבע\"פ<sup data-n=\"418\">15</sup>, כי תושב\"כ היא רק דרך רמז לבד, כמו תפילין וציצית שאינו מבואר היטב איך לעשותם, אבל בתושבע\"פ מתבאר היטב שהתפילין יהיו מרובעין ותפורי' בגידין, והיינו כי עיקר",[["413","10","<b>ג' שרי פרעה קנה ושט ורידין</b>: ראה בכ\"ז בארוכה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370453\" data-slug=\"torah-or\" data-id=\"3901370453\">תו\"א ויחי קב, ג</a> ואילך. סה\"מ תרל\"ג ח\"א ע' נד ואילך. וע' רכו ואילך."],["414","11","<b>מיצר הגרון. . נחר גרוני. . נאלמתי דומי'</b>: בכ\"ז ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370262\" data-slug=\"torah-or\" data-id=\"3901370262\">תו\"א וארא שם נח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370263\" data-slug=\"torah-or\" data-id=\"3901370263\">נט, א</a>-ב. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א ויצא כא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370104\" data-slug=\"torah-or\" data-id=\"3901370104\">כב, ב</a>. ועוד."],["415","12","<b>שבבחי' צוואר דקדושה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770407\" data-slug=\"or-hatorah-hb\" data-id=\"8316770407\">אוה\"ת וארא ע' רמ</a>. אוה\"ת שה\"ש (כרך ב) ס\"ע תז ואילך. סה\"מ תר\"ל ע' כז."],["416","13","<b>קול גדול ולא יסף. . וכמ\"ש קול דודי. . שנמשך תמיד</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ז ע' ריא-ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381189\" data-slug=\"likkutei-torah\" data-id=\"4001381189\">לקו\"ת שה\"ש טו, סע\"א</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381294\" data-slug=\"likkutei-torah\" data-id=\"4001381294\">ב. מא, סע\"ג</a>. וראה גם אוה\"ת מג\"א (הוצאת תש\"נ) ע' רנב ואילך. סה\"מ תרנ\"ט ע' קעט."],["417","14","<b>וזהו שמברכין נותן התורה ל' הוה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע כג, א</a>. דרושים לחה\"ס פא, ג. סה\"מ תר\"ל ע' ריא. עטר\"ת ע' תלח. תרפ\"ה ע' ריא. תש\"ה ע' 184. ועוד."],["418","15","<b>והבאתי אתכם אל הארץ. . בחי' תושבע\"פ</b>: בהבא לקמן ראה תו\"א וארא שם. ובארוכה בד\"ה אני ישנה בסה\"מ תרל\"ד שם ע' קפח ואילך."]]],[2000460193,"התגלות רצה\"ע הוא בתושבע\"פ<sup data-n=\"419\">16</sup> דוקא, ולכן נק' ארץ הצבי שהוא ל' רצון<sup data-n=\"420\">17</sup>. וגם ל' רץ כצבי, כי כתי' מכנף כו' צבי לצדיק וארז\"ל ביקש הקב\"ה לעשות חזקי' משיח<sup data-n=\"421\">18</sup>. והענין הוא כי תושבע\"פ מתלבשת אפילו בשקר כמו זה אומר כולה שלי וזה אומר כולה שלי שאחד מהם טוען שקר, ועד\"ז בשארי הלכות גשמיות, כמו המחליף פרה בחמור, ואעפ\"כ נמשך רצה\"ע בתושבע\"פ לברר הדין עם מי, שהוא השפלה יותר מתושב\"כ. ולכן בחי' זו צ\"ל ע\"י צבי דוקא, כי תושב\"כ הוא ג\"כ ע\"י אותיות הנק' סוסים כמ\"ש כי תרכב על סוסיך<sup data-n=\"422\">19</sup>, אך כדי שיהי' המשכת הרצה\"ע בחי' תושבע\"פ אפי' בטענות שקרי' כנ\"ל זהו ע\"י הצבי דוקא שרץ מהר. וכמו\"כ בענין חזקי' משיח, שצ\"ל ע\"י צבי דוקא וכמ\"ש במ\"א בדרושי פורים בענין אחש דאחשורש<sup data-n=\"423\">20</sup> שהוא לשון מהירות לפי שצ\"ל דוקא דומה דודי לצבי כו', וזהו לאגנא עלייהו כו', וכ\"ש במה שביקש לעשות חזקי' כו' ודאי צ\"ל ע\"י בחי' צבי דוקא שה\"ז ענין אחישנה ממש כו'.\n<b>ומעתה</b> יובן ענין המד\"ר<sup data-n=\"424\">21</sup> הנ\"ל כשבחר הקב\"ה כו', דהנה כתי' אנכי ה' אלקיך אשר הוצאתיך מאמ\"צ, וצ\"ל מפני מה לא נא' אשר בראתי יש מאין<sup data-n=\"425\">22</sup> שהוא יותר פלא, כי נסים דיצ\"מ הם יש מיש כמו דם ממים, ומים יבשה, משא\"כ ברה\"ע יש מאין. אך הענין הוא כנ\"ל שברה\"ע הוא כי נשגב שמו, בעשרה מאמרות נברא העולם והלא במאמר א' יכול להבראות, ובשתי אותיות כי בי\"ה כו', שהוא רק הארה בעלמא מבחי' שמו כנ\"ל. והנה מבחי' זו נמשך מצרים דקדושה שהוא בחי' הגבול. מהארץ לרקיע מהלך ת\"ק שנה שהוא בחי' גבול ומדה. אבל בחי' יצ\"מ הוא לצאת מהמצרים וגבולי', ובחי' זו נמשך מבחי' אנכי הוי', ולכן נא' אשר הוצאתיך מאמ\"צ, שהוא דבר גדול יותר שנמשך מבחי' אנכי הוי' להיות אלקיך כו'.",[["419","16","<b>תושב\"כ היא רק דרך רמז לבד. . עיקר התגלות רצה\"ע הוא בתושבע\"פ</b>: ראה בכ\"ז אגה\"ק סי' כט (קנ, ב ואילך). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370263\" data-slug=\"torah-or\" data-id=\"3901370263\">תו\"א וארא שם נט, א</a>-ב."],["420","17","<b>ארץ הצבי שהוא ל' רצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370265\" data-slug=\"torah-or\" data-id=\"3901370265\">תו\"א וארא שם נט, סע\"ג</a>. וראה ד\"ה אני ישנה בסה\"מ תרל\"ד שם ע' קפב: ורבינו ז\"ל פי' צבי מלשון רצון."],["421","18","<b>מכנף כו' צבי לצדיק וארז\"ל ביקש הקב\"ה לעשות חזקי' משיח</b>: בהבא לקמן ראה בארוכה ד\"ה אני ישנה בסה\"מ תרל\"ד שם ע' קפט ואילך. וע' קצה ואילך. — ז\"ל הגמ' (סנהדרין צד, א): ביקש הקב\"ה לעשות חזקיהו משיח כו' אמרה מדת הדין לפני הקב\"ה חזקי' שעשית לו כל הניסים הללו ולא אמר שירה תעשהו משיח כו' מיד פתחה הארץ ואמרה לפניו רבש\"ע אני אומרת לפניך שירה תחת צדיק זה ועשהו משיח פתחה ואמרה שירה לפניו שנא' מכנף הארץ זמירות שמענו צבי לצדיק וגו'. [וראה סה\"מ תרל\"ד שם שמביא את ל' הגמ' ומסיים: נמצא שצבי לצדיק שייך למשיח — ראה לקמן בפנים]."],["422","19","<b>תושב\"כ הוא ג\"כ ע\"י אותיות הנק' סוסים כמ\"ש כי תרכב על סוסיך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370282\" data-slug=\"torah-or\" data-id=\"3901370282\">תו\"א בשלח סג, א</a>. סג, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381140\" data-slug=\"likkutei-torah\" data-id=\"4001381140\">לקו\"ת</a> דרושים ליוהכ\"פ סט, סע\"ג. שה\"ש ב, סע\"ד. ג, א. לג, ג. סה\"מ תרכ\"ז ע' רו. תרל\"ד ע' שנג וע' שנט."],["423","20","<b>וכמ\"ש במ\"א בדרושי פורים בענין אחש דאחשורש</b>: הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370527\" data-slug=\"torah-or\" data-id=\"3901370527\">תו\"א מג\"א קיח, א</a>. סה\"מ תרכ\"ז ע' רט."],["424","21","<b>ומעתה יובן ענין המד\"ר</b>: בהבא לקמן עד סוף המאמר ראה גם אוה\"ת נ\"ך (כרך א) ע' סא ואילך. ד\"ה אני ישנה בסה\"מ תרל\"ד ע' קסח ואילך."],["425","22","<b>אשר הוצאתיך מאמ\"צ. . לא נא' אשר בראתי יש מאין</b>: ראה עד\"ז סידור עם דא\"ח רפד, ב. מאמרי אדהאמ\"צ ויקרא ח\"א ע' תב. וע' תפד. שער האמונה לאדהאמ\"צ יא, ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460088\" data-slug=\"or-hatorah-hb\" data-id=\"8316460088\">אוה\"ת יתרו ע' תתקג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600729\" data-slug=\"or-hatorah-hb\" data-id=\"8316600729\">וע' תתקטו</a>. ראה ע' תשכט. אוה\"ת סידור ע' קט. יהל אור לתהלים ע' קי. סה\"מ תרכ\"ז ע' רלג ואילך. וש\"נ. תרכ\"ט ע' רכ ואילך."]]],[2000460194,"<b>ועד\"ז</b> יובן ההפרש בין כשבחר הקב\"ה בעולמו<sup data-n=\"426\">23</sup> קבע להם ראשי חדשים, שתשרי הוא הראש, כי בריאת העולמות נמשך מבחי' שמו כנ\"ל, ובבחי' זו תשרי ר\"ה לשנים להנהגת העולמות, וכמו\"כ בכל ההשפעות גשמי' כמו מזונותיו של אדם קצובות לו מר\"ה שה\"ע פרנסה כו', וזהו דעתיקייהו הוי קרי לי' ירחא קדמאה. אבל משבחר הקב\"ה ביעקב ובניו קבע להם חדש של גאולה כמא' ומביא גואל כו' למען שמו, כי גלו למצרים שכינה עמהם שנא' אנכי ארד כו', גלו לבבל כו', ע' במד\"ר פ' בא פט\"ו. וכדי שיהי' יצ\"מ קבע להם חדש של גאולה, שבחי' חדש של גאולה הוא בחי' יצ\"מ, והיינו שכמו שיש י\"ב חדשי השנה בבחי' בריאת העולמות שקבע להם ראשי חדשים, שבכל חדש נמשך הארה חדשה והם בחי' י\"ב בקר ד' מחנות שכינה, ושרש קבלתם הוא מבחי' הים העומד עליהם הוא בחי' שמו הנ\"ל, י\"ב צירופי אד', שבבחי' זו תשרי ר\"ה. כמו\"כ יש י\"ב חדשי' י\"ב צירופי הוי' שהוא בחי' י\"ב גבולי אלכסון<sup data-n=\"427\">24</sup>, וכמ\"ש וזרחה לכם יראי שמי שמש צדקה, שיש כמה בחי' בשמש כו', ובבחי' זו ניסן הוא הראש כמ\"ש מוציא אסירי' בכושרות שקאי על גלות מצרים, שהזמן המוכשר הי' בניסן דוקא לפי שניסן הוא צירוף הראשון שבי\"ב צירופי הוי', שהוא בחי' ש' הוי' כסדר<sup data-n=\"428\">25</sup>, משא\"כ שארי הצירופי' הם כשמתחלפי' האותיות שלא כסדרן.\n<b>וזהו</b> החדש הזה לכם שהוא חדש של גאולה, ראשון הוא לכם קאי על הקב\"ה שאני ראשון ואני אחרון כמ\"ש במד\"ר, הנה בחדש ניסן נגלה לכם, וזהו ראשון הוא לכם.\n<b>והנה</b> אע\"פ שבחדשי הגאולה ניסן הוא ראשון אעפ\"כ יש מעלה בתשרי שהוא שביעי, וזהו וכען הוא ירחא שביעאה שכל השביעין חביבין, נמצא כי יש בתשרי ב' מעלות, הא' שבבחי' החדשי' שבברה\"ע הוא ראשון, הב' שגם בחדשי הגאולה שניסן הוא ראשון מ\"מ הרי כל השביעין חביבין כו'. ואעפ\"כ חדש של גאולה הוא ניסן, ולכן ר\"א אומר בניסן נגאלו ובתשרי עתידין להגאל לפי שהשביעין חביבין.\n<b>אבל</b> ר\"י אומר שבניסן נגאלו ובניסן עתידין להגאל שנא' כימי צאתך מאמ\"צ אראנו נפלאות לע\"ל. ויש כמה טעמי' ע\"ז<sup data-n=\"429\">26</sup>, ע\"פ פשוט הוא מפני כי תשרי",[["426","23","<b>ועד\"ז יובן ההפרש בין כשבחר הקב\"ה בעולמו</b>: בהבא לקמן ראה גם סה\"מ תרס\"ה ע' קיח. תרפ\"ו ע' רמב-ג. סד\"ה באתי לגני תרצ\"ב (סה\"מ קונטרסים ח\"א קלד, א-ב)."],["427","24","<b>י\"ב בקר ד' מחנות שכינה. . י\"ב צירופי אד'. . הוי'. . גבולי אלכסון</b>: ראה בכ\"ז ביאוה\"ז לאדהאמ\"צ פה, א ואילך. ולהצ\"צ ח\"א ע' תנא ואילך. ד\"ה אני ישנה בסה\"מ תרל\"ד שם ע' קעד. וש\"נ."],["428","25","<b>שניסן. . בחי' ש' הוי' כסדר</b>: ראה בארוכה ד\"ה אני ישנה בסה\"מ תרל\"ד שם ע' קעח ואילך. סה\"מ תרע\"ח ע' רכו ואילך. ובהנסמן ע\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221259\" data-slug=\"likkutei-sichot\" data-id=\"1300221259\">לקו\"ש חכ\"ב ע' 243</a>. הגש\"פ עם לקוטי טעמים ומנהגים (הוצאת תשנ\"ב) ע' תשי. וע' תשסא."],["429","26","<b>ויש כמה טעמים ע\"ז</b>: ראה אוה\"ת בא שם ס\"ע ער ואילך (בנוסחא הא'). וראה ד\"ה החודש הזה תשי\"ד שהטעמים הם זה למעלה מזה [וראה לקמן במאמר זה הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע]. בהבא לקמן ראה גם סה\"מ תרנ\"ד ע' קלח-ט."]]],[2000460195,"הוא חדש המשפט ובבחי' המשפט כתי' הן שמים לא זכו בעיניו, ולכן אין אומרים מועדי' לשמחה בר\"ה כי הוא זמן המשפט<sup data-n=\"430\">27</sup>, ולכן ניסן הוא חדש הגאולה. הב' כי תשרי הוא שביעי לניסן כו' שהוא כמו משה שהי' דור שביעי לאברהם, ויש מעלה יתירה באברהם<sup data-n=\"431\">28</sup>, שלמשה כשאמר הנני שדימה עצמו לאברהם כמ\"ש במדרש תנחומא ע\"פ זה וכ\"ה במד\"ר פ' וירא פנ\"ה ובפ' ואתחנן פ\"ב ע\"פ אתה החלות, נא' לו אל תקרב הלום כו', וכמ\"ש ג\"כ במד\"ר על פסוק זה בפ' שמות ס\"פ ב', וי\"ל המעלה יתירה שבאברהם מפני שהוא הי' הראשון כמ\"ש מי העיר ממזרח א\"ת העיר אלא האיר במד\"ר בראשית פ\"ב שדרשו על אברהם שהתחיל להאיר. הג' כי יש ג' בחי' בתי אחותי אמי, בתי בפסח שהוא בחי' מקבל, אחותי בשבועות מ\"ת, אמי בסוכות<sup data-n=\"432\">29</sup> בחדש תשרי, ולכן ר\"א אומר בתשרי עתידי' להגאל כסדר המדרגות, אך הנה נת' בדרוש רני ושמחי בת<sup data-n=\"433\">30</sup> שבחי' אמי בעטרה שעטרה לו אמו שהעטרה עצמה היא למעלה מבחי' אמי ורק אמי מעטרו בהעטרה, אבל לעתיד יהי' עליות המל' להיות עטרת בעלה בחי' עטרה עצמה כי שרש המל' בכתר, לכן בניסן עתידי' להגאל בחי' בת כו'. הד' כי בניסן נגאלו לפי שביצ\"מ הי' הגילוי מבחי' אתעדל\"ע מצד עצמו לכן בפסח מצה לחם עוני, והנה משיח הוא ג\"כ בחי' עני, עני ורוכב על החמור כמ\"ש בזהר פ' כי תצא, והיינו כי יש אתעדל\"ע שאין אתעדל\"ת יכול להגיע שם, בחי' אהי' כטל לישראל, וזהו בחי' עני דמשיח, ולכן בניסן עתידי' להגאל לפי שהזמן שנמשך בחי' האתעדל\"ע מצד עצמו הוא בניסן דוקא, משא\"כ בתשרי כו'.",[["430","27","<b>אין אומרים מועדי' לשמחה בר\"ה כי הוא זמן המשפט</b>: ראה עד\"ז בד\"ה זה בסה\"מ ה'ש\"ת שם ע' 28, ובהערת כ\"ק אדמו\"ר זי\"ע: שו\"ע רבנו הזקן סי' תקפ\"ב ס\"י. וצע\"ק. [בשו\"ע אדה\"ז שם: בר\"ה ויוהכ\"פ אין אומרים מועדים לשמחה חגים וזמנים לששון מפני שימים אלו לא ניתנו לשמחה ולששון. ועי' בס' מראי מקומות וציונים לשו\"ע אדה\"ז שם]."],["431","28","<b>משה שהי' דור שביעי לאברהם ויש מעלה יתירה באברהם</b>: ראה בכ\"ז סה\"מ מלוקט ח\"א ע' ד-ה."],["432","29","<b>יש ג' בחי' בתי אחותי אמי. . בפסח. . בשבועות. . בסוכות</b>: ראה בכ\"ז בארוכה אוה\"ת בא ע' רנח. שם ע' רסג. שם (כרך ח) ע' ב'תתקטז ואילך. נשא ע' רעג. דרושים לשמע\"צ ע' א'תשעג ואילך."],["433","30","<b>נת' בדרוש רני ושמחי בת</b>: סה\"מ תרכ\"ז ע' שכח. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370168\" data-slug=\"torah-or\" data-id=\"3901370168\">תו\"א מקץ לו, ד</a>."]]],[2000460196,"<h3>ששים המה מלכות כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ ויקרא ט\"ל).</b>\n<b></b>ושמי הוי' לא נודעתי כו' הוי' דלעילא דלתתא כו' האבות ומ\"ת\nויקרא\n<b>ששים</b> המה מלכות<sup data-n=\"434\">1</sup> ושמונים פלגשים ועלמות אין מספר אחת היא יונתי, וארז\"ל ששים המה מלכות אלו ס' מסכתות ושמונים פלגשים אלו ברייתות ועלמות אין מספר אלו הלכות שבגמ' אחת היא יונתי זו כנס\"י, והנה מזה מובן שהנשמות הם למעלה במדריגה מבחי' התורה. ובמ\"א מצינו שארז\"ל תלת קשרין מתקשרין דא בדא ישראל מתקשראן באורייתא כו', ונמצא להיפוך שהתורה היא למעלה במדריגה מישראל.\n<b>הנה</b> כתי' וידבר אלקי' אל משה ויאמר אליו אני ה' וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם, וצ\"ל מהו התירוץ על מה שאמר משה אד' למה הרעות לעם הזה כו'. ובמד\"ר ע\"פ למה הרעות אמר משה לפני הקב\"ה נטלתי ספר בראשית וקראתי בו וראיתי מעשיהם של דור המבול ומדת הדין היתה, מעשיהם של דור הפלגה ומדת הדין היתה (ופי' המ\"כ דין אמת הי'), אבל העם הזה מה עשו שנשתעבדו כו'. ובפ' וארא כו' הה\"ד (קהלת ב' י\"ב) ופניתי אני לראות חכמה והוללות וסכלות כי מה האדם שיבא אחרי המלך את אשר כבר עשהו, הפסוק הזה נא' על שלמה ועל משה כו' כיצד נא' על משה כו' והתחיל לומר<sup data-n=\"435\">2</sup> אד' למה הרעות התחיל לדון לפניו כמ\"ש למעלה, וע\"ז נא' שאותו חכ' ודעת של משה של הוללות וסכלות הי', כי מה האדם שיבוא אחרי המלך להרהר אחר מדותיו של הקב\"ה כו'. ולהבין כ\"ז צ\"ל תחלה מ\"ש וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם, הלא גם באברהם כתי' ש' הוי' כמ\"ש ויאמר ה' אל אברם לך לך, וכתי' וירא אליו ה', וכתי' וה' אמר המכסה אני מאברהם כו'.",[["434","1","<b>ששים המה מלכות</b>: מאמר זה והמשכו (להלן ד\"ה אך הנה כו' זית רענן), נמצאים בשינויים וכו' בד\"ה ששים המה להצ\"צ [משנת תרי\"ח] בגוכי\"ק אדמו\"ר מהר\"ש בכת\"י 1063 רא, א ואילך. ונמצא בתוס' התחלה וסיום בד\"ה עיר קטנה בסה\"מ תרכ\"ו ע' קיד ואילך. ובשינויים והוספות בד\"ה עיר קטנה בסה\"מ תרנ\"ב ע' רפג ואילך.\nמאמר זה והמאמר שלאחריו מיוסדים על ד\"ה וארא תקע\"ב וביאורו [יודפס אי\"ה בס' מאמרי אדה\"ז תקע\"ב — נמצא בדפוס]. המאמר דתקע\"ב נמצא בתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560395\" data-slug=\"or-hatorah-hb\" data-id=\"8316560395\">אוה\"ת</a> וארא (כרך ז) ע' ב'תקמט ואילך וע' ב'תקסג ואילך. והביאור ע\"ז שם ע' ב'תקנז ואילך. [הביאור נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300025\" data-slug=\"or-hatorah-hb\" data-id=\"8316300025\">אוה\"ת נח (כרך ג</a>) תרסד, א ואילך]. וקיצורים ע\"ז באוה\"ת וארא (כרך ח) ע' ב'תתצג. הביאור דתקע\"ב נמצא באריכות בס' מאמרי אדהאמ\"צ שמות ח\"א ע' כה ואילך.\nמאמר הצ\"צ מובא ג\"כ בסה\"מ תרל\"ג ח\"א ע' קלא: ”ע' בד\"ה ששים המה מלכות (שהוא וארא דדור הפלגה)\".\nראה לקמן בהנחות המאמרים אשר בעת אמירת המאמר התחיל כ\"ק אדמו\"ר מהר\"ש את הדרוש עה\"פ ”לריח שמניך\". והמאמר שלאח\"ז ד\"ה אך הנה כו' זית רענן, התחיל ע\"פ ”ששים המה מלכות\". [וראה לקמן בסיום מאמר זה פיסקא: וזהו מ\"ש. . ע\"פ לריח שמניך]."],["435","2","<b>כיצד נא' על משה כו' והתחיל לומר</b>: ז\"ל המדרש (שמו\"ר פ\"ו, א): כיצד נאמר על משה לפי שכבר הודיע הקב\"ה למשה שלא יניח אותם פרעה לילך כו' ומשה לא שמר את הדבר הזה אלא בא להתחכם על גזירתו של הקב\"ה והתחיל אומר למה הרעות [כבפנים]."]]],[2000460197,"<b>אך</b> הענין דהנה כתי' ויקרא ה' ה' שיש שני שמות הוי' ופסיק טעמא<sup data-n=\"436\">3</sup> בגווייהו, וענין הפסיק טעמא נת' בזהר שזהו ע\"ד מ\"ש יהי רקיע ויהי מבדיל בין מים למים. והנה ברקיע נא' ב' הבדלות כמ\"ש יהי רקיע ויהי מבדיל כו' ואח\"כ ויעש אלקי' את הרקיע ויבדל<sup data-n=\"437\">4</sup>, והיינו שבד\"כ יש ב' הבדלות הא' הוא כמ\"ש והבדילה הפרוכת לכם בין הקדש ובין קה\"ק, והשנית היא הפרסא שבין קדש לחול<sup data-n=\"438\">5</sup>. והגם שבד\"פ יש ז' הבדלות, בד\"כ הם ב', בין קדש לחול ובין קדש לקוה\"ק. ולהבין זה צ\"ל פי' ל' שם הוי', דהנה ש' אלקי' הוא ל' דיין, ושם אל הוא ל' בעל יכולת, וש' שדי שאמר לעולמו די, אבל ש' הוי' אין לו פי'<sup data-n=\"439\">6</sup>. והיינו כי ש' הוי' הוא מורה על התהוות<sup data-n=\"440\">7</sup>, כי הוי' הוא מקור כל ההויות, שכדי שיתהוה יש מאין זהו ע\"י ש' הוי' דוקא, כי בחי' השתלשלו' הוא בחי' עילה ועלול אבל שיתהוה הבריאה יש מאין בראתיו יצרתיו אף עשיתיו זהו ע\"י שם הוי' דוקא. וזהו היו\"ד של שם הוי' שהוא בחי' צמצום נקודה חדא, שכדי שיהי' בחי' התהוות יש מאין מאתו ית' זהו ע\"י צמצום דוקא, ואח\"כ ה' בחי' התפשטות, וא\"ו המשכה<sup data-n=\"441\">8</sup> להיות אח\"כ בחי' ה' אחרונה בהבראם בה' בראם, ולכן נמצא בכללות העולם ד' בחי' דצח\"ם נגד ד' אותיות דש' הוי'. והנה אע\"פ שש' הוי' מקור לעולמות אעפ\"כ הוא קדוש ומובדל, שלא כמו שהנשמה מחי' את הגוף הקב\"ה ממלא את העולם, שהנשמה מתלבשת בגוף ומתפעלת ממקרי הגוף<sup data-n=\"442\">9</sup>, אבל ש' הוי' הוא קדוש ומובדל, אבל מ\"מ ש' הוי' הוא מקור כל ההויות כו' כנ\"ל, וזהו בחי' ש' הוי' דלתתא. אבל בחי' ש' הוי' דלעילא אינו שייך לעולמות כלל, שהוא בחי' ש' הוי' כמו שהוא כלול בעצמותו, וכמו באדם הנה הדבור הוא המקור להתגלות לזולתו שיעשה הדבר ההוא, וכדי שיוכל לבוא בדבור צ\"ל תחלה במחשבה כו', ועד\"ז הוא ענין ש' הוי' דלעילא שהוא כלול בעצמותו, והיינו משארז\"ל עד שלא נברא העולם",[["436","3","<b>דהנה כתי' ויקרא ה' ה'. . שני שמות הוי' ופסיק טעמא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370277\" data-slug=\"torah-or\" data-id=\"3901370277\">תו\"א בשלח סא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370372\" data-slug=\"torah-or\" data-id=\"3901370372\">תצוה פג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">פד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380546\" data-slug=\"likkutei-torah\" data-id=\"4001380546\">לקו\"ת חוקת נז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380955\" data-slug=\"likkutei-torah\" data-id=\"4001380955\">דרושים לר\"ה נט, א</a>. מאמרי אדה\"ז תקס\"ו ע' קמג. ובארוכה תו\"ח שמות (כת\"י הר\"ש סופר) תקנז, א ואילך. סה\"מ תרל\"ב ח\"א ע' קכז. וע' קל. תרמ\"ד (הוצאת תשס\"ב) ע' שמז ואילך. תרנ\"ד ע' רחצ ואילך. סה\"מ מלוקט ח\"ב ע' רלב. וראה עוד בהנסמן ע\"ז באוה\"ת וארא שם ע' ב'תקסד."],["437","4","<b>ברקיע נא' ב' הבדלות. . ויהי מבדיל כו' ואח\"כ ויעש אלקי'. . ויבדל</b>: ראה בארוכה לקו\"ת ואתחנן יא, ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע רמד ואילך. ח\"ב ע' תקטז ואילך [ובהנסמן בהמ\"מ לשם]. אוה\"ת ואתחנן ע' ריח ואילך."],["438","5","<b>ב' הבדלות. . והבדילה הפרוכת. . הפרסא שבין קדש לחול</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך לך יב, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370056\" data-slug=\"torah-or\" data-id=\"3901370056\">יג, א</a>. סידור עם דא\"ח קמה, א ואילך. סה\"מ תרכ\"ו ע' כו. תרל\"ב ח\"א ע' מח. לעיל ד\"ה כרמי גו' האלף לך שלמה. וש\"נ."],["439","6","<b>שם הוי' אין לו פי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460022\" data-slug=\"or-hatorah-hb\" data-id=\"8316460022\">אוה\"ת יתרו ע' תתלז</a>. סה\"מ תרס\"ח ע' קצא. ובכ\"מ."],["440","7","<b>ש' הוי' הוא מורה על התהוות</b>: ראה שעהיוה\"א פ\"ד (עט, רע\"א). ובכ\"מ. [וראה במקומות שנסמנו בהערה שלפנ\"ז]."],["441","8","<b>ש' הוי'. . היו\"ד. . צמצום. . ה' בחי' התפשטות וא\"ו המשכה</b>: ראה בכ\"ז לקו\"ת דרושים לשמע\"צ צב, ד. ובארוכה תו\"ח שמות (כת\"י הר\"ש סופר) רט, א ואילך. סה\"מ תרכ\"ט ע' קכו. תרנ\"ו ע' תרנ-נא. המשך תרס\"ו ע' רז ואילך. ועוד."],["442","9","<b>שהנשמה מתלבשת בגוף ומתפעלת ממקרי הגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, ב</a>). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a>. מאמרי אדה\"ז תקס\"ו ע' ל. ובכ\"מ."]]],[2000460198,"הי' הוא ושמו בלבד שהוא בחי' כשעלה ברצונו להתהוות עי\"ז נתהוה, אבל עדיין הוא כלול בעצמותו וזהו הוא ושמו אחד<sup data-n=\"443\">10</sup> כו'. וזהו ההפרש בין האבות למ\"ת, שהאבות הגם שנא' בהם ש' הוי', אבל הוא בחי' ש' הוי' שהוא מקור להתהוות העולמות, אבל שמי הוי' שהוא כלול בעצמותו לא נודעתי להם ולכן נא' נודעתי ולא הודעתי, כי ע\"פ הדקדוק הי' צ\"ל הודעתי, ונא' נודעתי לפי שהוא ושמו א'<sup data-n=\"444\">11</sup> שהוא כמו שהוא כלול בעצמותו. אבל במ\"ת נא' לכן אמור לבנ\"י אני הוי'<sup data-n=\"445\">12</sup> בחי' ש' הוי' דלעילא כו'.\n<b>ולהבין</b> מפני מה לא נתראה אל האבות כ\"א בש' הוי' דלתתא, הנה כתי' ביעקב עם לבן גרתי ופרש\"י ותרי\"ג מצות שמרתי, וכן באברהם ארז\"ל קיים אברהם כל התו' כולה עד שלא ניתנה. ולכאו' צ\"ל איך קיימו המצות<sup data-n=\"446\">13</sup> הלא כמו עד\"מ תפילין שהיא מצוה גדולה הנה בד' פרשיות הם קדש והי' נאמר בהם יצ\"מ, ומאחר שעדיין לא הי' שעבוד מצרים כלל איך קיימו מצות תפילין, ועד\"ז כל המצות.\n<b>אך</b> הנה יובן בהקדם ענין המצות שאנו מקיימי' שהם רמ\"ח פקודין<sup data-n=\"447\">14</sup> רמ\"ח אברי' דמלכא, ופי' ל' אברים הלא אין לו דמות הגוף ולא גוף, והיינו שאברים הם כלים בחי' אדם, שכמו שאנו רואי' באדם שבד\"כ הוא ג' בחי' ראש וגוף ורגל, ראש הוא בחי' מוחין, והגוף הוא בחי' חג\"ת, ורגל בחי' נה\"י, ובד\"פ נחלק לרמ\"ח אברי', עד\"ז יובן למעלה בבחי' אדם כי בצלם אלקי' עשה את האדם שהם ג\"כ ג' בחי' חב\"ד חג\"ת נה\"י. ובד\"פ הנה ט' ספי' דז\"א ט' פעמים ט' עולה פ\"א וראש תוך סוף הם רמ\"ג וה' חסדים המגדילי' הם רמ\"ח, וע\"י רמ\"ח פקודין ממשיכי' בחי' רמ\"ח אברין דמלכא. והאבות ע\"י שהיו תמיד בבחי' מרכבה בבחי' ביטול המשיכו ג\"כ בחי' אלו, וכמו שהחיות נושאו' את הכסא ועל דמות הכסא דמות כמראה אדם, שע\"י הביטול שלהם הם מרכבה לבחי' אדם. אך הנה פי' דמות כמראה אדם שהוא רק דמות כמראה אדם ולא בחי' אדם, אבל האבות ע\"י הביטול שלהם הן הן המרכבתא עילאה<sup data-n=\"448\">15</sup>, שהם מרכבה לבחי' אדם העליון ממש ע\"י הביטול שלהם במס\"נ. וזהו בעשרה נסיונות נתנסה אברהם נגד עשר בחי' הנפש, שהי' בטל בכל עשר בחינותיו, ועי\"ז",[["443","10","<b>משארז\"ל עד שלא נברא העולם הי' הוא ושמו בלבד. . וזהו הוא ושמו אחד</b>: בשולי הגליון נרשם בגוכי\"ק: הוא ר\"ת הוא ושמו אחד."],["444","11","<b>נא' נודעתי ולא הודעתי. . שהוא ושמו א'</b>: ראה אוה\"ת וארא שם ע' ב'תקסג בשם רבינו בחיי (עה\"פ). וראה ד\"ה עיר קטנה תרנ\"ב שם: ל' הודעתי שייך רק על בחי' גילויים, אבל על עצמות אינו שייך ל' הודעתי כ\"א נודעתי. וראה אוה\"ת וארא שם (כרך ח) ע' ב'תתצג."],["445","12","<b>אבל במ\"ת נא' לכן אמור לבנ\"י אני הוי'</b>: ראה בארוכה לעיל בהמאמר שלפנ\"ז ד\"ה החודש הזה לכם. וש\"נ."],["446","13","<b>קיים אברהם כל התו'. . איך קיימו המצות</b>: בכ\"ז ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370051\" data-slug=\"torah-or\" data-id=\"3901370051\">תו\"א לך לך יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370304\" data-slug=\"torah-or\" data-id=\"3901370304\">יתרו סח, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380358\" data-slug=\"likkutei-torah\" data-id=\"4001380358\">לקו\"ת במדבר יב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380465\" data-slug=\"likkutei-torah\" data-id=\"4001380465\">שלח לח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381166\" data-slug=\"likkutei-torah\" data-id=\"4001381166\">שה\"ש ט, סע\"ב</a>. סה\"מ תרכ\"ז ע' י ואילך. תרכ\"ט ע' רכא ואילך."],["447","14","<b>אך הנה יובן בהקדם ענין המצות. . רמ\"ח פקודין</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370306\" data-slug=\"torah-or\" data-id=\"3901370306\">תו\"א יתרו סח, ג</a>-ד."],["448","15","<b>שהחיות נושאות את הכסא. . רק דמות. . האבות. . המרכבתא עילאה</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370316\" data-slug=\"torah-or\" data-id=\"3901370316\">תו\"א יתרו עא, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370321\" data-slug=\"torah-or\" data-id=\"3901370321\">עב, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370323\" data-slug=\"torah-or\" data-id=\"3901370323\">עב, ד</a> ואילך. סה\"מ תרל\"ב ח\"א ע' יב ואילך [ובהנסמן שם בתחילת המאמר]. וע' טו ואילך."]]],[2000460199,"המשיך בחי' ע\"ס דאצי' בחי' אדם, שאצי' אינו כמו בריאה, שעולם הבריאה היא בריאה יש מאין, אבל אצי' הוא הפרשת הארה<sup data-n=\"449\">16</sup> בחי' אדם, וע\"י הביטול בבחי' מרכבה המשיכו בחי' אצי'. ובדרך פרט הנה אברהם הי' מרכבה למדת החסד, ויצחק מדת הגבורה כמ\"ש ופחד יצחק, ויעקב הי' כלול משניהם. וזהו מ\"ש כי יעקב בחר לו י\"ה ישראל לסגולתו, פי' ישראל לסגולתו כי מה שממשיכי' נש\"י ע\"י המצות הוא בדרך סגולה כמ\"ש והייתם לי סגולה, כמו שענין הסגולה שאין יודעי' איך פועלת פעולתה<sup data-n=\"450\">17</sup>, כמ\"כ ע\"י המצות דמניחי' תפילין נמשך עי\"ז ד' מוחין הגם שאינו מובן, ולכן נק' בשם סגולה. אבל האבות הן הן המרכבה שהיו בטלי' אליו ית' בבחי' עבודה כו', וזהו כי יעקב בחר לו י\"ה ויש בזה ב' פי'<sup data-n=\"451\">18</sup>, הא' שיעקב בחר לו י\"ה, והב' שי\"ה בחר ליעקב כו'.\n<b>אך</b> הנה עכ\"ז מאחר שעבודת האבות הי' מצד בחי' הביטול שלהם לבד לכן לא המשיכו כ\"א בחי' ש' הוי' שהוא מקור להתהוות, כי ביטול הנברא אינו יכול להגיע כ\"א לשרש התהוות הנבראי'<sup data-n=\"452\">19</sup>, אבל במ\"ת ע\"י המצות גשמיות המשיכו מבחי' ש' הוי' דלעילא. וזהו מתן תורה שבחי' זה הוא בבחי' מתנה<sup data-n=\"453\">20</sup>. וגם כי עשי' לעילא, שדוקא ע\"י עשי' גשמי' ממשיכי' ממקום גבוה יותר וכמ\"ש וה' פקד את שרה ויעש ה' לשרה, פי' וה' פקד וה' הוא ובית דינו, אבל ויעש ה'<sup data-n=\"454\">21</sup> שהעשי' הוא בחי' איהו בלחודוהי, וכמו\"כ לע\"ל נא' עדן עין לא ראתה אלקי' זולתך יעשה כו' יעשה דוקא, כי עשי' לעילא, וכמו עד\"מ באדם הנה העיקר הוא המעשה, שהדבור אינו עדיין שלימות הענין, אבל כשעושה איזה דבר הלא דבר הוא, ועד\"ז יובן למעלה שע\"י עשיית המצות גשמיי' עי\"ז דוקא ממשיכי' מבחי' ש' הוי' דלעילא שלמעלה מבחי' ש' הוי' שמקור להתהוות כו'.\n<b>ולהבין</b> כ\"ז בתוס' ביאור, הנה כתי' (תלים קי\"ג א') הללוי' הללו עבדי הוי' הללו את שם הוי', וכהנה רבות, ופעם נא' מי כמוכה כו' נורא תהלות, פי' שיראי' להללו<sup data-n=\"455\">22</sup> כו'. אך הענין הוא, דהנה פי' ל' הלל יש בו ב' פירושי', הא' ל' הלל",[["449","16","<b>שעולם הבריאה היא בריאה יש מאין אבל אצי' הוא הפרשת הארה</b>: ראה סה\"מ תרל\"ב ח\"א ע' מב. וש\"נ. תרל\"ג ח\"ב ע' תקב ואילך. וש\"נ."],["450","17","<b>הסגולה שאין יודעי' איך פועלת פעולתה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381180\" data-slug=\"likkutei-torah\" data-id=\"4001381180\">לקו\"ת שה\"ש יב, ד</a>."],["451","18","<b>כי יעקב בחר לו י\"ה ויש בזה ב' פי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450598\" data-slug=\"or-hatorah-hb\" data-id=\"8316450598\">אוה\"ת תבוא ע' תתרסח</a>."],["452","19","<b>ביטול הנברא אינו יכול להגיע כ\"א לשרש התהוות הנבראי'</b>: ראה סה\"מ תרכ\"ט ע' ריא. תרל\"ב ח\"א ע' קיז. וש\"נ."],["453","20","<b>מתן תורה. . בבחי' מתנה</b>: ראה בארוכה אוה\"ת תשא ע' א'תתקסו ואילך. סה\"מ תרכ\"ז ע' קס ואילך. וש\"נ."],["454","21","<b>עשי' לעילא. . וכמ\"ש וה' פקד. . אבל ויעש ה'</b>: ראה בכ\"ז בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' כה ואילך. על מארז\"ל ע' קפט ואילך. וע' קצט ואילך. ביאוה\"ז לאדהאמ\"צ יא, ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490169\" data-slug=\"or-hatorah-hb\" data-id=\"8316490169\">אוה\"ת וירא (כרך ד) תשנד, א</a> ואילך."],["455","22","<b>כתי'. . הללוי' הללו עבדי הוי'. . ופעם נא'. . נורא תהלות פי' שיראים להללו</b>: ראה בכ\"ז בארוכה אוה\"ת בשלח ע' תתקמח-ט. וע' תקנג ואילך. סה\"מ תרכ\"ו ס\"ע יח-ט. וע' נו. תרכ\"ז ע' תפח."]]],[2000460200,"ושבח, והב' ל' אור מל' בהילו נרו<sup data-n=\"456\">23</sup> עלי ראשי, וב' הפירושי' אמת, שע\"י ההילול והשבח עי\"ז ממשיכי' האור, כמו עד\"מ באדם שהוא חכם גדול הנה חכמתו היא בהעלם וע\"י שמשבחי' אותו יוצא מהעלם אל הגילוי<sup data-n=\"457\">24</sup>, ועד\"ז במדות מי שהוא חסדן ורחמן שמדות אלו הם בהעלם אצלו, וע\"י ההילול ושבח יצא מדותיו מהעלם אל הגילוי. ועד\"ז יובן למעלה ג\"כ, רק כי באדם הנה יש אצלו מדות רק שהם בהעלם, אבל למעלה הנה הוא ית' לאו מכל אינון מדות כלל, וזהו מ\"ש וידבר אלקי' אל משה ויאמר אליו אני הוי', שהוי' ואלקי' הם בחי' מדה\"ד ומדה\"ר, אבל עצמותו לאו מכל אינון מדות איהו כלל, וע\"י ההילול ושבח שמשבחי' אותו, מה רב טובך כו', חנון ורחום ה', עי\"ז ממשיכי' אוא\"ס בבחי' מדות כו'. וזהו הללוי' הללו עבדי ה' הללו ש' הוי', מתחלה הללוי' להמשיך בחי' י\"ה, ואח\"כ הללו שם הוי' בחי' ו\"ה<sup data-n=\"458\">25</sup>, ופי' עבדי הוי' שההילול ושבח צ\"ל בבחי' עבודה. אמנם כ\"ז הוא בש' הוי' דסדר השתלשלו', אבל לגבי בחי' ש' הוי' שלמעלה מסדר השתל' ע\"ז נא' נורא תהלות לפי שהוא למעלה מסדר השתלשלו', רק בבחי' הודאה יכולים להודות גם לבחי' ש' הוי' דלעילא. וזהו שתקנו חנוכה בהלל והודאה<sup data-n=\"459\">26</sup>, הלל הוא לגבי בחי' ש' הוי' דלתתא, והודאה הוא לגבי בחי' ש' הוי' דלעילא.\n<b>וזהו</b> וארא אל אברהם אל יצחק ואל יעקב באל שדי, פי' הגם שנא' באבות ש' הוי' אבל הנה הוא באל שדי שאמר לעולמו די דהיינו בחי' ש' הוי' שמקור להתהוות הנבראי' [ומה שנז' ש' הוי' אצל אברהם, ש' הוי' בשעה שהי' שמו אברם היינו קודם המילה שנתגלה אליו בשם שדי כמ\"ש אני אל שדי התהלך כו', צ\"ל שקודם המילה הי' ג\"כ ע\"י שם שדי כפי הפירוש שדי שאמר לעולמו די כמ\"ש כאן, אבל ע\"י המילה זהו כפי שפירשו רז\"ל בש' שדי שדי באלקותי לכל ברי', וכמ\"ש במ\"א<sup data-n=\"460\">27</sup> מזה שזהו כענין עד שיבלו שפתותיכם מלומר די כו']<sup data-n=\"461\">28</sup> אבל שמי הוי' דלעילא שלמעלה מסדר השתלשלות לא נודעתי להם כ\"א במ\"ת בקיום המצות גשמי' דוקא ממשיכי' ש' הוי' דלעילא כנ\"ל שעשי' לעילא.",[["456","23","<b>ל' הלל יש בו ב' פירושי' הא' ל' הלל ושבח והב' ל' אור מל' בהילו נרו</b>: בהבא לקמן עד סוף הפיסקא — ראה תו\"א וישב ל, א. מאמרי אדה\"ז תקס\"ח ח\"א ע' שע. שם ח\"ב ע' תש ואילך. שערי אורה שער החנוכה יח, א ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480207\" data-slug=\"or-hatorah-hb\" data-id=\"8316480207\">אוה\"ת חנוכה (כרך ה</a>) תתקלה, א ואילך. יהל אור לתהלים ע' תקנח ואילך. וע' תרצג."],["457","24","<b>שע\"י ההילול והשבח. . ממשיכי' האור. . וע\"י שמשבחי' אותו יוצא מהעלם אל הגילוי</b>: ראה בכ\"ז הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370451\" data-slug=\"torah-or\" data-id=\"3901370451\">תו\"א ויחי קב, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370457\" data-slug=\"torah-or\" data-id=\"3901370457\">קג, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380135\" data-slug=\"likkutei-torah\" data-id=\"4001380135\">לקו\"ת צו יד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380204\" data-slug=\"likkutei-torah\" data-id=\"4001380204\">קדושים כט, ג</a>. דרך מצותיך קיח, א ואילך. קמח, א ואילך. סה\"מ תרל\"ב ח\"א ע' קסז. ח\"ב ע' שסט. שעב. [ובדרושים שנסמנו בהערה שלפנ\"ז]."],["458","25","<b>הללוי' להמשיך בחי' י\"ה. . הללו שם הוי' בחי' ו\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370139\" data-slug=\"torah-or\" data-id=\"3901370139\">תו\"א וישב ל, א</a> שם. ובארוכה בשערי אורה שם יט, א."],["459","26","<b>וזהו שתקנו חנוכה בהלל והודאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370139\" data-slug=\"torah-or\" data-id=\"3901370139\">תו\"א וישב ל, א</a> שם. שערי אורה שם כא, ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480216\" data-slug=\"or-hatorah-hb\" data-id=\"8316480216\">אוה\"ת חנוכה (כרך ה) שם תתקלט, ב</a>. תתקמ, א."],["460","27","<b>שם שדי כפי הפירוש. . שאמר לעולמו די. . אבל ע\"י המילה. . שדי באלקותי. . וכמ\"ש במ\"א</b>: ראה בארוכה סה\"מ תר\"ל ע' סא ואילך. עטר\"ת ע' קפח ואילך. תרפ\"ד ע' קצ ואילך. סה\"מ מלוקט ח\"ה ע' קלז ואילך."],["461","28","<b>ומה שנז'. . מלומר די כו']</b>: הגה\"ה זו נרשמה בגוכתי\"ק בצידי הגליון, וכנראה שייכת לכאן."]]],[2000460201,"<b>וזהו</b> מ\"ש רז\"ל במד\"ר ע\"פ לריח שמניך טובים שמן תורק שמך, כל המצות שעשו לפניך האבות ריחות היו אבל אנו שמן תורק שמך רמ\"ח מ\"ע ושס\"ה מל\"ת, פי' שהמצות שעשו האבות ריחות היו כמו שהריח אינו גוף הדבר, ולכן באיסורי מאכל ריחא לאו מלתא היא, אבל אנו שמן תורק שמך פי' ל' תורק הוא ל' דבר המריק שמריקין מכלי אל כלי, והיינו שע\"י רמ\"ח מ\"ע ושס\"ה ל\"ת ממשיכי' מבחי' ש' הוי' שהוא כלול בעצמותו כו'."]]});
